/**
 * The Help window of Studio: one section for every menu, in the seven languages, built the same way as the node panels' help (a list of
 * sections on the left, the chosen one on the right). Every section is [en, es, de, fr, it, ja, zh] for its title and for its body; a blank
 * line in a body starts a new paragraph.
 * Copyright (C) 2026 JuanenRac (Electro Hobby 3D)
 * SPDX-License-Identifier: GPL-3.0-or-later
 */
import type { Locale } from "./i18n";
import { HELP_PT_A } from "./helpPtA";
import { HELP_PT_B } from "./helpPtB";

type Seven = readonly [string, string, string, string, string, string, string];
export type HelpSection = { id: string; title: Seven; body: Seven };
const order: readonly Locale[] = ["en", "es", "de", "fr", "it", "ja", "zh"];

export const HELP_SECTIONS: readonly HelpSection[] = [
  { id: "start",
    title: ["Getting started", "Primeros pasos", "Erste Schritte", "Premiers pas", "Per iniziare", "はじめに", "快速入门"],
    body: [
      "Studio is the console of A.R.M.O.R.: from here you watch the perimeter, answer alarms, see the cameras, the solar energy, the electrical installation and the network, and you design the site and its alarm.\n\nThe menu on the left has the screens in groups: Monitor (the overview, the weather and the alarms), Security (the alarm panels, the cameras, the radar, the recordings and the history), Energy (inverters, batteries and the electrical installation), House and network (devices, automations and the network), Design (the site, alarm, electrical and network designers) and Administration. Click the title of a group to fold it or unfold it; Studio remembers which ones you folded, and the group of the screen you are on never hides it. The arrow at the top folds the whole menu to icons. The top bar shows the screen you are on, the revision of the server, the armed / disarmed button, full screen, Help (this window) and About.\n\nThe big button at the top right arms or disarms the whole system. Disarming asks for your PIN (Configuration > Users); a duress PIN disarms as well but silently raises a critical alarm. While the system is armed, an intrusion, an open door or a camera that stops answering raises an alarm; disarming closes the ones that depend on the mode.\n\nPausing the pointer over any button, field or menu entry shows a short explanation of what it does. The language and the look of the console are in Configuration.",
      "Studio es la consola de A.R.M.O.R.: desde aquí vigilas el perímetro, atiendes las alarmas, ves las cámaras, la energía solar, la instalación eléctrica y la red, y diseñas el sitio y su alarma.\n\nEl menú de la izquierda tiene las pantallas en grupos: Vigilancia (el resumen, el tiempo y las alarmas), Seguridad (las centrales de alarma, las cámaras, el radar, las grabaciones y el historial), Energía (inversores, baterías y la instalación eléctrica), Casa y red (dispositivos, automatizaciones y la red), Diseño (los diseñadores del sitio, de la alarma, eléctrico y de red) y Administración. Pulsa el título de un grupo para plegarlo o desplegarlo; Studio recuerda cuáles has plegado, y el grupo de la pantalla en la que estás nunca la oculta. La flecha de arriba pliega todo el menú a iconos. La barra superior muestra la pantalla actual, la revisión del servidor, el botón armado / desarmado, la pantalla completa, la Ayuda (esta ventana) y Acerca de.\n\nEl botón grande de arriba a la derecha arma o desarma todo el sistema. Desarmar pide tu PIN (Configuración > Usuarios); un PIN de coacción también desarma pero levanta en silencio una alarma crítica. Con el sistema armado, una intrusión, una puerta abierta o una cámara que deja de responder levanta una alarma; al desarmar se cierran las que dependen del modo.\n\nSi dejas el puntero sobre un botón, campo o entrada del menú aparece una breve explicación de lo que hace. El idioma y el aspecto de la consola están en Configuración.",
      "Studio ist die Konsole von A.R.M.O.R.: Hier überwachen Sie den Perimeter, beantworten Alarme, sehen Kameras, Solarenergie, Elektroanlage und Netz und entwerfen den Standort und seine Alarmanlage.\n\nDas Menü links gliedert die Bildschirme in Gruppen: Überwachung (Übersicht, Wetter und Alarme), Sicherheit (Alarmzentralen, Kameras, Radar, Aufnahmen und Verlauf), Energie (Wechselrichter, Batterien und Elektroanlage), Haus und Netzwerk (Geräte, Automatisierungen und das Netzwerk), Entwurf (die Planer für Standort, Alarm, Elektrik und Netzwerk) und Verwaltung. Ein Klick auf den Titel einer Gruppe klappt sie ein oder aus; Studio merkt sich, welche eingeklappt sind, und die Gruppe des aktuellen Bildschirms verbirgt diesen nie. Der Pfeil oben klappt das ganze Menü auf Symbole zusammen. Die obere Leiste zeigt den aktuellen Bildschirm, die Revision des Servers, die Schaltfläche scharf / unscharf, Vollbild, Hilfe (dieses Fenster) und Info.\n\nDie große Schaltfläche oben rechts schaltet das ganze System scharf oder unscharf. Das Unscharfschalten verlangt Ihre PIN (Konfiguration > Benutzer); eine Zwangs-PIN schaltet ebenfalls unscharf, löst aber still einen kritischen Alarm aus. Bei scharfem System löst ein Einbruch, eine offene Tür oder eine Kamera, die nicht mehr antwortet, einen Alarm aus.\n\nHalten Sie den Zeiger über eine Schaltfläche, ein Feld oder einen Menüeintrag, erscheint eine kurze Erklärung. Sprache und Aussehen der Konsole stehen in der Konfiguration.",
      "Studio est la console d'A.R.M.O.R. : d'ici vous surveillez le périmètre, répondez aux alarmes, voyez les caméras, l'énergie solaire, l'installation électrique et le réseau, et vous concevez le site et son alarme.\n\nLe menu de gauche range les écrans en groupes : Surveillance (l'aperçu, la météo et les alarmes), Sécurité (les centrales d'alarme, les caméras, le radar, les enregistrements et l'historique), Énergie (onduleurs, batteries et installation électrique), Maison et réseau (appareils, automatisations et le réseau), Conception (les concepteurs du site, de l'alarme, électrique et réseau) et Administration. Cliquez sur le titre d'un groupe pour le replier ou le déplier ; Studio retient ceux que vous avez repliés, et le groupe de l'écran où vous êtes ne le cache jamais. La flèche en haut replie tout le menu en icônes. La barre du haut montre l'écran actuel, la révision du serveur, le bouton armé / désarmé, le plein écran, l'Aide (cette fenêtre) et À propos.\n\nLe grand bouton en haut à droite arme ou désarme tout le système. Désarmer demande votre code PIN (Configuration > Utilisateurs) ; un code de contrainte désarme aussi mais déclenche en silence une alarme critique. Système armé, une intrusion, une porte ouverte ou une caméra qui ne répond plus déclenche une alarme.\n\nLaisser le pointeur sur un bouton, un champ ou une entrée du menu affiche une courte explication. La langue et l'apparence de la console sont dans Configuration.",
      "Studio è la console di A.R.M.O.R.: da qui controlli il perimetro, rispondi agli allarmi, vedi le telecamere, l'energia solare, l'impianto elettrico e la rete, e progetti il sito e il suo allarme.\n\nIl menu a sinistra raggruppa le schermate: Sorveglianza (panoramica, meteo e allarmi), Sicurezza (centrali di allarme, telecamere, radar, registrazioni e storico), Energia (inverter, batterie e impianto elettrico), Casa e rete (dispositivi, automazioni e la rete), Progetto (i progettisti del sito, dell'allarme, elettrico e di rete) e Amministrazione. Clicca il titolo di un gruppo per comprimerlo o espanderlo; Studio ricorda quali hai compresso, e il gruppo della schermata in cui sei non la nasconde mai. La freccia in alto riduce tutto il menu a icone. La barra superiore mostra la schermata attuale, la revisione del server, il pulsante attivo / disattivo, lo schermo intero, la Guida (questa finestra) e Informazioni.\n\nIl grande pulsante in alto a destra attiva o disattiva tutto il sistema. Disattivare chiede il tuo PIN (Configurazione > Utenti); un PIN di coercizione disattiva comunque ma genera in silenzio un allarme critico. A sistema attivo, un'intrusione, una porta aperta o una telecamera che non risponde più genera un allarme.\n\nFermando il puntatore su un pulsante, un campo o una voce del menu compare una breve spiegazione. La lingua e l'aspetto della console sono in Configurazione.",
      "Studio は A.R.M.O.R. のコンソールです。ここから境界の監視、アラームへの対応、カメラ・太陽光・電気設備・ネットワークの確認、サイトと警報の設計ができます。\n\n左のメニューは画面をグループに分けています：監視（概要・天気・アラーム）、セキュリティ（警報制御盤・カメラ・レーダー・録画・履歴）、エネルギー（インバーター・バッテリー・電気設備）、家とネットワーク（デバイス・自動化・ネットワーク）、設計（サイト・警報・電気・ネットワークの設計）、管理。グループ名をクリックすると折りたたみ／展開でき、折りたたんだ状態は記憶されます。いま開いている画面のグループは隠れません。上部の矢印でメニュー全体をアイコン表示にできます。上部バーには現在の画面、サーバーのリビジョン、警戒／解除ボタン、全画面、ヘルプ（このウィンドウ）、情報が表示されます。\n\n右上の大きなボタンでシステム全体を警戒／解除します。解除には PIN が必要です（設定 > ユーザー）。強要 PIN でも解除できますが、静かに重大アラームを発報します。警戒中は、侵入、開いたドア、応答しなくなったカメラがアラームになります。\n\nボタン、入力欄、メニュー項目にポインターを重ねると短い説明が表示されます。言語と外観は設定にあります。",
      "Studio 是 A.R.M.O.R. 的控制台：在这里监视周界、处理报警、查看摄像头、太阳能、电气设施和网络，并设计场地及其报警系统。\n\n左侧菜单把界面分成几组：监控（概览、天气、报警）、安防（报警主机、摄像头、雷达、录像和历史）、能源（逆变器、电池和电气设施）、住宅与网络（设备、自动化和网络）、设计（场地、报警、电气和网络设计器）以及管理。点击分组标题可折叠或展开，Studio 会记住折叠状态，而当前所在界面的分组不会被隐藏。顶部箭头可把整个菜单折叠为图标。顶部栏显示当前界面、服务器修订号、布防/撤防按钮、全屏、帮助（本窗口）和关于。\n\n右上角的大按钮用于对整个系统布防或撤防。撤防需要输入您的 PIN（设置 > 用户）；胁迫 PIN 同样可以撤防，但会悄悄触发严重报警。布防期间，入侵、门被打开或摄像头不再响应都会触发报警。\n\n把指针停在任何按钮、字段或菜单项上，会显示简短说明。语言和外观在设置中。",
    ] },
  { id: "overview",
    title: ["Overview", "Resumen", "Übersicht", "Aperçu", "Panoramica", "概要", "概览"],
    body: [
      "The first screen. It gathers, in cards, what deserves a look: the state of the perimeter (armed or disarmed), the field nodes that are online, the active tracks the radars see, the cameras that are enabled, and the alarms waiting for a person.\n\n\"Needs attention\" lists the things that ask for someone: unseen alarms and nodes with problems; each opens its screen. \"Recent activity\" is the latest events, newest first. \"Quick actions\" jump to the cameras, the site designer or the form to add a device.\n\nThe small live map shows the site with the radars' targets as they move. If the server cannot be reached, the screen says so and shows demonstration data, clearly marked as such.",
      "La primera pantalla. Reúne en tarjetas lo que merece una mirada: el estado del perímetro (armado o desarmado), los nodos de campo en línea, los objetivos activos que ven los radares, las cámaras habilitadas y las alarmas que esperan a una persona.\n\n\"Requiere atención\" lista lo que pide a alguien: alarmas sin ver y nodos con problemas; cada una abre su pantalla. \"Actividad reciente\" son los últimos eventos, el más nuevo primero. Las \"Acciones rápidas\" saltan a las cámaras, al diseñador del sitio o al formulario para añadir un dispositivo.\n\nEl pequeño mapa en vivo muestra el sitio con los objetivos de los radares moviéndose. Si no se puede llegar al servidor, la pantalla lo dice y muestra datos de demostración, claramente marcados como tales.",
      "Der erste Bildschirm. Er sammelt in Karten, was einen Blick verdient: Zustand des Perimeters (scharf oder unscharf), Feldknoten online, aktive Ziele der Radare, aktivierte Kameras und Alarme, die auf eine Person warten.\n\n„Braucht Aufmerksamkeit“ listet, was jemanden verlangt: ungesehene Alarme und Knoten mit Problemen; jeder Eintrag öffnet seinen Bildschirm. „Letzte Aktivität“ zeigt die jüngsten Ereignisse, neueste zuerst. Die „Schnellaktionen“ springen zu den Kameras, zum Standort-Designer oder zum Formular für ein neues Gerät.\n\nDie kleine Live-Karte zeigt den Standort mit den bewegten Zielen der Radare. Ist der Server nicht erreichbar, sagt der Bildschirm das und zeigt Demodaten, klar als solche gekennzeichnet.",
      "Le premier écran. Il réunit en cartes ce qui mérite un coup d'œil : l'état du périmètre (armé ou désarmé), les nœuds de terrain en ligne, les pistes actives vues par les radars, les caméras activées et les alarmes en attente d'une personne.\n\n« Demande de l'attention » liste ce qui réclame quelqu'un : alarmes non vues et nœuds en difficulté ; chacun ouvre son écran. « Activité récente » donne les derniers événements, le plus récent d'abord. Les « Actions rapides » mènent aux caméras, au concepteur de site ou au formulaire d'ajout d'un appareil.\n\nLa petite carte en direct montre le site avec les cibles des radars en mouvement. Si le serveur est injoignable, l'écran le dit et affiche des données de démonstration, clairement signalées.",
      "La prima schermata. Raccoglie in schede ciò che merita uno sguardo: lo stato del perimetro (armato o disarmato), i nodi di campo online, le tracce attive viste dai radar, le telecamere abilitate e gli allarmi in attesa di una persona.\n\n«Richiede attenzione» elenca ciò che chiede qualcuno: allarmi non visti e nodi con problemi; ognuno apre la sua schermata. «Attività recente» sono gli ultimi eventi, il più recente prima. Le «Azioni rapide» portano alle telecamere, alla progettazione del sito o al modulo per aggiungere un dispositivo.\n\nLa piccola mappa dal vivo mostra il sito con i bersagli dei radar in movimento. Se il server non è raggiungibile, la schermata lo dice e mostra dati dimostrativi, chiaramente segnalati.",
      "最初の画面です。注目すべき項目をカードにまとめます：境界の状態（警戒/解除）、オンラインのフィールドノード、レーダーが捉えている対象、有効なカメラ、対応待ちのアラーム。\n\n「要注意」には、人の対応が必要なもの（未確認のアラームや問題のあるノード）が並び、各項目からその画面に移れます。「最近の動き」は最新のイベント（新しい順）です。「クイック操作」はカメラ、サイトデザイナー、機器追加フォームへのショートカットです。\n\n小さなライブマップには、レーダーの対象が動く様子がサイト上に表示されます。サーバーに接続できない場合は、その旨とデモデータ（デモと明記）を表示します。",
      "这是第一个界面，用卡片汇总值得关注的内容：周界状态（布防或撤防）、在线的现场节点、雷达当前跟踪的目标、已启用的摄像头，以及等待人处理的报警。\n\n“需要关注”列出需要人处理的事项：未读报警和有问题的节点，点击可进入相应界面。“最近活动”是最新事件，最新的在前。“快捷操作”可跳转到摄像头、场地设计器或添加设备表单。\n\n小型实时地图显示场地以及雷达目标的移动。若无法连接服务器，界面会说明并显示明确标注的演示数据。",
    ] },
  { id: "weather",
    title: ["Weather", "Tiempo", "Wetter", "Météo", "Meteo", "天気", "天气"],
    body: [
      "The forecast of your place: now, the next 48 hours and the next days, with warnings from the forecast and the air quality.\n\nThe first time, you turn the weather on and choose the place: search a town or city, or type the latitude and longitude yourself. The place is kept in this server. \"Change place\" picks another; \"Turn off and forget the place\" removes it.\n\nThe rain radar plays the last frames of rain (and, if you choose, of clouds from the satellite) over a map. Play and Pause control the animation, the opacity slider lets you see the map below, and \"Center on my place\" recentres the view.\n\nThe weather is read from public services; nothing from your cameras or sensors is sent to them, only the place you chose.",
      "La previsión de tu lugar: ahora, las próximas 48 horas y los próximos días, con los avisos de la previsión y la calidad del aire.\n\nLa primera vez activas el tiempo y eliges el lugar: buscas un pueblo o ciudad, o escribes tú la latitud y la longitud. El lugar se guarda en este servidor. \"Cambiar lugar\" elige otro; \"Apagar y olvidar el lugar\" lo elimina.\n\nEl radar de lluvia reproduce los últimos fotogramas de lluvia (y, si quieres, de nubes del satélite) sobre un mapa. Reproducir y Pausa controlan la animación, el deslizador de opacidad deja ver el mapa de debajo y \"Centrar en mi lugar\" recentra la vista.\n\nEl tiempo se lee de servicios públicos; no se les envía nada de tus cámaras ni sensores, solo el lugar que elegiste.",
      "Die Vorhersage für Ihren Ort: jetzt, die nächsten 48 Stunden und die nächsten Tage, mit Warnungen aus der Vorhersage und der Luftqualität.\n\nBeim ersten Mal schalten Sie das Wetter ein und wählen den Ort: einen Ort suchen oder Breiten- und Längengrad selbst eingeben. Der Ort wird auf diesem Server gespeichert. „Ort ändern“ wählt einen anderen; „Ausschalten und Ort vergessen“ entfernt ihn.\n\nDas Regenradar spielt die letzten Bilder von Regen (und auf Wunsch Wolken vom Satelliten) über einer Karte ab. Abspielen und Pause steuern die Animation, der Deckkraft-Regler lässt die Karte darunter sehen, „Auf meinen Ort zentrieren“ zentriert die Ansicht neu.\n\nDas Wetter stammt von öffentlichen Diensten; von Kameras oder Sensoren wird nichts gesendet, nur der gewählte Ort.",
      "Les prévisions de votre lieu : maintenant, les 48 prochaines heures et les jours suivants, avec les alertes de prévision et la qualité de l'air.\n\nLa première fois, vous activez la météo et choisissez le lieu : cherchez une ville ou saisissez vous-même latitude et longitude. Le lieu est conservé sur ce serveur. « Changer de lieu » en choisit un autre ; « Désactiver et oublier le lieu » le supprime.\n\nLe radar de pluie rejoue les dernières images de pluie (et, si vous voulez, de nuages du satellite) sur une carte. Lecture et Pause commandent l'animation, le curseur d'opacité laisse voir la carte dessous, « Centrer sur mon lieu » recentre la vue.\n\nLa météo vient de services publics ; rien de vos caméras ni capteurs ne leur est envoyé, seulement le lieu choisi.",
      "Le previsioni del tuo luogo: adesso, le prossime 48 ore e i prossimi giorni, con gli avvisi di previsione e la qualità dell'aria.\n\nLa prima volta attivi il meteo e scegli il luogo: cerchi una città o scrivi tu latitudine e longitudine. Il luogo resta in questo server. «Cambia luogo» ne sceglie un altro; «Disattiva e dimentica il luogo» lo elimina.\n\nIl radar della pioggia riproduce gli ultimi fotogrammi di pioggia (e, se vuoi, di nuvole dal satellite) su una mappa. Riproduci e Pausa controllano l'animazione, il cursore di opacità lascia vedere la mappa sotto, «Centra sul mio luogo» ricentra la vista.\n\nIl meteo arriva da servizi pubblici; non viene inviato nulla delle tue telecamere o sensori, solo il luogo scelto.",
      "お住まいの場所の予報：現在、今後 48 時間、今後の数日間、予報の警報、大気質を表示します。\n\n初回は天気機能をオンにして場所を選びます。町や都市を検索するか、緯度と経度を自分で入力します。場所はこのサーバーに保存されます。「場所を変更」で別の場所を選び、「オフにして場所を忘れる」で削除します。\n\n雨雲レーダーは、地図の上に直近の雨（選べば衛星の雲）を再生します。再生/一時停止でアニメーションを操作し、不透明度スライダーで下の地図を見やすくし、「現在地を中心に」で表示を戻します。\n\n天気は公開サービスから取得します。カメラやセンサーの情報は送られず、選んだ場所だけが使われます。",
      "所在地的预报：当前、未来 48 小时和未来几天，以及预报预警和空气质量。\n\n首次使用需开启天气并选择地点：搜索城镇，或自己输入纬度和经度。地点保存在此服务器上。“更改地点”选择另一个地点；“关闭并忘记地点”将其删除。\n\n降雨雷达在地图上播放最近的降雨画面（可选择卫星云图）。播放和暂停控制动画，不透明度滑块可透出下方地图，“以我的位置为中心”会重新居中视图。\n\n天气数据来自公共服务；不会发送摄像头或传感器的任何内容，只发送你选择的地点。",
    ] },
  { id: "alarms",
    title: ["Alarms", "Alarmas", "Alarme", "Alarmes", "Allarmi", "アラーム", "报警"],
    body: [
      "Everything that needs a person right now. An alarm is raised when something goes wrong - an intrusion, smoke, a door opened while armed, a camera or a device that stopped answering, a low battery, an alarm panel that sounds or is tampered with, a new device on the network, a risky open port - and it stays on the list until someone acknowledges it.\n\nA new critical alarm sounds three beeps and, if you allow notifications in the browser (it asks on your first click in Studio), it also appears as a notification when Studio is on another tab. The alarms that were already on the list when you opened Studio are not announced again.\n\nAcknowledge marks one alarm as seen; Acknowledge all marks every alarm that is waiting. An acknowledged alarm leaves the list and is kept in the Record below, whether its cause has ended or not; the whole story stays in History. If its cause is still going on, the same condition reported again does not bring it back: it comes back only after the cause ends and happens again.\n\nDetails shows the facts of an alarm (device, address, MAC, port, numbers). The cross deletes an alarm. \"Mark the device as known\" tells A.R.M.O.R. that a new device is welcome. The filters narrow the list by severity and source, and the search box looks for any text. The big button arms or disarms the system; disarming asks for your PIN.\n\nBefore arming: the button asks the server first and shows what would leave the perimeter blind or noisy - a radar node that does not answer, a silent alarm panel, an open zone, a camera that is down, an open door or window and alarms nobody has seen. If something blocks, the button says \"Arm anyway\"; nothing is armed until you confirm. The tick button in the top bar shows the same check without arming. A new alarm also appears as a pop-up that never blocks the page, with an Acknowledge button and a jump to the right menu; sounds, voice and pop-ups are chosen in Configuration > Preferences. An account of the viewer role only looks and cannot arm.",
      "Todo lo que necesita a una persona ahora mismo. Se levanta una alarma cuando algo va mal - una intrusión, humo, una puerta abierta con el sistema armado, una cámara o un dispositivo que ha dejado de responder, una batería baja, una central de alarma que suena o sufre sabotaje, un dispositivo nuevo en la red, un puerto abierto de riesgo - y se queda en la lista hasta que alguien la reconoce.\n\nUna alarma crítica nueva suena con tres pitidos y, si permites las notificaciones en el navegador (las pide en tu primer clic en Studio), además aparece como notificación aunque Studio esté en otra pestaña. Las alarmas que ya estaban en la lista cuando abriste Studio no se anuncian de nuevo.\n\nReconocer marca una alarma como vista; Reconocer todas marca todas las que esperan. Una alarma reconocida sale de la lista y se guarda en el Registro de abajo, haya terminado su causa o no; toda la historia queda en el Historial. Si su causa sigue, la misma condición informada otra vez no la trae de vuelta: vuelve solo cuando la causa termina y se repite.\n\nDetalles muestra los datos de una alarma (dispositivo, dirección, MAC, puerto, cifras). La cruz borra una alarma. \"Marcar el dispositivo como conocido\" indica a A.R.M.O.R. que un dispositivo nuevo es bienvenido. Los filtros acotan la lista por gravedad y origen, y el buscador busca cualquier texto. El botón grande arma o desarma el sistema; desarmar pide tu PIN.\n\nAntes de armar: el botón pregunta primero al servidor y muestra lo que dejaría el perímetro ciego o ruidoso - un nodo de radar que no responde, una central de alarma muda, una zona abierta, una cámara caída, una puerta o ventana abierta y alarmas que nadie ha visto. Si algo bloquea, el botón dice \"Armar igualmente\"; no se arma nada hasta que confirmes. El botón de la marca en la barra superior muestra la misma comprobación sin armar. Una alarma nueva aparece también como ventana que nunca bloquea la página, con botón Reconocer y salto al menú adecuado; los sonidos, la voz y las ventanas se eligen en Configuración > Preferencias. Una cuenta con rol de observador solo mira y no puede armar.",
      "Alles, was jetzt einen Menschen braucht. Ein Alarm entsteht, wenn etwas schiefgeht - ein Einbruch, Rauch, eine geöffnete Tür bei scharfem System, eine Kamera oder ein Gerät, das nicht mehr antwortet, eine schwache Batterie, eine Alarmzentrale, die ertönt oder sabotiert wird, ein neues Gerät im Netz, ein riskanter offener Port - und bleibt in der Liste, bis ihn jemand quittiert.\n\nEin neuer kritischer Alarm ertönt dreimal und erscheint, wenn Sie Benachrichtigungen im Browser erlauben (sie werden bei Ihrem ersten Klick in Studio erfragt), auch als Benachrichtigung, wenn Studio in einem anderen Tab ist. Alarme, die beim Öffnen von Studio schon in der Liste standen, werden nicht erneut angekündigt.\n\nQuittieren markiert einen Alarm als gesehen; Alle quittieren markiert alle wartenden. Ein quittierter Alarm verlässt die Liste und wird unten im Protokoll aufbewahrt, ob seine Ursache endete oder nicht; die ganze Geschichte bleibt im Verlauf. Dauert die Ursache an, bringt dieselbe erneut gemeldete Bedingung ihn nicht zurück: Er kommt erst wieder, wenn die Ursache endet und erneut auftritt.\n\nDetails zeigt die Fakten eines Alarms (Gerät, Adresse, MAC, Port, Zahlen). Das Kreuz löscht einen Alarm. „Gerät als bekannt markieren“ sagt A.R.M.O.R., dass ein neues Gerät willkommen ist. Die Filter grenzen die Liste nach Schwere und Quelle ein, das Suchfeld sucht beliebigen Text. Die große Schaltfläche schaltet das System scharf oder unscharf; das Unscharfschalten verlangt Ihre PIN.\n\nVor dem Scharfschalten: Die Schaltfläche fragt zuerst den Server und zeigt, was den Perimeter blind oder laut machen würde - einen Radarknoten, der nicht antwortet, eine stumme Alarmzentrale, eine offene Zone, eine ausgefallene Kamera, eine offene Tür oder ein Fenster und Alarme, die niemand gesehen hat. Blockiert etwas, steht dort \"Trotzdem scharfschalten\"; erst nach Ihrer Bestätigung wird scharf geschaltet. Der Haken in der oberen Leiste zeigt dieselbe Prüfung ohne Scharfschalten. Ein neuer Alarm erscheint zudem als Fenster, das die Seite nie blockiert, mit Quittieren-Schaltfläche und Sprung ins passende Menü; Töne, Stimme und Fenster stellen Sie unter Konfiguration > Einstellungen ein. Ein Konto mit der Rolle Betrachter schaut nur und kann nicht scharfschalten.",
      "Tout ce qui demande une personne maintenant. Une alarme est levée quand quelque chose va mal - une intrusion, de la fumée, une porte ouverte système armé, une caméra ou un appareil qui ne répond plus, une batterie faible, une centrale d'alarme qui sonne ou qu'on sabote, un nouvel appareil sur le réseau, un port ouvert risqué - et elle reste dans la liste jusqu'à ce que quelqu'un l'acquitte.\n\nUne nouvelle alarme critique émet trois bips et, si vous autorisez les notifications dans le navigateur (elles sont demandées à votre premier clic dans Studio), apparaît aussi comme notification quand Studio est sur un autre onglet. Les alarmes déjà dans la liste à l'ouverture de Studio ne sont pas annoncées de nouveau.\n\nAcquitter marque une alarme comme vue ; Tout acquitter marque toutes celles qui attendent. Une alarme acquittée quitte la liste et est conservée dans le Registre en dessous, que sa cause ait cessé ou non ; toute l'histoire reste dans l'Historique. Si sa cause continue, la même condition signalée de nouveau ne la ramène pas : elle revient seulement après la fin de la cause et une nouvelle occurrence.\n\nDétails montre les faits d'une alarme (appareil, adresse, MAC, port, chiffres). La croix supprime une alarme. « Marquer l'appareil comme connu » dit à A.R.M.O.R. qu'un nouvel appareil est bienvenu. Les filtres restreignent la liste par gravité et origine, et la recherche cherche n'importe quel texte. Le grand bouton arme ou désarme le système ; désarmer demande votre PIN.\n\nAvant d'armer : le bouton interroge d'abord le serveur et montre ce qui rendrait le périmètre aveugle ou bruyant - un nœud radar qui ne répond pas, une centrale d'alarme muette, une zone ouverte, une caméra en panne, une porte ou fenêtre ouverte et des alarmes que personne n'a vues. Si quelque chose bloque, le bouton dit « Armer quand même » ; rien n'est armé avant votre confirmation. Le bouton coche de la barre du haut montre la même vérification sans armer. Une nouvelle alarme apparaît aussi comme une fenêtre qui ne bloque jamais la page, avec un bouton Acquitter et un saut vers le bon menu ; sons, voix et fenêtres se choisissent dans Configuration > Préférences. Un compte au rôle observateur regarde seulement et ne peut pas armer.",
      "Tutto ciò che richiede una persona adesso. Un allarme scatta quando qualcosa va male - un'intrusione, fumo, una porta aperta a sistema attivo, una telecamera o un dispositivo che non risponde più, una batteria scarica, una centrale di allarme che suona o viene manomessa, un nuovo dispositivo in rete, una porta aperta a rischio - e resta nell'elenco finché qualcuno lo conferma.\n\nUn nuovo allarme critico emette tre segnali acustici e, se consenti le notifiche nel browser (le chiede al tuo primo clic in Studio), compare anche come notifica quando Studio è su un'altra scheda. Gli allarmi già presenti nell'elenco all'apertura di Studio non vengono annunciati di nuovo.\n\nConferma segna un allarme come visto; Conferma tutti segna tutti quelli in attesa. Un allarme confermato esce dall'elenco e resta nel Registro sotto, sia finita o no la sua causa; tutta la storia resta nello Storico. Se la causa continua, la stessa condizione segnalata di nuovo non lo riporta: torna solo dopo che la causa è finita ed è successa di nuovo.\n\nDettagli mostra i fatti di un allarme (dispositivo, indirizzo, MAC, porta, numeri). La croce elimina un allarme. \"Segna il dispositivo come noto\" dice ad A.R.M.O.R. che un nuovo dispositivo è benvenuto. I filtri restringono l'elenco per gravità e origine, e la ricerca cerca qualsiasi testo. Il grande pulsante attiva o disattiva il sistema; disattivare chiede il tuo PIN.\n\nPrima di armare: il pulsante interroga prima il server e mostra ciò che lascerebbe il perimetro cieco o rumoroso - un nodo radar che non risponde, una centrale muta, una zona aperta, una telecamera spenta, una porta o finestra aperta e allarmi che nessuno ha visto. Se qualcosa blocca, il pulsante dice \"Arma comunque\"; non si arma nulla finché non confermi. Il pulsante con la spunta nella barra in alto mostra la stessa verifica senza armare. Un nuovo allarme compare anche come finestra che non blocca mai la pagina, con il pulsante Riconosci e il salto al menu giusto; suoni, voce e finestre si scelgono in Configurazione > Preferenze. Un account con ruolo osservatore guarda soltanto e non può armare.",
      "今すぐ人の対応が必要なものすべてです。侵入、煙、警戒中にドアが開いた、カメラやデバイスが応答しなくなった、電池残量が少ない、警報制御盤が鳴動または改ざんされた、ネットワークに新しいデバイスが現れた、危険なポートが開いた、といったときにアラームが発生し、誰かが確認するまで一覧に残ります。\n\n新しい重大アラームは3回のビープ音で知らせ、ブラウザーの通知を許可していれば（Studio での最初のクリック時に確認されます）、Studio が別のタブにあっても通知として表示されます。Studio を開いたときに既にあったアラームは再通知されません。\n\n「確認」は1件を確認済みにし、「すべて確認」は待機中のすべてを確認済みにします。確認したアラームは、原因が解消したかどうかに関係なく一覧から外れ、下の記録に保存されます。全経過は履歴に残ります。原因が続いている間に同じ状態が再報告されても戻りません。原因が解消してから再び起きたときだけ戻ります。\n\n「詳細」ではアラームの内容（デバイス、アドレス、MAC、ポート、数値）を表示します。×でアラームを削除します。「既知のデバイスにする」は新しいデバイスを許可します。フィルターで重大度や発生源を絞り込み、検索欄で任意の文字列を探せます。大きなボタンでシステムを警戒／解除します。解除には PIN が必要です。\n\n警戒開始の前：ボタンはまずサーバーに問い合わせ、境界を無防備またはうるさくしてしまうもの（応答しないレーダーノード、無通信の警報盤、開いているゾーン、停止したカメラ、開いているドアや窓、誰も確認していないアラーム）を表示します。妨げがあるときのボタンは「それでも警戒開始」となり、確認するまで何も警戒されません。上部バーのチェックボタンは、警戒せずに同じ確認だけを行います。新しいアラームはページを妨げないポップアップとしても表示され、「確認」ボタンと適切なメニューへの移動があります。音・音声・ポップアップは「設定 > 環境設定」で選びます。閲覧者ロールのアカウントは見るだけで、警戒開始はできません。",
      "此处汇集此刻需要人处理的一切。出现问题时会触发报警——入侵、烟雾、布防时门被打开、摄像头或设备不再响应、电池电量低、报警主机鸣响或被拆、网络上出现新设备、存在风险的开放端口——并保留在列表中，直到有人确认。\n\n新的严重报警会发出三声提示音；如果您在浏览器中允许通知（在 Studio 中首次点击时会询问），即使 Studio 位于其他标签页也会以通知形式出现。打开 Studio 时列表里已有的报警不会再次提示。\n\n“确认”把一条报警标为已查看；“全部确认”标记所有待处理的报警。已确认的报警离开列表并保存在下方的记录中，无论原因是否已结束；完整过程保留在历史中。若原因仍在持续，同一状况再次上报不会让它回来；只有原因结束后再次发生才会重新出现。\n\n“详情”显示报警的具体信息（设备、地址、MAC、端口、数值）。叉号删除报警。“标记设备为已知”告诉 A.R.M.O.R. 欢迎该新设备。筛选器按严重程度和来源缩小列表，搜索框可查找任意文字。大按钮对系统布防或撤防；撤防需要输入 PIN。\n\n布防前：按钮会先询问服务器，并显示会让周界失明或吵闹的情况——无响应的雷达节点、沉默的报警主机、打开的防区、离线的摄像头、打开的门窗以及无人查看的报警。若有阻碍，按钮显示“仍然布防”；在您确认之前不会布防。顶部栏的对勾按钮可在不布防的情况下显示同样的检查。新报警还会以不阻挡页面的弹窗出现，带有“确认”按钮并可跳转到相应菜单；声音、语音和弹窗在“配置 > 偏好设置”中选择。查看者角色的账户只能查看，不能布防。",
    ] },
  { id: "alarmPanels",
    title: ["Alarm panels", "Centrales de alarma", "Alarmzentralen", "Centrales d'alarme", "Centrali d'allarme", "警報盤", "报警主机"],
    body: [
      "The alarm nodes (ARMOR-ALARM): each one reads its wired zones and listens to its Zigbee sensors, runs the panel (arming, delays, the siren, the PIN) and tells the server what it sees.\n\nEach card shows whether the node is guarding, its mode (away or at home), its zones and what happened last. A sounding alarm raises a critical alarm in the Alarms menu, and a zone in tamper a high one. \"Search for nodes\" finds panels on the local network that are not yet in the system.\n\nAn administrator can arm and disarm a panel from here, but only when three things allow it: the server (ARMOR_ALARM_COMMANDS=1), the node (its setting for the server's commands) and the broker (its access list). A disarm from here asks for the PIN of the signed-in user: the server checks it and the node never sees it. An accepted command is not an armed alarm: the card shows what the node says next. This is not a certified alarm system.\n\n\"Open the Alarm Designer\" takes you to the drawing of the house's alarm: the panels shown here appear there with their zones as sensors, tied to the real ones, and from a tied panel in the drawing you come back to this menu.",
      "Los nodos de alarma (ARMOR-ALARM): cada uno lee sus zonas cableadas y escucha a sus sensores Zigbee, lleva la central (armado, retardos, sirena, PIN) y cuenta al servidor lo que ve.\n\nCada tarjeta muestra si el nodo vigila, su modo (fuera o en casa), sus zonas y lo último que pasó. Una alarma sonando levanta una alarma crítica en el menú Alarmas, y una zona en sabotaje una alta. \"Buscar nodos\" encuentra centrales de la red local que aún no están en el sistema.\n\nUn administrador puede armar y desarmar una central desde aquí, pero solo cuando lo permiten tres cosas: el servidor (ARMOR_ALARM_COMMANDS=1), el nodo (su ajuste para las órdenes del servidor) y el broker (su lista de acceso). Un desarme desde aquí pide el PIN del usuario con sesión: lo comprueba el servidor y el nodo nunca lo ve. Una orden aceptada no es una alarma armada: la tarjeta muestra lo que dice el nodo a continuación. Esto no es un sistema de alarma certificado.\n\n\"Abrir el Diseñador de alarma\" te lleva al dibujo de la alarma de la casa: las centrales de aquí aparecen allí con sus zonas como sensores, vinculadas a las reales, y desde una central vinculada del dibujo vuelves a este menú.",
      "Die Alarmknoten (ARMOR-ALARM): Jeder liest seine verdrahteten Zonen, hört auf seine Zigbee-Melder, führt die Zentrale (Scharfschalten, Verzögerungen, Sirene, PIN) und meldet dem Server, was er sieht.\n\nJede Karte zeigt, ob der Knoten überwacht, seinen Modus (abwesend oder zu Hause), seine Zonen und was zuletzt geschah. Eine ertönende Alarmanlage löst einen kritischen Alarm im Menü Alarme aus, eine sabotierte Zone einen hohen. „Knoten suchen“ findet Zentralen im lokalen Netz, die noch nicht im System sind.\n\nEin Administrator kann eine Zentrale von hier aus schärfen und unscharf schalten, aber nur, wenn drei Dinge es erlauben: der Server (ARMOR_ALARM_COMMANDS=1), der Knoten (seine Einstellung für die Befehle des Servers) und der Broker (seine Zugriffsliste). Das Unscharfschalten verlangt die PIN des angemeldeten Benutzers: Der Server prüft sie, der Knoten sieht sie nie. Ein akzeptierter Befehl ist keine scharfe Anlage: Die Karte zeigt, was der Knoten danach meldet. Dies ist keine zertifizierte Alarmanlage.\n\n„Alarmplaner öffnen“ führt zur Zeichnung der Alarmanlage des Hauses: Die Zentralen von hier erscheinen dort mit ihren Zonen als Melder, mit den echten verknüpft, und von einer verknüpften Zentrale in der Zeichnung kommen Sie zu diesem Menü zurück.",
      "Les nœuds d'alarme (ARMOR-ALARM) : chacun lit ses zones filaires, écoute ses capteurs Zigbee, fait tourner la centrale (armement, temporisations, sirène, PIN) et dit au serveur ce qu'il voit.\n\nChaque carte montre si le nœud surveille, son mode (absent ou à la maison), ses zones et ce qui s'est passé en dernier. Une alarme qui sonne déclenche une alarme critique dans le menu Alarmes, et une zone sabotée une alarme haute. « Chercher des nœuds » trouve les centrales du réseau local qui ne sont pas encore dans le système.\n\nUn administrateur peut armer et désarmer une centrale d'ici, mais seulement si trois choses le permettent : le serveur (ARMOR_ALARM_COMMANDS=1), le nœud (son réglage pour les ordres du serveur) et le broker (sa liste d'accès). Un désarmement d'ici demande le PIN de l'utilisateur connecté : le serveur le vérifie et le nœud ne le voit jamais. Un ordre accepté n'est pas une alarme armée : la carte montre ce que dit ensuite le nœud. Ce n'est pas un système d'alarme certifié.\n\n« Ouvrir le Concepteur d'alarme » mène au dessin de l'alarme de la maison : les centrales d'ici y apparaissent avec leurs zones comme capteurs, liées aux vraies, et depuis une centrale liée du dessin vous revenez à ce menu.",
      "I nodi di allarme (ARMOR-ALARM): ognuno legge le sue zone cablate, ascolta i sensori Zigbee, gestisce la centrale (attivazione, ritardi, sirena, PIN) e dice al server ciò che vede.\n\nOgni scheda mostra se il nodo sorveglia, la sua modalità (fuori o in casa), le sue zone e cosa è successo per ultimo. Un allarme che suona genera un allarme critico nel menu Allarmi, e una zona manomessa uno alto. \"Cerca nodi\" trova le centrali della rete locale non ancora nel sistema.\n\nUn amministratore può attivare e disattivare una centrale da qui, ma solo se lo permettono tre cose: il server (ARMOR_ALARM_COMMANDS=1), il nodo (la sua impostazione per i comandi del server) e il broker (la sua lista di accesso). Una disattivazione da qui chiede il PIN dell'utente connesso: lo verifica il server e il nodo non lo vede mai. Un comando accettato non è un allarme attivo: la scheda mostra ciò che dice poi il nodo. Questo non è un sistema di allarme certificato.\n\n\"Apri il Progettista di allarme\" porta al disegno dell'allarme della casa: le centrali di qui vi compaiono con le loro zone come sensori, collegate a quelle reali, e da una centrale collegata nel disegno torni a questo menu.",
      "警報ノード（ARMOR-ALARM）：各ノードは有線ゾーンを読み取り、Zigbee センサーの通信を受け、制御盤の動作（警戒、遅延、サイレン、PIN）を行い、見たものをサーバーに伝えます。\n\n各カードには、ノードが警戒中か、モード（外出／在宅）、ゾーン、直近の出来事が表示されます。サイレンが鳴ると、アラームメニューに重大アラームが、ゾーンの改ざんには高レベルのアラームが発生します。「ノードを検索」で、まだシステムにないローカルネットワーク上の制御盤を見つけます。\n\n管理者はここから制御盤を警戒／解除できますが、次の3つがすべて許可している場合のみです：サーバー（ARMOR_ALARM_COMMANDS=1）、ノード（サーバーからの命令に対する設定）、ブローカー（アクセスリスト）。ここからの解除はログイン中のユーザーの PIN を要求します。確認はサーバーが行い、ノードは PIN を見ません。受理された命令は警戒中の警報ではありません。カードにはその後のノードの報告が表示されます。これは認証済みの警報システムではありません。\n\n「警報設計を開く」で家の警報の図に移動します。ここにある制御盤はそのゾーンがセンサーとして描かれ、実物に関連付けられます。図の中の関連付け済み制御盤からこのメニューに戻れます。",
      "报警节点（ARMOR-ALARM）：每个节点读取自己的有线防区，接收 Zigbee 传感器信号，运行主机（布防、延时、警笛、PIN），并把所见告诉服务器。\n\n每张卡片显示节点是否在守护、它的模式（离家或在家）、防区以及最近发生的事。警笛鸣响会在“报警”菜单中产生严重报警，防区被拆则产生高级别报警。“搜索节点”可找到本地网络中尚未加入系统的主机。\n\n管理员可以在这里对主机布防和撤防，但必须同时满足三个条件：服务器（ARMOR_ALARM_COMMANDS=1）、节点（其对服务器命令的设置）和代理（其访问列表）。在这里撤防需要登录用户的 PIN：由服务器校验，节点从不会看到。被接受的命令并不等于已布防：卡片会显示节点随后的上报。这不是经过认证的报警系统。\n\n“打开报警设计”会进入住宅报警的图纸：这里的主机会连同其防区作为传感器出现在图中，并与真实设备关联；在图中从已关联的主机可以回到本菜单。",
    ] },
  { id: "cameras",
    title: ["Cameras", "Cámaras", "Kameras", "Caméras", "Telecamere", "カメラ", "摄像头"],
    body: [
      "The live view of the IP cameras of the site. Pick a layout (one camera, a grid, a wall) and each place shows a camera; a place with a drop-down lets you choose which one. A click on a camera enlarges it; the arrows go to the next or previous one.\n\nOn a camera: Snapshot saves a photo into the Record, the red button records and stops, and the PTZ controls move a motorised camera (pan, tilt, zoom) when it supports it. Full-screen wall shows the cameras of the view over the whole screen with no gaps.\n\n\"Configure cameras\" opens the camera settings: add a camera with its name, address, RTSP port and path, ONVIF port and, if needed, a snapshot address; the user and password of the camera go only to your local server, which keeps them encrypted, and are never kept in the browser. Discover streams helps to find the right path. Cameras that stop answering raise an alarm while the system is armed.",
      "La vista en vivo de las cámaras IP del sitio. Elige una disposición (una cámara, una rejilla, un muro) y cada hueco muestra una cámara; un hueco con desplegable te deja elegir cuál. Un clic en una cámara la agranda; las flechas pasan a la siguiente o anterior.\n\nEn una cámara: Instantánea guarda una foto en las Grabaciones, el botón rojo graba y detiene, y los controles PTZ mueven una cámara motorizada (giro, inclinación, zoom) si lo admite. Muro a pantalla completa muestra las cámaras de la vista en toda la pantalla sin huecos.\n\n\"Configurar cámaras\" abre los ajustes de cámaras: añade una cámara con su nombre, dirección, puerto y ruta RTSP, puerto ONVIF y, si hace falta, una dirección de instantánea; el usuario y la contraseña de la cámara van solo a tu servidor local, que los guarda cifrados, y nunca se guardan en el navegador. Descubrir flujos ayuda a encontrar la ruta correcta. Las cámaras que dejan de responder generan una alarma mientras el sistema está armado.",
      "Die Live-Ansicht der IP-Kameras des Standorts. Wählen Sie ein Layout (eine Kamera, Raster, Wand), und jeder Platz zeigt eine Kamera; ein Platz mit Auswahlliste lässt Sie wählen, welche. Ein Klick vergrößert eine Kamera; die Pfeile wechseln zur nächsten oder vorherigen.\n\nAn einer Kamera: Schnappschuss speichert ein Foto in die Aufzeichnungen, der rote Knopf nimmt auf und stoppt, die PTZ-Steuerung bewegt eine motorisierte Kamera (Schwenken, Neigen, Zoom), wenn sie es kann. Vollbild-Wand zeigt die Kameras der Ansicht lückenlos auf dem ganzen Bildschirm.\n\n„Kameras konfigurieren“ öffnet die Kameraeinstellungen: Kamera mit Name, Adresse, RTSP-Port und -Pfad, ONVIF-Port und ggf. einer Schnappschuss-Adresse hinzufügen; Benutzer und Passwort der Kamera gehen nur an Ihren lokalen Server, der sie verschlüsselt speichert, und bleiben nie im Browser. „Streams suchen“ hilft, den richtigen Pfad zu finden. Kameras, die nicht mehr antworten, lösen bei scharfem System einen Alarm aus.",
      "La vue en direct des caméras IP du site. Choisissez une disposition (une caméra, une grille, un mur) et chaque emplacement montre une caméra ; un emplacement avec liste déroulante permet de choisir laquelle. Un clic agrandit une caméra ; les flèches passent à la suivante ou à la précédente.\n\nSur une caméra : Photo enregistre une image dans les Enregistrements, le bouton rouge enregistre et arrête, et les commandes PTZ déplacent une caméra motorisée (panoramique, inclinaison, zoom) si elle le permet. Mur plein écran affiche les caméras de la vue sur tout l'écran sans espaces.\n\n« Configurer les caméras » ouvre les réglages : ajoutez une caméra avec son nom, adresse, port et chemin RTSP, port ONVIF et, au besoin, une adresse d'image fixe ; l'utilisateur et le mot de passe de la caméra vont seulement à votre serveur local, qui les garde chiffrés, et ne restent jamais dans le navigateur. Découvrir les flux aide à trouver le bon chemin. Les caméras qui ne répondent plus déclenchent une alarme quand le système est armé.",
      "La vista dal vivo delle telecamere IP del sito. Scegli una disposizione (una telecamera, una griglia, un muro) e ogni posto mostra una telecamera; un posto con menu a tendina permette di scegliere quale. Un clic ingrandisce una telecamera; le frecce passano alla successiva o alla precedente.\n\nSu una telecamera: Istantanea salva una foto nelle Registrazioni, il pulsante rosso registra e ferma, e i controlli PTZ muovono una telecamera motorizzata (rotazione, inclinazione, zoom) se lo supporta. Muro a schermo intero mostra le telecamere della vista su tutto lo schermo senza spazi.\n\n«Configura telecamere» apre le impostazioni: aggiungi una telecamera con nome, indirizzo, porta e percorso RTSP, porta ONVIF e, se serve, un indirizzo di istantanea; utente e password della telecamera vanno solo al tuo server locale, che li conserva cifrati, e non restano mai nel browser. Scopri flussi aiuta a trovare il percorso giusto. Le telecamere che non rispondono più generano un allarme quando il sistema è armato.",
      "サイトの IP カメラのライブ映像です。レイアウト（1 台、グリッド、ウォール）を選ぶと各枠にカメラが表示され、ドロップダウンのある枠では表示するカメラを選べます。カメラをクリックすると拡大し、矢印で次/前のカメラへ移動します。\n\nカメラ上の操作：「スナップショット」は写真を録画に保存し、赤いボタンで録画の開始/停止、PTZ 操作は電動カメラ（パン、チルト、ズーム）を動かします（対応機種のみ）。「全画面ウォール」はその表示のカメラを隙間なく全画面で表示します。\n\n「カメラを設定」でカメラ設定を開き、名前、アドレス、RTSP ポートとパス、ONVIF ポート、必要なら静止画アドレスを入力して追加します。カメラのユーザー名とパスワードはローカルサーバーにのみ送られ、暗号化して保存され、ブラウザには保存されません。「ストリームを探す」で正しいパスを見つけられます。応答しなくなったカメラは、警戒中にアラームになります。",
      "场地 IP 摄像头的实时画面。选择布局（单个摄像头、网格、墙），每个位置显示一个摄像头；带下拉菜单的位置可选择显示哪一个。点击摄像头可放大，箭头切换到下一个或上一个。\n\n摄像头上的操作：“抓图”把照片保存到录像，红色按钮开始/停止录制，云台控制可移动电动摄像头（转动、俯仰、变焦，需摄像头支持）。“全屏墙”把当前视图的摄像头无缝铺满整个屏幕。\n\n“配置摄像头”打开摄像头设置：添加摄像头的名称、地址、RTSP 端口和路径、ONVIF 端口，必要时填写抓图地址；摄像头的用户名和密码只发送到本地服务器并加密保存，绝不保存在浏览器中。“发现视频流”帮助找到正确路径。布防期间摄像头不再响应会产生报警。",
    ] },
  { id: "radar",
    title: ["Radar", "Radar", "Radar", "Radar", "Radar", "レーダー", "雷达"],
    body: [
      "The live map of what the radar nodes see. Each radar of the site is drawn with the area it covers, and each target appears where it stands, in its radar's colour. Targets seen by two radars at once are merged into one.\n\nThe map is drawn from your site design: terrain, buildings, cameras and radars. Below it, the settings of each LD2450 radar: which field node and channel report for it, where it stands (position, height) and which way it faces. What you set here draws its coverage and places its targets; the radar module itself keeps the configuration flashed in its node.\n\n\"Mirror sideways axis\" fixes a radar mounted the other way round. \"Ignore zones\" are areas where nothing is reported (a tree that moves, a fan): draw one by dragging on the plane. A node with three radars covers about 270 degrees; \"Add a 270° node\" creates the three radars in one place, ready to move to where the node is.",
      "El mapa en vivo de lo que ven los nodos radar. Cada radar del sitio se dibuja con la zona que cubre, y cada objetivo aparece donde está, con el color de su radar. Los objetivos que ven dos radares a la vez se fusionan en uno.\n\nEl mapa se dibuja a partir del diseño del sitio: terreno, edificios, cámaras y radares. Debajo, los ajustes de cada radar LD2450: qué nodo de campo y canal informan por él, dónde está (posición, altura) y hacia dónde mira. Lo que pongas aquí dibuja su cobertura y coloca sus objetivos; el módulo radar conserva la configuración grabada en su nodo.\n\n\"Reflejar el eje lateral\" corrige un radar montado al revés. Las \"zonas a ignorar\" son áreas donde no se informa nada (un árbol que se mueve, un ventilador): dibuja una arrastrando sobre el plano. Un nodo con tres radares cubre unos 270 grados; \"Añadir un nodo de 270°\" crea los tres radares en un punto, listos para llevarlos a donde esté el nodo.",
      "Die Live-Karte dessen, was die Radarknoten sehen. Jedes Radar des Standorts wird mit seinem Erfassungsbereich gezeichnet, jedes Ziel erscheint dort, wo es steht, in der Farbe seines Radars. Von zwei Radaren gleichzeitig gesehene Ziele werden zu einem verschmolzen.\n\nDie Karte entsteht aus Ihrem Standortplan: Gelände, Gebäude, Kameras und Radare. Darunter die Einstellungen jedes LD2450-Radars: welcher Feldknoten und Kanal für es melden, wo es steht (Position, Höhe) und wohin es blickt. Was Sie hier einstellen, zeichnet seine Abdeckung und platziert seine Ziele; das Radarmodul selbst behält die in seinem Knoten gespeicherte Konfiguration.\n\n„Querachse spiegeln“ korrigiert ein verkehrt montiertes Radar. „Ignorierzonen“ sind Bereiche, aus denen nichts gemeldet wird (ein bewegter Baum, ein Ventilator): zeichnen Sie eine, indem Sie auf der Ebene ziehen. Ein Knoten mit drei Radaren deckt etwa 270 Grad ab; „270°-Knoten hinzufügen“ legt die drei Radare an einem Punkt an, bereit zum Verschieben an den Ort des Knotens.",
      "La carte en direct de ce que voient les nœuds radar. Chaque radar du site est dessiné avec la zone qu'il couvre, et chaque cible apparaît où elle se trouve, à la couleur de son radar. Les cibles vues par deux radars à la fois sont fusionnées en une.\n\nLa carte est dessinée d'après votre plan du site : terrain, bâtiments, caméras et radars. En dessous, les réglages de chaque radar LD2450 : quel nœud de terrain et quel canal rapportent pour lui, où il se trouve (position, hauteur) et vers où il regarde. Ce que vous réglez ici dessine sa couverture et place ses cibles ; le module radar garde la configuration inscrite dans son nœud.\n\n« Inverser l'axe latéral » corrige un radar monté à l'envers. Les « zones à ignorer » sont des zones où rien n'est rapporté (un arbre qui bouge, un ventilateur) : dessinez-en une en glissant sur le plan. Un nœud à trois radars couvre environ 270 degrés ; « Ajouter un nœud 270° » crée les trois radars au même endroit, prêts à être placés là où est le nœud.",
      "La mappa dal vivo di ciò che vedono i nodi radar. Ogni radar del sito è disegnato con l'area che copre, e ogni bersaglio appare dove si trova, nel colore del suo radar. I bersagli visti da due radar insieme sono uniti in uno.\n\nLa mappa è disegnata dal progetto del sito: terreno, edifici, telecamere e radar. Sotto, le impostazioni di ogni radar LD2450: quale nodo di campo e canale riferiscono per esso, dove si trova (posizione, altezza) e dove guarda. Ciò che imposti qui disegna la sua copertura e colloca i suoi bersagli; il modulo radar conserva la configurazione scritta nel suo nodo.\n\n«Specchia l'asse laterale» corregge un radar montato al contrario. Le «zone da ignorare» sono aree in cui non si riferisce nulla (un albero che si muove, un ventilatore): disegnane una trascinando sul piano. Un nodo con tre radar copre circa 270 gradi; «Aggiungi un nodo 270°» crea i tre radar in un punto, pronti da portare dove sta il nodo.",
      "レーダーノードが捉えているもののライブマップです。サイトの各レーダーが、カバーする範囲とともに描かれ、各対象はそのレーダーの色で位置に表示されます。2 台のレーダーが同時に捉えた対象は 1 つに統合されます。\n\nマップはサイト設計（敷地、建物、カメラ、レーダー）から描かれます。その下に各 LD2450 レーダーの設定があります：どのフィールドノードとチャンネルが報告するか、設置位置（位置、高さ）、向き。ここでの設定がカバー範囲の描画と対象の配置に使われます。レーダーモジュール自体はノードに書き込まれた設定を保持します。\n\n「横軸を反転」は逆向きに取り付けたレーダー用です。「無視ゾーン」は何も報告しない領域（揺れる木、扇風機など）で、平面上をドラッグして描きます。3 台のレーダーを持つノードは約 270 度をカバーします。「270° ノードを追加」で 3 台を 1 か所に作成し、ノードの設置場所へ移動できます。",
      "雷达节点所见内容的实时地图。场地的每台雷达都绘有其覆盖范围，每个目标以其雷达的颜色显示在所在位置。两台雷达同时看到的目标会合并为一个。\n\n地图根据你的场地设计绘制：场地、建筑、摄像头和雷达。下方是每台 LD2450 雷达的设置：由哪个现场节点和通道上报、安装位置（位置、高度）以及朝向。此处的设置用于绘制覆盖范围并放置目标；雷达模块本身保留写入其节点的配置。\n\n“镜像横轴”用于修正反向安装的雷达。“忽略区域”是不上报任何内容的区域（摇动的树、风扇）：在平面上拖动即可绘制。带三台雷达的节点覆盖约 270 度；“添加 270° 节点”会在一处创建三台雷达，便于移到节点所在位置。",
    ] },
  { id: "record",
    title: ["Record", "Grabaciones", "Aufzeichnungen", "Enregistrements", "Registrazioni", "録画", "录像"],
    body: [
      "The photos and recordings saved from the cameras. The list on the left shows them with their date and size; filters pick everything, only photos or only recordings. Choose one and it opens on the right: a photo is shown large, a recording plays.\n\n\"Keep (protect)\" keeps the chosen photo or recording out of the automatic pruning (the server keeps 30 days or 20 GB, oldest first) - use it for what may be evidence. A protected item shows \"Protected: release\"; it is not deleted by the bulk clean-ups and has to be released first.\n\nYou delete selected items with \"Delete selected\", or clean up in bulk: everything of the chosen kind, or only what is older than a number of days. Deleting is permanent and Studio asks first. The Cameras screen shows which cameras are recording, and it still knows after the page is reloaded.\n\nPhotos and recordings are taken from the Cameras screen (Snapshot and the red record button).\n\nProof of custody: the \"Proof of custody\" button downloads a file signed by the server with the size, the SHA-256 of the evidence as it is now, when it was made and every line of the audit trail about it (who protected it, who asked for its hash). Hand it over with the file: the server can say whether the document is genuine and whether the file still has the same digest.",
      "Las fotos y grabaciones guardadas de las cámaras. La lista de la izquierda las muestra con su fecha y tamaño; los filtros eligen todo, solo fotos o solo grabaciones. Elige una y se abre a la derecha: una foto se ve grande, una grabación se reproduce.\n\n\"Conservar (proteger)\" deja la foto o grabación elegida fuera de la poda automática (el servidor guarda 30 días o 20 GB, lo más antiguo primero): úsalo con lo que pueda ser una prueba. Un elemento protegido muestra \"Protegida: liberar\"; las limpiezas en bloque no lo borran y hay que liberarlo antes.\n\nBorras los elementos seleccionados con \"Borrar seleccionados\", o limpias en bloque: todo lo del tipo elegido, o solo lo más antiguo de cierto número de días. Borrar es permanente y Studio pregunta antes. La pantalla Cámaras muestra qué cámaras están grabando, y lo sigue sabiendo tras recargar la página.\n\nLas fotos y grabaciones se hacen desde la pantalla Cámaras (Foto y el botón rojo de grabar).\n\nPrueba de custodia: el botón \"Prueba de custodia\" descarga un archivo firmado por el servidor con el tamaño, el SHA-256 de la prueba tal como está ahora, cuándo se hizo y cada línea de la auditoría sobre ella (quién la protegió, quién pidió su huella). Entrégalo junto con el archivo: el servidor puede decir si el documento es auténtico y si el archivo sigue teniendo la misma huella.",
      "Die von den Kameras gespeicherten Fotos und Aufnahmen. Die Liste links zeigt sie mit Datum und Größe; Filter wählen alles, nur Fotos oder nur Aufnahmen. Wählen Sie eines, und es öffnet sich rechts: Ein Foto wird groß gezeigt, eine Aufnahme abgespielt.\n\n„Aufbewahren (schützen)“ nimmt das gewählte Foto oder die Aufnahme von der automatischen Bereinigung aus (der Server behält 30 Tage oder 20 GB, das Älteste zuerst) - nutzen Sie es für mögliche Beweise. Ein geschütztes Element zeigt „Geschützt: freigeben“; Sammelbereinigungen löschen es nicht, es muss zuerst freigegeben werden.\n\nAusgewählte Elemente löschen Sie mit „Ausgewählte löschen“, oder Sie räumen gesammelt auf: alles der gewählten Art oder nur, was älter als eine Anzahl Tage ist. Löschen ist endgültig, und Studio fragt vorher. Der Bildschirm Kameras zeigt, welche Kameras aufnehmen, und weiß es auch nach dem Neuladen der Seite.\n\nFotos und Aufnahmen entstehen im Bildschirm Kameras (Foto und der rote Aufnahmeknopf).\n\nNachweis der Beweiskette: Die Schaltfläche \"Nachweis der Beweiskette\" lädt eine vom Server signierte Datei herunter, mit Größe, dem SHA-256 des Beweises in seinem jetzigen Zustand, dem Entstehungszeitpunkt und jeder Audit-Zeile dazu (wer ihn geschützt, wer seine Prüfsumme angefragt hat). Übergeben Sie sie zusammen mit der Datei: Der Server kann sagen, ob das Dokument echt ist und ob die Datei noch dieselbe Prüfsumme hat.",
      "Les photos et enregistrements sauvegardés des caméras. La liste de gauche les montre avec leur date et leur taille ; les filtres choisissent tout, seulement les photos ou seulement les enregistrements. Choisissez-en un et il s'ouvre à droite : une photo s'affiche en grand, un enregistrement se lit.\n\n« Conserver (protéger) » met la photo ou l'enregistrement choisi à l'abri de l'élagage automatique (le serveur garde 30 jours ou 20 Go, le plus ancien d'abord) - à utiliser pour ce qui peut être une preuve. Un élément protégé affiche « Protégé : libérer » ; les nettoyages en masse ne le suppriment pas et il faut d'abord le libérer.\n\nVous supprimez les éléments sélectionnés avec « Supprimer la sélection », ou vous nettoyez en masse : tout ce qui est du type choisi, ou seulement ce qui date de plus de quelques jours. Supprimer est définitif et Studio demande d'abord. L'écran Caméras montre quelles caméras enregistrent, et le sait encore après le rechargement de la page.\n\nLes photos et enregistrements se prennent depuis l'écran Caméras (Photo et le bouton rouge d'enregistrement).\n\nPreuve de garde : le bouton « Preuve de garde » télécharge un fichier signé par le serveur avec la taille, le SHA-256 de la preuve telle qu'elle est maintenant, sa date de création et chaque ligne de l'audit la concernant (qui l'a protégée, qui a demandé son empreinte). Remettez-le avec le fichier : le serveur peut dire si le document est authentique et si le fichier a toujours la même empreinte.",
      "Le foto e le registrazioni salvate dalle telecamere. L'elenco a sinistra le mostra con data e dimensione; i filtri scelgono tutto, solo foto o solo registrazioni. Sceglierne una la apre a destra: una foto è mostrata grande, una registrazione viene riprodotta.\n\n\"Conserva (proteggi)\" esclude la foto o registrazione scelta dalla potatura automatica (il server tiene 30 giorni o 20 GB, prima il più vecchio): usalo per ciò che può essere una prova. Un elemento protetto mostra \"Protetto: rilascia\"; le pulizie in blocco non lo eliminano e va prima rilasciato.\n\nElimini gli elementi selezionati con \"Elimina selezionati\", oppure pulisci in blocco: tutto del tipo scelto, o solo ciò che ha più di un certo numero di giorni. Eliminare è definitivo e Studio chiede prima. La schermata Telecamere mostra quali telecamere stanno registrando, e lo sa ancora dopo aver ricaricato la pagina.\n\nFoto e registrazioni si fanno dalla schermata Telecamere (Foto e il pulsante rosso di registrazione).\n\nProva di custodia: il pulsante \"Prova di custodia\" scarica un file firmato dal server con la dimensione, lo SHA-256 della prova com'è ora, quando è stata fatta e ogni riga dell'audit che la riguarda (chi l'ha protetta, chi ha chiesto la sua impronta). Consegnalo insieme al file: il server può dire se il documento è autentico e se il file ha ancora la stessa impronta.",
      "カメラから保存された写真と録画です。左の一覧に日付とサイズが表示され、フィルターで全部／写真のみ／録画のみを選べます。1つ選ぶと右に表示され、写真は大きく、録画は再生されます。\n\n「保護する」で、選んだ写真や録画を自動削除（サーバーは30日または20GB、古い順）から外します。証拠になりうるものに使ってください。保護されたものは「保護中：解除」と表示され、一括削除では消えず、先に解除が必要です。\n\n選択した項目は「選択を削除」で削除するか、一括で整理します（選んだ種類すべて、または指定日数より古いものだけ）。削除は元に戻せず、Studio が事前に確認します。カメラ画面はどのカメラが録画中かを表示し、ページを再読み込みしても把握しています。\n\n写真と録画はカメラ画面（スナップショットと赤い録画ボタン）で撮ります。\n\n保管証明：「保管証明」ボタンは、サイズ、現時点の証拠の SHA-256、作成時刻、およびそれに関する監査ログの全行（誰が保護したか、誰がハッシュを求めたか）を含む、サーバー署名付きのファイルをダウンロードします。証拠ファイルと一緒に提出してください。サーバーは文書が真正か、ファイルのハッシュが今も同じかを確認できます。",
      "保存的摄像头照片和录像。左侧列表显示日期和大小；筛选器可选择全部、仅照片或仅录像。选中一项会在右侧打开：照片放大显示，录像直接播放。\n\n“保护”可让所选照片或录像不被自动清理（服务器保留 30 天或 20 GB，先清最旧的）——请用于可能作为证据的内容。受保护的项目显示“已保护：解除”；批量清理不会删除它，需要先解除保护。\n\n用“删除所选”删除选中项，或批量清理：所选类型的全部，或仅超过若干天的内容。删除不可恢复，Studio 会先询问。摄像头界面会显示哪些摄像头正在录像，刷新页面后仍然知道。\n\n照片和录像在摄像头界面拍摄（快照和红色录制按钮）。\n\n保管证明：“保管证明”按钮会下载一个由服务器签名的文件，包含大小、证据当前的 SHA-256、创建时间以及与之相关的每一行审计记录（谁保护了它、谁请求了它的摘要）。请连同证据文件一并提交：服务器可以验证该文档是否真实，以及文件的摘要是否仍然相同。",
    ] },
  { id: "history",
    title: ["History", "Historial", "Verlauf", "Historique", "Cronologia", "履歴", "历史"],
    body: [
      "Everything that happened, newest first: every change of alert level of a node, node and camera going online or offline, changes of the security mode, alarms raised, acknowledged and cleared, and device and network events. It is the place to see the whole story, also of alarms you have already acknowledged.\n\nThe summary on top counts the events held, those of the last 24 hours, the HIGH alerts and the incidents of nodes. Filters pick the kind of event, the alert level and a period (from / to); the search box looks for any text. \"Load older events\" asks the server for more. \"Live\" refreshes every five seconds and can be paused. \"Clear history\" deletes the stored events but not the alarms.",
      "Todo lo que ha pasado, lo más reciente primero: cada cambio de nivel de alerta de un nodo, nodos y cámaras que se conectan o desconectan, cambios del modo de seguridad, alarmas generadas, reconocidas y cerradas, y eventos de dispositivos y de red. Es el sitio para ver la historia completa, también de las alarmas que ya reconociste.\n\nEl resumen de arriba cuenta los eventos guardados, los de las últimas 24 horas, las alertas ALTAS y las incidencias de nodos. Los filtros eligen el tipo de evento, el nivel de alerta y un periodo (desde / hasta); el cuadro de búsqueda busca cualquier texto. \"Cargar eventos más antiguos\" pide más al servidor. \"En vivo\" se actualiza cada cinco segundos y se puede pausar. \"Borrar historial\" elimina los eventos guardados pero no las alarmas.",
      "Alles, was geschehen ist, neueste zuerst: jede Änderung der Alarmstufe eines Knotens, Knoten und Kameras, die online oder offline gehen, Wechsel des Sicherheitsmodus, ausgelöste, quittierte und beendete Alarme sowie Geräte- und Netzereignisse. Hier sehen Sie die ganze Geschichte, auch von bereits quittierten Alarmen.\n\nDie Übersicht oben zählt die gespeicherten Ereignisse, die der letzten 24 Stunden, die HOCH-Alarme und die Zwischenfälle von Knoten. Filter wählen die Art des Ereignisses, die Alarmstufe und einen Zeitraum (von / bis); das Suchfeld sucht beliebigen Text. „Ältere Ereignisse laden“ fragt den Server nach mehr. „Live“ aktualisiert alle fünf Sekunden und lässt sich pausieren. „Verlauf löschen“ entfernt die gespeicherten Ereignisse, nicht die Alarme.",
      "Tout ce qui s'est passé, le plus récent d'abord : chaque changement de niveau d'alerte d'un nœud, nœuds et caméras qui passent en ligne ou hors ligne, changements du mode de sécurité, alarmes déclenchées, acquittées et closes, et événements d'appareils et de réseau. C'est l'endroit pour voir toute l'histoire, y compris celle des alarmes déjà acquittées.\n\nLe résumé en haut compte les événements conservés, ceux des dernières 24 heures, les alertes ÉLEVÉES et les incidents de nœuds. Les filtres choisissent le type d'événement, le niveau d'alerte et une période (du / au) ; la recherche cherche n'importe quel texte. « Charger des événements plus anciens » en demande davantage au serveur. « En direct » se rafraîchit toutes les cinq secondes et peut être mis en pause. « Effacer l'historique » supprime les événements conservés mais pas les alarmes.",
      "Tutto ciò che è successo, il più recente prima: ogni cambio di livello di allerta di un nodo, nodi e telecamere che vanno online o offline, cambi della modalità di sicurezza, allarmi generati, riconosciuti e chiusi, ed eventi di dispositivi e di rete. È il posto per vedere tutta la storia, anche degli allarmi già riconosciuti.\n\nIl riepilogo in alto conta gli eventi conservati, quelli delle ultime 24 ore, gli allarmi ALTI e gli incidenti dei nodi. I filtri scelgono il tipo di evento, il livello di allerta e un periodo (da / a); la ricerca cerca qualsiasi testo. «Carica eventi più vecchi» ne chiede altri al server. «Dal vivo» si aggiorna ogni cinque secondi e si può mettere in pausa. «Cancella cronologia» elimina gli eventi salvati ma non gli allarmi.",
      "起きたことをすべて新しい順に表示します：ノードのアラートレベルの変化、ノードやカメラのオンライン/オフライン、セキュリティモードの変更、発生・確認・解消したアラーム、機器とネットワークのイベント。確認済みのアラームを含め、経緯全体を見る場所です。\n\n上部のサマリーには、保存済みイベント数、過去 24 時間の数、「高」アラートの数、ノードの障害件数が表示されます。フィルターでイベントの種類、アラートレベル、期間（開始/終了）を選び、検索欄で任意の文字を探せます。「古いイベントを読み込む」でサーバーからさらに取得します。「ライブ」は 5 秒ごとに更新し、一時停止できます。「履歴を消去」は保存イベントを削除しますが、アラームは削除しません。",
      "按时间从新到旧显示发生过的一切：节点警报级别的每次变化、节点和摄像头上线或离线、安全模式变化、报警的产生/确认/结束，以及设备和网络事件。想看完整经过（包括已确认的报警）就来这里。\n\n顶部汇总统计已保存事件数、最近 24 小时的数量、“高”级警报和节点事件数。筛选器可选择事件类型、警报级别和时间段（起/止），搜索框可查找任意文字。“加载更早的事件”向服务器请求更多。“实时”每五秒刷新一次，可暂停。“清除历史”会删除已保存的事件，但不删除报警。",
    ] },
  { id: "inverters",
    title: ["Inverters", "Inversores", "Wechselrichter", "Onduleurs", "Inverter", "インバーター", "逆变器"],
    body: [
      "The solar inverters and their live readings, as the gateway nodes (ARMOR-SOLAR) read them: power, voltages, load, battery and temperature, with the state of the inverter (line, battery, fault) and the warnings it reports.\n\nYou declare the equipment here with \"Add an inverter\": a name, the gateway node that reads it, its identifier (the short name used in the node's settings), its model and how it is connected. The readings are read-only: they come from the node. While the node has not sent its first reading, the equipment waits; \"Show example readings\" fills the screen with made-up values to see how it will look (nothing is saved).\n\nHistory shows how the readings changed over time. A fault of the inverter raises a HIGH alarm; a battery below 20 % raises a warning. If an inverter is silent for a while, the screen says \"no data for a while\" and an alarm is raised.",
      "Los inversores solares y sus lecturas en vivo, tal como las leen los nodos pasarela (ARMOR-SOLAR): potencia, tensiones, carga, batería y temperatura, con el estado del inversor (red, batería, fallo) y los avisos que informa.\n\nDeclaras el equipo aquí con \"Añadir un inversor\": un nombre, el nodo pasarela que lo lee, su identificador (el nombre corto usado en los ajustes del nodo), su modelo y cómo está conectado. Las lecturas son de solo lectura: vienen del nodo. Mientras el nodo no ha enviado su primera lectura, el equipo espera; \"Mostrar lecturas de ejemplo\" llena la pantalla con valores inventados para ver cómo quedará (no se guarda nada).\n\nHistorial muestra cómo cambiaron las lecturas con el tiempo. Un fallo del inversor genera una alarma ALTA; una batería por debajo del 20 % genera un aviso. Si un inversor calla un rato, la pantalla dice \"sin datos desde hace un rato\" y se genera una alarma.",
      "Die Solar-Wechselrichter und ihre Live-Werte, wie die Gateway-Knoten (ARMOR-SOLAR) sie lesen: Leistung, Spannungen, Last, Batterie und Temperatur, mit dem Zustand des Wechselrichters (Netz, Batterie, Fehler) und seinen Warnungen.\n\nSie melden das Gerät hier mit „Wechselrichter hinzufügen“ an: Name, der lesende Gateway-Knoten, Kennung (der Kurzname in den Knoteneinstellungen), Modell und Anschlussart. Die Werte sind nur lesbar: Sie kommen vom Knoten. Solange der Knoten noch keinen Wert gesendet hat, wartet das Gerät; „Beispielwerte zeigen“ füllt den Bildschirm mit erfundenen Werten, um das Aussehen zu sehen (nichts wird gespeichert).\n\nVerlauf zeigt, wie sich die Werte über die Zeit änderten. Ein Fehler des Wechselrichters löst einen Alarm HOCH aus; eine Batterie unter 20 % eine Warnung. Schweigt ein Wechselrichter länger, steht „seit einer Weile keine Daten“ und ein Alarm wird ausgelöst.",
      "Les onduleurs solaires et leurs mesures en direct, telles que les lisent les nœuds passerelles (ARMOR-SOLAR) : puissance, tensions, charge, batterie et température, avec l'état de l'onduleur (réseau, batterie, défaut) et les avertissements rapportés.\n\nVous déclarez l'équipement ici avec « Ajouter un onduleur » : un nom, le nœud passerelle qui le lit, son identifiant (le nom court utilisé dans les réglages du nœud), son modèle et sa connexion. Les mesures sont en lecture seule : elles viennent du nœud. Tant que le nœud n'a pas envoyé sa première mesure, l'équipement attend ; « Afficher des mesures d'exemple » remplit l'écran de valeurs inventées pour voir le rendu (rien n'est enregistré).\n\nHistorique montre l'évolution des mesures dans le temps. Un défaut de l'onduleur déclenche une alarme ÉLEVÉE ; une batterie sous 20 % un avertissement. Si un onduleur se tait un moment, l'écran indique « pas de données depuis un moment » et une alarme se déclenche.",
      "Gli inverter solari e le loro letture dal vivo, come le leggono i nodi gateway (ARMOR-SOLAR): potenza, tensioni, carico, batteria e temperatura, con lo stato dell'inverter (rete, batteria, guasto) e gli avvisi che riferisce.\n\nDichiari l'apparecchio qui con «Aggiungi un inverter»: un nome, il nodo gateway che lo legge, il suo identificativo (il nome breve usato nelle impostazioni del nodo), il modello e come è collegato. Le letture sono di sola lettura: vengono dal nodo. Finché il nodo non ha inviato la prima lettura, l'apparecchio attende; «Mostra letture di esempio» riempie la schermata di valori inventati per vedere come sarà (non si salva nulla).\n\nCronologia mostra come sono cambiate le letture nel tempo. Un guasto dell'inverter genera un allarme ALTO; una batteria sotto il 20 % un avviso. Se un inverter tace a lungo, la schermata dice «nessun dato da un po'» e scatta un allarme.",
      "ゲートウェイノード（ARMOR-SOLAR）が読み取る太陽光インバーターのライブ測定値です：電力、電圧、負荷、バッテリー、温度、インバーターの状態（系統、バッテリー、故障）と報告される警告。\n\n「インバーターを追加」で機器を登録します：名前、読み取るゲートウェイノード、識別子（ノード設定で使う短い名前）、型式、接続方法。測定値は読み取り専用で、ノードから届きます。ノードが最初の測定値を送るまで機器は待機し、「例の測定値を表示」で架空の値を表示して見た目を確認できます（保存はされません）。\n\n「履歴」では測定値の時間変化を確認できます。インバーターの故障は「高」のアラーム、バッテリー 20 % 未満は警告になります。しばらく応答がなければ「しばらくデータなし」と表示され、アラームが発生します。",
      "由网关节点（ARMOR-SOLAR）读取的光伏逆变器及其实时读数：功率、电压、负载、电池和温度，以及逆变器状态（市电、电池、故障）和上报的警告。\n\n用“添加逆变器”在此声明设备：名称、读取它的网关节点、标识（节点设置中使用的简称）、型号及连接方式。读数为只读，来自节点。节点发送首个读数之前设备处于等待状态；“显示示例读数”会用虚构数值填满界面以便查看效果（不保存任何内容）。\n\n“历史”显示读数随时间的变化。逆变器故障会产生“高”级报警；电池低于 20 % 产生警告。若逆变器沉默一段时间，界面显示“一段时间没有数据”并产生报警。",
    ] },
  { id: "batteries",
    title: ["Batteries", "Baterías", "Batterien", "Batteries", "Batterie", "バッテリー", "电池"],
    body: [
      "The battery banks and their live readings: state of charge, voltage, current, temperature and, for banks that report them, each module and each cell.\n\n\"Add a battery\" declares one in the same way as an inverter: name, gateway node, identifier, model and connection. \"Cells\" shows the cells of a module one by one, so a weak cell stands out. A module that is not present is marked \"not present\".\n\nA battery below 20 % of charge raises a warning that ends when it is back above 30 %; a battery that reports an alarm of its own raises a HIGH alarm. History shows how charge and voltage changed over time.",
      "Los bancos de baterías y sus lecturas en vivo: estado de carga, tensión, corriente, temperatura y, en los bancos que lo informan, cada módulo y cada celda.\n\n\"Añadir una batería\" declara una igual que un inversor: nombre, nodo pasarela, identificador, modelo y conexión. \"Celdas\" muestra las celdas de un módulo una a una, para que se note una celda débil. Un módulo que no está presente se marca \"no presente\".\n\nUna batería por debajo del 20 % de carga genera un aviso que termina cuando vuelve a superar el 30 %; una batería que informa de una alarma propia genera una alarma ALTA. Historial muestra cómo cambiaron la carga y la tensión con el tiempo.",
      "Die Batteriebänke und ihre Live-Werte: Ladezustand, Spannung, Strom, Temperatur und, bei Bänken, die es melden, jedes Modul und jede Zelle.\n\n„Batterie hinzufügen“ meldet eine an wie einen Wechselrichter: Name, Gateway-Knoten, Kennung, Modell und Anschluss. „Zellen“ zeigt die Zellen eines Moduls einzeln, damit eine schwache Zelle auffällt. Ein nicht vorhandenes Modul ist mit „nicht vorhanden“ markiert.\n\nEine Batterie unter 20 % Ladung löst eine Warnung aus, die endet, wenn sie wieder über 30 % liegt; meldet eine Batterie einen eigenen Alarm, entsteht ein Alarm HOCH. Verlauf zeigt, wie sich Ladung und Spannung über die Zeit änderten.",
      "Les bancs de batteries et leurs mesures en direct : état de charge, tension, courant, température et, pour les bancs qui les rapportent, chaque module et chaque cellule.\n\n« Ajouter une batterie » en déclare une comme un onduleur : nom, nœud passerelle, identifiant, modèle et connexion. « Cellules » montre les cellules d'un module une à une, pour repérer une cellule faible. Un module absent est marqué « absent ».\n\nUne batterie sous 20 % de charge déclenche un avertissement qui cesse quand elle repasse au-dessus de 30 % ; une batterie qui rapporte une alarme propre déclenche une alarme ÉLEVÉE. Historique montre l'évolution de la charge et de la tension.",
      "I banchi di batterie e le loro letture dal vivo: stato di carica, tensione, corrente, temperatura e, per i banchi che le riferiscono, ogni modulo e ogni cella.\n\n«Aggiungi una batteria» ne dichiara una come un inverter: nome, nodo gateway, identificativo, modello e collegamento. «Celle» mostra le celle di un modulo una per una, così una cella debole si nota. Un modulo non presente è segnato «non presente».\n\nUna batteria sotto il 20 % di carica genera un avviso che finisce quando torna sopra il 30 %; una batteria che riferisce un proprio allarme genera un allarme ALTO. Cronologia mostra come sono cambiati carica e tensione nel tempo.",
      "バッテリーバンクのライブ測定値：充電率、電圧、電流、温度、対応するバンクでは各モジュールと各セル。\n\n「バッテリーを追加」でインバーターと同様に登録します：名前、ゲートウェイノード、識別子、型式、接続。「セル」ではモジュールのセルを 1 つずつ表示し、弱いセルが分かります。存在しないモジュールは「なし」と表示されます。\n\n充電率が 20 % 未満になると警告となり、30 % を超えると解除されます。バッテリー自身がアラームを報告すると「高」のアラームになります。「履歴」では充電率と電圧の時間変化を確認できます。",
      "电池组的实时读数：电量、电压、电流、温度，对支持的电池组还有每个模块和每个电芯。\n\n“添加电池”的声明方式与逆变器相同：名称、网关节点、标识、型号和连接。“电芯”逐个显示模块的电芯，便于发现较弱的电芯。不存在的模块标记为“不存在”。\n\n电量低于 20 % 时产生警告，回升到 30 % 以上结束；电池自身上报报警时产生“高”级报警。“历史”显示电量和电压随时间的变化。",
    ] },
  { id: "electrical",
    title: ["Electrical", "Eléctrico", "Elektrik", "Électrique", "Elettrico", "電気", "电气"],
    body: [
      "The electrical nodes (ARMOR-ELECTRICAL) and the live diagram of the installation. The nodes read energy meters over RS485 and report channels: voltage, current, power and energy of the mains, the sub-circuits and the solar side.\n\nIf you drew the installation in the Electrical Designer and bound its elements to nodes, the diagram here shows the live values on it. Without a drawing, you see the nodes and their channels as a list. When no electrical node has reported yet, the screen tells you what to do: power one on in this network and look for it in the node finder.\n\nThe alarms of this area are warnings that end by themselves: a meter that raises its own alarm, a mains voltage out of range (about 230 V, from 195 to 253), and the loss of the grid input; a latched fault of a contactor is HIGH.\n\nEnergy per day: a card adds up, for the last week, what the meter of each channel counted. It adds only the difference between readings, so a meter that wraps at 9,999.99 kWh or starts again from zero after a power cut does not make a negative day or count its whole total again; the day it happens is marked.",
      "Los nodos eléctricos (ARMOR-ELECTRICAL) y el esquema en vivo de la instalación. Los nodos leen contadores de energía por RS485 e informan canales: tensión, corriente, potencia y energía de la red, de los subcircuitos y de la parte solar.\n\nSi dibujaste la instalación en el Diseñador eléctrico y enlazaste sus elementos con nodos, el esquema de aquí muestra los valores en vivo sobre él. Sin dibujo, ves los nodos y sus canales en una lista. Cuando aún no ha informado ningún nodo eléctrico, la pantalla te dice qué hacer: encender uno en esta red y buscarlo en el buscador de nodos.\n\nLas alarmas de esta zona son avisos que terminan solos: un contador que genera su propia alarma, una tensión de red fuera de rango (unos 230 V, de 195 a 253) y la pérdida de la entrada de red; un fallo retenido de un contactor es ALTO.\n\nEnergía por día: una tarjeta suma, para la última semana, lo que contó el contador de cada canal. Suma solo la diferencia entre lecturas, así que un contador que da la vuelta a 9.999,99 kWh o empieza de cero tras un corte no produce un día negativo ni vuelve a contar todo su total; el día en que ocurre queda marcado.",
      "Die Elektroknoten (ARMOR-ELECTRICAL) und das Live-Schema der Anlage. Die Knoten lesen Energiezähler per RS485 und melden Kanäle: Spannung, Strom, Leistung und Energie von Netz, Unterkreisen und Solarseite.\n\nHaben Sie die Anlage im Elektro-Designer gezeichnet und deren Elemente an Knoten gebunden, zeigt das Schema hier die Live-Werte darauf. Ohne Zeichnung sehen Sie Knoten und Kanäle als Liste. Hat noch kein Elektroknoten gemeldet, sagt der Bildschirm, was zu tun ist: einen in diesem Netz einschalten und im Knotenfinder suchen.\n\nDie Alarme dieses Bereichs sind Warnungen, die von selbst enden: ein Zähler mit eigenem Alarm, eine Netzspannung außerhalb des Bereichs (etwa 230 V, 195 bis 253) und der Verlust des Netzeingangs; ein gespeicherter Fehler eines Schützes ist HOCH.\n\nEnergie pro Tag: Eine Karte addiert für die letzte Woche, was der Zähler jedes Kanals gezählt hat. Sie addiert nur die Differenz zwischen Messungen; ein Zähler, der bei 9.999,99 kWh überläuft oder nach einem Stromausfall bei null beginnt, ergibt keinen negativen Tag und zählt nicht seine ganze Summe erneut; der Tag wird markiert.",
      "Les nœuds électriques (ARMOR-ELECTRICAL) et le schéma en direct de l'installation. Les nœuds lisent des compteurs d'énergie en RS485 et rapportent des canaux : tension, courant, puissance et énergie du secteur, des sous-circuits et du côté solaire.\n\nSi vous avez dessiné l'installation dans le Concepteur électrique et lié ses éléments à des nœuds, le schéma affiche ici les valeurs en direct. Sans dessin, vous voyez les nœuds et leurs canaux en liste. Quand aucun nœud électrique n'a encore rapporté, l'écran dit quoi faire : en allumer un sur ce réseau et le chercher dans le chercheur de nœuds.\n\nLes alarmes de cette zone sont des avertissements qui cessent d'eux-mêmes : un compteur qui lève sa propre alarme, une tension secteur hors plage (environ 230 V, de 195 à 253) et la perte de l'entrée secteur ; un défaut verrouillé d'un contacteur est ÉLEVÉ.\n\nÉnergie par jour : une carte additionne, pour la dernière semaine, ce que le compteur de chaque canal a compté. Elle n'ajoute que la différence entre deux relevés ; un compteur qui boucle à 9 999,99 kWh ou repart de zéro après une coupure ne donne ni jour négatif ni recomptage de tout son total ; le jour concerné est marqué.",
      "I nodi elettrici (ARMOR-ELECTRICAL) e lo schema dal vivo dell'impianto. I nodi leggono contatori di energia via RS485 e riferiscono canali: tensione, corrente, potenza ed energia della rete, dei sottocircuiti e del lato solare.\n\nSe hai disegnato l'impianto nella Progettazione elettrica e collegato i suoi elementi ai nodi, lo schema qui mostra i valori dal vivo. Senza disegno vedi i nodi e i loro canali in elenco. Quando nessun nodo elettrico ha ancora riferito, la schermata dice cosa fare: accenderne uno in questa rete e cercarlo nel cercatore di nodi.\n\nGli allarmi di quest'area sono avvisi che finiscono da soli: un contatore con un proprio allarme, una tensione di rete fuori intervallo (circa 230 V, da 195 a 253) e la perdita dell'ingresso di rete; un guasto bloccato di un contattore è ALTO.\n\nEnergia al giorno: una scheda somma, per l'ultima settimana, ciò che ha contato il contatore di ogni canale. Somma solo la differenza tra le letture, quindi un contatore che riparte a 9.999,99 kWh o da zero dopo un'interruzione non produce un giorno negativo né riconta tutto il suo totale; il giorno in cui accade è segnato.",
      "電気ノード（ARMOR-ELECTRICAL）と設備のライブ配線図です。ノードは RS485 で電力量計を読み取り、系統、分岐回路、太陽光側の電圧・電流・電力・電力量をチャンネルとして報告します。\n\n電気デザイナーで設備を描き、要素をノードに関連付けてあれば、ここの図にライブ値が重ねて表示されます。図面がない場合は、ノードとチャンネルが一覧で表示されます。まだ電気ノードが報告していない場合は、このネットワークでノードの電源を入れ、ノード検索で探すよう案内します。\n\nこの分野のアラームは自然に解除される警告です：電力量計自身のアラーム、系統電圧の範囲外（約 230 V、195～253 V）、系統入力の喪失。接触器のラッチされた故障は「高」です。\n\n日別エネルギー：直近1週間について、各チャンネルのメーターが計測した量を日ごとに合計するカードです。読み取り値の差分だけを加算するため、9,999.99 kWh で一巡するメーターや停電後にゼロから再開するメーターでも、負の日や合計の二重計上は起きません。その日には印が付きます。",
      "电气节点（ARMOR-ELECTRICAL）及设施的实时示意图。节点通过 RS485 读取电能表，并上报通道：市电、分支回路和光伏侧的电压、电流、功率和电能。\n\n如果你在电气设计器中绘制了设施并把元素绑定到节点，这里的示意图会叠加显示实时数值；没有图则以列表显示节点及其通道。尚无电气节点上报时，界面会提示：在此网络中给节点上电，并在节点查找中找到它。\n\n此区域的报警是会自动结束的警告：电表自身报警、市电电压超范围（约 230 V，195 至 253）以及市电输入丢失；接触器的锁存故障为“高”级。\n\n每日电能：一张卡片按天汇总最近一周各通道电表的计量值。它只累加两次读数之间的差值，因此电表在 9,999.99 kWh 回绕或断电后从零重新开始，也不会出现负数日，也不会重复计入全部总量；发生当天会有标记。",
    ] },
  { id: "devices",
    title: ["Devices", "Dispositivos", "Geräte", "Appareils", "Dispositivi", "デバイス", "设备"],
    body: [
      "The sensors, plugs and other things that report to A.R.M.O.R. and, in some cases, that it can switch. \"Add a device\" asks for a name, the room or zone, the kind (door contact, window contact, motion, smoke, CO, gas, water leak, glass break, vibration, panic button, plug, light...), and how it talks to A.R.M.O.R.: through MQTT topics (state, command, availability), through web addresses (on, off, toggle) or through a node. The \"payload mapping\" says which field of the device's JSON message holds each value.\n\nThe kind decides when it raises an alarm: some always (smoke, gas, water), others only while the system is armed (door, motion). If a device is silent for the \"expected interval\" it counts as offline; 0 means never. For devices that never say what they did, \"assume the state after a command\" lets Studio assume the command worked.\n\nEach device can be placed on the site design so you see where it is. \"Test: trigger\" and \"Test: clear\" set the state by hand to try the alarm and the automations without touching the real device.",
      "Los sensores, enchufes y otras cosas que informan a A.R.M.O.R. y que, en algunos casos, este puede accionar. \"Añadir un dispositivo\" pide un nombre, la habitación o zona, el tipo (contacto de puerta, de ventana, movimiento, humo, CO, gas, fuga de agua, rotura de cristal, vibración, botón de pánico, enchufe, luz...), y cómo habla con A.R.M.O.R.: por topics MQTT (estado, orden, disponibilidad), por direcciones web (encender, apagar, alternar) o por un nodo. El \"mapeo de carga\" indica qué campo del mensaje JSON del dispositivo contiene cada valor.\n\nEl tipo decide cuándo genera una alarma: unos siempre (humo, gas, agua), otros solo con el sistema armado (puerta, movimiento). Si un dispositivo calla durante el \"intervalo esperado\" cuenta como sin conexión; 0 significa nunca. Para dispositivos que nunca dicen lo que hicieron, \"suponer el estado tras una orden\" deja que Studio dé por buena la orden.\n\nCada dispositivo puede colocarse en el diseño del sitio para ver dónde está. \"Prueba: disparar\" y \"Prueba: limpiar\" ponen el estado a mano para probar la alarma y las automatizaciones sin tocar el dispositivo real.",
      "Die Sensoren, Steckdosen und anderes, das an A.R.M.O.R. meldet und das dieses teils schalten kann. „Gerät hinzufügen“ fragt nach Name, Raum oder Zone, Art (Türkontakt, Fensterkontakt, Bewegung, Rauch, CO, Gas, Wasserleck, Glasbruch, Vibration, Panikknopf, Steckdose, Licht ...) und wie es mit A.R.M.O.R. spricht: über MQTT-Topics (Zustand, Befehl, Verfügbarkeit), über Webadressen (ein, aus, umschalten) oder über einen Knoten. Die „Payload-Zuordnung“ sagt, welches Feld der JSON-Nachricht des Geräts jeden Wert enthält.\n\nDie Art bestimmt, wann ein Alarm entsteht: manche immer (Rauch, Gas, Wasser), andere nur bei scharfem System (Tür, Bewegung). Schweigt ein Gerät für das „erwartete Intervall“, gilt es als offline; 0 heißt nie. Für Geräte, die nie zurückmelden, lässt „Zustand nach Befehl annehmen“ Studio den Befehl als erfolgreich ansehen.\n\nJedes Gerät kann im Standortplan platziert werden, um zu sehen, wo es ist. „Test: auslösen“ und „Test: löschen“ setzen den Zustand von Hand, um Alarm und Automatisierungen ohne das echte Gerät zu testen.",
      "Les capteurs, prises et autres éléments qui rapportent à A.R.M.O.R. et que celui-ci peut parfois commander. « Ajouter un appareil » demande un nom, la pièce ou zone, le type (contact de porte, de fenêtre, mouvement, fumée, CO, gaz, fuite d'eau, bris de vitre, vibration, bouton panique, prise, lumière...), et comment il parle à A.R.M.O.R. : par topics MQTT (état, commande, disponibilité), par adresses web (marche, arrêt, bascule) ou par un nœud. Le « mappage de charge » dit quel champ du message JSON de l'appareil contient chaque valeur.\n\nLe type décide quand il déclenche une alarme : certains toujours (fumée, gaz, eau), d'autres seulement système armé (porte, mouvement). Si un appareil se tait pendant l'« intervalle attendu », il est hors ligne ; 0 signifie jamais. Pour les appareils qui ne disent jamais ce qu'ils ont fait, « supposer l'état après une commande » laisse Studio considérer la commande réussie.\n\nChaque appareil peut être placé sur le plan du site pour voir où il est. « Test : déclencher » et « Test : effacer » fixent l'état à la main pour essayer l'alarme et les automatisations sans toucher à l'appareil réel.",
      "I sensori, le prese e altre cose che riferiscono ad A.R.M.O.R. e che in alcuni casi questo può azionare. «Aggiungi un dispositivo» chiede un nome, la stanza o zona, il tipo (contatto porta, finestra, movimento, fumo, CO, gas, perdita d'acqua, rottura vetro, vibrazione, pulsante panico, presa, luce...), e come parla con A.R.M.O.R.: tramite topic MQTT (stato, comando, disponibilità), tramite indirizzi web (accendi, spegni, alterna) o tramite un nodo. La «mappatura del payload» dice quale campo del messaggio JSON del dispositivo contiene ogni valore.\n\nIl tipo decide quando genera un allarme: alcuni sempre (fumo, gas, acqua), altri solo a sistema armato (porta, movimento). Se un dispositivo tace per l'«intervallo previsto» risulta offline; 0 significa mai. Per i dispositivi che non dicono mai cosa hanno fatto, «presumi lo stato dopo un comando» lascia che Studio dia il comando per riuscito.\n\nOgni dispositivo può essere posizionato nel progetto del sito per vedere dov'è. «Test: attiva» e «Test: azzera» impostano lo stato a mano per provare l'allarme e le automazioni senza toccare il dispositivo reale.",
      "A.R.M.O.R. に報告するセンサー、プラグなどで、場合によっては A.R.M.O.R. から操作もできるものです。「デバイスを追加」では、名前、部屋またはゾーン、種類（ドア接点、窓接点、動き、煙、CO、ガス、水漏れ、ガラス破損、振動、非常ボタン、プラグ、照明など）、A.R.M.O.R. との通信方法（MQTT トピック：状態/コマンド/可用性、Web アドレス：オン/オフ/切替、またはノード経由）を指定します。「ペイロードマッピング」は、機器の JSON メッセージのどのフィールドに各値があるかを示します。\n\n種類によってアラームの出る条件が決まります。常に出すもの（煙、ガス、水）と、警戒中のみのもの（ドア、動き）があります。「想定間隔」の間応答がなければオフライン扱いで、0 は判定しません。状態を報告しない機器では「コマンド後の状態を仮定」で、Studio がコマンドが成功したものとみなします。\n\n各機器はサイト設計に配置して場所を確認できます。「テスト：発報」「テスト：解除」は、実機に触れずにアラームとオートメーションを試すため状態を手動で設定します。",
      "向 A.R.M.O.R. 上报、并且在某些情况下可由其控制的传感器、插座等。“添加设备”需要填写名称、房间或区域、类型（门磁、窗磁、移动、烟雾、CO、燃气、漏水、玻璃破碎、振动、紧急按钮、插座、灯等），以及与 A.R.M.O.R. 的通信方式：通过 MQTT 主题（状态、命令、可用性）、通过网址（开、关、切换）或通过节点。“负载映射”说明设备 JSON 消息中哪个字段包含各个值。\n\n类型决定何时产生报警：有的始终报警（烟雾、燃气、漏水），有的只在布防时（门、移动）。设备沉默超过“预期间隔”即视为离线，0 表示从不。对从不回报状态的设备，“命令后假定状态”让 Studio 认为命令已生效。\n\n每个设备都可放置在场地设计中以查看位置。“测试：触发”和“测试：清除”手动设置状态，在不触碰实际设备的情况下测试报警和自动化。",
    ] },
  { id: "automations",
    title: ["Automations", "Automatizaciones", "Automatisierungen", "Automatisations", "Automazioni", "オートメーション", "自动化"],
    body: [
      "Rules of the form \"when this happens, do that\". \"New automation\" opens the builder: give it a name, choose WHEN (a device, a camera or a radar node reports something, or the system becomes armed or disarmed), optionally add \"and the system is\" (in any mode, only while armed, only while disarmed), and THEN add one or more actions: switch a device on or off, or send the alarm notification (MQTT and webhook).\n\nAn action on a device can undo itself: \"then back after (seconds)\" returns the device to its previous state after that time; 0 leaves it. Each automation can be enabled or disabled without deleting it. \"Run now\" runs it once whatever the condition; the run is written in the audit trail (System). \"Save rules\" stores the list.\n\nThresholds: besides \"a device reaches a state\", a trigger can be \"a reading goes above or below a value\" - a temperature over 30, a battery under 20 - for a device's temperature, humidity, battery, power or voltage.",
      "Reglas del tipo \"cuando pase esto, haz aquello\". \"Nueva automatización\" abre el constructor: ponle un nombre, elige CUANDO (un dispositivo, una cámara o un nodo radar informa de algo, o el sistema pasa a armado o desarmado), añade opcionalmente \"y el sistema está\" (en cualquier modo, solo armado, solo desarmado) y ENTONCES añade una o más acciones: encender o apagar un dispositivo, o enviar la notificación de alarma (MQTT y webhook).\n\nUna acción sobre un dispositivo puede deshacerse sola: \"luego volver tras (segundos)\" devuelve el dispositivo a su estado anterior pasado ese tiempo; 0 lo deja. Cada automatización puede habilitarse o deshabilitarse sin borrarla. \"Ejecutar ahora\" la ejecuta una vez sea cual sea la condición; la ejecución queda en el registro de auditoría (Sistema). \"Guardar reglas\" guarda la lista.\n\nUmbrales: además de \"un dispositivo llega a un estado\", un disparador puede ser \"una lectura supera o baja de un valor\" - una temperatura por encima de 30, una batería por debajo de 20 - para la temperatura, humedad, batería, potencia o tensión de un dispositivo.",
      "Regeln der Form „wenn dies geschieht, tue das“. „Neue Automatisierung“ öffnet den Editor: Namen vergeben, WENN wählen (ein Gerät, eine Kamera oder ein Radarknoten meldet etwas, oder das System wird scharf oder unscharf), optional „und das System ist“ (in jedem Modus, nur scharf, nur unscharf) und DANN eine oder mehrere Aktionen hinzufügen: ein Gerät ein- oder ausschalten oder die Alarmbenachrichtigung senden (MQTT und Webhook).\n\nEine Aktion an einem Gerät kann sich selbst zurücknehmen: „dann zurück nach (Sekunden)“ stellt den vorigen Zustand nach dieser Zeit wieder her; 0 lässt es. Jede Automatisierung lässt sich aktivieren oder deaktivieren, ohne sie zu löschen. „Jetzt ausführen“ führt sie einmal aus, egal welche Bedingung; der Lauf steht im Audit-Protokoll (System). „Regeln speichern“ speichert die Liste.\n\nSchwellwerte: Neben \"ein Gerät erreicht einen Zustand\" kann ein Auslöser \"ein Messwert über- oder unterschreitet einen Wert\" sein - eine Temperatur über 30, eine Batterie unter 20 - für Temperatur, Feuchtigkeit, Batterie, Leistung oder Spannung eines Geräts.",
      "Des règles du type « quand ceci arrive, fais cela ». « Nouvelle automatisation » ouvre l'éditeur : donnez un nom, choisissez QUAND (un appareil, une caméra ou un nœud radar rapporte quelque chose, ou le système passe armé ou désarmé), ajoutez au besoin « et le système est » (dans tout mode, seulement armé, seulement désarmé) puis ENSUITE une ou plusieurs actions : allumer ou éteindre un appareil, ou envoyer la notification d'alarme (MQTT et webhook).\n\nUne action sur un appareil peut s'annuler d'elle-même : « puis retour après (secondes) » remet l'appareil dans son état précédent après ce délai ; 0 le laisse. Chaque automatisation peut être activée ou désactivée sans la supprimer. « Exécuter maintenant » l'exécute une fois quelle que soit la condition ; l'exécution est notée dans le journal d'audit (Système). « Enregistrer les règles » enregistre la liste.\n\nSeuils : en plus de « un appareil atteint un état », un déclencheur peut être « une mesure dépasse ou passe sous une valeur » - une température au-dessus de 30, une batterie sous 20 - pour la température, l'humidité, la batterie, la puissance ou la tension d'un appareil.",
      "Regole del tipo «quando succede questo, fai quello». «Nuova automazione» apre l'editor: dai un nome, scegli QUANDO (un dispositivo, una telecamera o un nodo radar riferisce qualcosa, o il sistema diventa armato o disarmato), aggiungi se vuoi «e il sistema è» (in qualsiasi modalità, solo armato, solo disarmato) e POI aggiungi una o più azioni: accendere o spegnere un dispositivo, o inviare la notifica di allarme (MQTT e webhook).\n\nUn'azione su un dispositivo può annullarsi da sola: «poi torna dopo (secondi)» riporta il dispositivo allo stato precedente dopo quel tempo; 0 lo lascia. Ogni automazione può essere abilitata o disabilitata senza eliminarla. «Esegui ora» la esegue una volta qualunque sia la condizione; l'esecuzione resta nel registro di audit (Sistema). «Salva regole» salva l'elenco.\n\nSoglie: oltre a \"un dispositivo raggiunge uno stato\", un'attivazione può essere \"una lettura supera o scende sotto un valore\" - una temperatura sopra 30, una batteria sotto 20 - per temperatura, umidità, batteria, potenza o tensione di un dispositivo.",
      "「これが起きたらあれをする」という形のルールです。「新しいオートメーション」でビルダーを開き、名前を付け、いつ（機器・カメラ・レーダーノードの報告、またはシステムの警戒/解除）を選び、必要なら「かつシステムが」（どのモードでも、警戒中のみ、解除中のみ）を追加し、次に 1 つ以上の動作（機器のオン/オフ、またはアラーム通知の送信：MQTT と Webhook）を追加します。\n\n機器への動作は自動で元に戻せます。「その後戻す（秒）」は指定時間後に機器を前の状態に戻し、0 なら戻しません。各オートメーションは削除せずに有効/無効にできます。「今すぐ実行」は条件に関わらず 1 回実行し、実行は監査ログ（システム）に記録されます。「ルールを保存」で一覧を保存します。\n\nしきい値：「機器がある状態になる」に加えて、「測定値がしきい値を上回る／下回る」もトリガーにできます（温度が30超、電池が20未満など）。機器の温度、湿度、電池、電力、電圧に使えます。",
      "“当发生这件事时，做那件事”形式的规则。“新建自动化”打开编辑器：先命名，选择“当”（设备、摄像头或雷达节点上报某事，或系统变为布防/撤防），可选添加“并且系统处于”（任意模式、仅布防、仅撤防），然后添加一个或多个“则”动作：开/关设备，或发送报警通知（MQTT 和 Webhook）。\n\n对设备的动作可自动撤销：“之后恢复（秒）”会在该时间后让设备回到先前状态，0 表示不恢复。每条自动化都可以启用或停用而无需删除。“立即执行”不论条件如何都执行一次，执行记录在审计记录（系统）中。“保存规则”保存列表。\n\n阈值：除了“设备进入某个状态”，触发条件还可以是“读数高于或低于某个值”——例如温度超过 30、电池低于 20——适用于设备的温度、湿度、电池、功率或电压。",
    ] },
  { id: "network",
    title: ["Network", "Red", "Netzwerk", "Réseau", "Rete", "ネットワーク", "网络"],
    body: [
      "What an ARMOR-NETWORK node sees on the local network: the devices, what changed, the outages and the tools to look into each device. The node only observes: it never changes anything on your network by itself.\n\nThe list shows every device with its name, address, MAC, maker and whether it answers. Filters narrow it (all kinds, offline, not known) and the search box looks by name, address, MAC or maker. Opening a device gives you its details: give it a name of your own, a kind and notes, and mark it as known and welcome so it stops raising the new-device alarm. \"Forget what I noted\" removes your notes.\n\nThe tools of a device: Ping and Traceroute (run from the network node), \"Look at the ports now\", \"Look at its web page\" (reads its title), \"Inspect its web login\" (never tries passwords; with a login you saved it can look inside), Wake-on-LAN, and \"Tell me when it connects again\". \"Scan now\" searches the network at once. Events show what changed; Outages the times the internet or the local network stopped working, with start, end and length. The alarms of the network: internet down, local network down, line degraded for a while, new device, an address answered by another MAC, and a port that opened (high for risky ones such as Telnet or remote desktop).",
      "Lo que ve un nodo ARMOR-NETWORK en la red local: los dispositivos, qué ha cambiado, los cortes y las herramientas para mirar cada dispositivo. El nodo solo observa: nunca cambia nada en tu red por sí mismo.\n\nLa lista muestra cada dispositivo con su nombre, dirección, MAC, fabricante y si responde. Los filtros la acotan (todos los tipos, sin conexión, no conocidos) y el cuadro de búsqueda busca por nombre, dirección, MAC o fabricante. Al abrir un dispositivo ves sus detalles: ponle un nombre propio, un tipo y notas, y márcalo como conocido y bienvenido para que deje de generar la alarma de dispositivo nuevo. \"Olvidar lo que anoté\" borra tus notas.\n\nLas herramientas de un dispositivo: Ping y Traceroute (desde el nodo de red), \"Mirar los puertos ahora\", \"Mirar su página web\" (lee su título), \"Inspeccionar su acceso web\" (nunca prueba contraseñas; con un acceso que guardaste puede mirar dentro), Wake-on-LAN y \"Avísame cuando vuelva a conectarse\". \"Escanear ahora\" busca en la red al instante. Eventos muestra qué cambió; Cortes los momentos en que internet o la red local dejaron de funcionar, con inicio, fin y duración. Las alarmas de red: internet caído, red local caída, línea degradada un rato, dispositivo nuevo, una dirección respondida por otra MAC y un puerto que se abre (alta si es de los arriesgados, como Telnet o escritorio remoto).",
      "Was ein ARMOR-NETWORK-Knoten im lokalen Netz sieht: die Geräte, Änderungen, Ausfälle und Werkzeuge, um jedes Gerät anzusehen. Der Knoten beobachtet nur: Er ändert nie von selbst etwas in Ihrem Netz.\n\nDie Liste zeigt jedes Gerät mit Name, Adresse, MAC, Hersteller und ob es antwortet. Filter grenzen sie ein (alle Arten, offline, nicht bekannt), das Suchfeld sucht nach Name, Adresse, MAC oder Hersteller. Ein geöffnetes Gerät zeigt Details: eigener Name, Art und Notizen, und als bekannt und willkommen markieren, damit es den Neugerät-Alarm nicht mehr auslöst. „Meine Angaben vergessen“ entfernt Ihre Notizen.\n\nWerkzeuge eines Geräts: Ping und Traceroute (vom Netzknoten), „Ports jetzt prüfen“, „Webseite ansehen“ (liest den Titel), „Web-Anmeldung prüfen“ (probiert nie Passwörter; mit gespeichertem Zugang kann es hineinsehen), Wake-on-LAN und „Melden, wenn es wieder verbindet“. „Jetzt scannen“ durchsucht das Netz sofort. Ereignisse zeigen Änderungen; Ausfälle die Zeiten, in denen Internet oder lokales Netz ausfielen, mit Beginn, Ende und Dauer. Netzalarme: Internet aus, lokales Netz aus, Leitung eine Weile verschlechtert, neues Gerät, eine Adresse von anderer MAC beantwortet und ein geöffneter Port (HOCH bei riskanten wie Telnet oder Remotedesktop).",
      "Ce qu'un nœud ARMOR-NETWORK voit sur le réseau local : les appareils, ce qui a changé, les pannes et les outils pour examiner chaque appareil. Le nœud observe seulement : il ne change jamais rien de lui-même sur votre réseau.\n\nLa liste montre chaque appareil avec nom, adresse, MAC, fabricant et s'il répond. Les filtres la restreignent (tous types, hors ligne, non connus) et la recherche cherche par nom, adresse, MAC ou fabricant. Ouvrir un appareil donne ses détails : un nom à vous, un type et des notes, et le marquer connu et bienvenu pour qu'il cesse de déclencher l'alarme d'appareil nouveau. « Oublier mes notes » les supprime.\n\nLes outils d'un appareil : Ping et Traceroute (depuis le nœud réseau), « Regarder les ports maintenant », « Regarder sa page web » (lit son titre), « Inspecter sa connexion web » (n'essaie jamais de mots de passe ; avec un identifiant enregistré il peut regarder dedans), Wake-on-LAN et « Prévenez-moi quand il se reconnecte ». « Analyser maintenant » cherche aussitôt sur le réseau. Événements montre ce qui a changé ; Pannes les moments où internet ou le réseau local ont cessé, avec début, fin et durée. Alarmes réseau : internet coupé, réseau local coupé, ligne dégradée un moment, appareil nouveau, adresse répondue par une autre MAC et port ouvert (élevée pour les risqués comme Telnet ou le bureau à distance).",
      "Ciò che un nodo ARMOR-NETWORK vede sulla rete locale: i dispositivi, cosa è cambiato, le interruzioni e gli strumenti per guardare dentro ogni dispositivo. Il nodo osserva soltanto: non cambia mai nulla da solo nella tua rete.\n\nL'elenco mostra ogni dispositivo con nome, indirizzo, MAC, produttore e se risponde. I filtri lo restringono (tutti i tipi, offline, non noti) e la ricerca cerca per nome, indirizzo, MAC o produttore. Aprendo un dispositivo vedi i dettagli: un nome tuo, un tipo e note, e segnalo come noto e benvenuto perché smetta di generare l'allarme di dispositivo nuovo. «Dimentica le mie note» le elimina.\n\nGli strumenti di un dispositivo: Ping e Traceroute (dal nodo di rete), «Guarda le porte ora», «Guarda la sua pagina web» (legge il titolo), «Ispeziona il suo accesso web» (non prova mai password; con un accesso salvato può guardare dentro), Wake-on-LAN e «Avvisami quando si ricollega». «Scansiona ora» cerca subito nella rete. Eventi mostra cosa è cambiato; Interruzioni i momenti in cui internet o la rete locale si sono fermati, con inizio, fine e durata. Allarmi di rete: internet assente, rete locale assente, linea degradata per un po', dispositivo nuovo, un indirizzo risposto da un'altra MAC e una porta aperta (ALTO per quelle rischiose come Telnet o desktop remoto).",
      "ARMOR-NETWORK ノードがローカルネットワークで見ているもの（機器、変化、停止、各機器の調査ツール）です。ノードは観察のみを行い、ネットワークを自分で変更することはありません。\n\n一覧には各機器の名前、アドレス、MAC、メーカー、応答の有無が表示されます。フィルター（すべての種類、オフライン、未登録）で絞り込み、検索欄で名前、アドレス、MAC、メーカーを探せます。機器を開くと詳細が表示され、独自の名前、種類、メモを付け、既知・許可済みにして新規機器アラームを止められます。「メモを消す」で記録を削除します。\n\n機器ごとのツール：Ping と Traceroute（ネットワークノードから実行）、「ポートを今確認」、「Web ページを見る」（タイトルを読む）、「Web ログインを調べる」（パスワードは試さず、保存したログインがあれば中も確認）、Wake-on-LAN、「再接続したら知らせる」。「今スキャン」は即時にネットワークを探します。「イベント」は変化、「停止」はインターネットやローカルネットワークが止まった時間（開始、終了、長さ）を示します。ネットワークのアラーム：インターネット断、ローカルネットワーク断、回線品質低下、新規機器、別の MAC が応答したアドレス、開いたポート（Telnet やリモートデスクトップなど危険なものは「高」）。",
      "ARMOR-NETWORK 节点在本地网络中看到的内容：设备、变化、中断以及检查各设备的工具。节点只做观察，绝不会自行更改你的网络。\n\n列表显示每个设备的名称、地址、MAC、厂商以及是否响应。筛选器可缩小范围（所有类型、离线、未知），搜索框按名称、地址、MAC 或厂商查找。打开设备可查看详情：设置自己的名称、类型和备注，并标记为已知且受欢迎，使其不再触发新设备报警。“忘记我的备注”会删除你的备注。\n\n设备的工具：Ping 和 Traceroute（从网络节点执行）、“立即查看端口”、“查看其网页”（读取标题）、“检查其网页登录”（绝不尝试密码；有已保存的登录信息时可查看内部）、Wake-on-LAN 以及“重新连接时通知我”。“立即扫描”会马上搜索网络。“事件”显示变化；“中断”显示互联网或本地网络停止工作的时段，含开始、结束和时长。网络报警：互联网中断、本地网络中断、线路持续变差、新设备、地址被另一 MAC 应答，以及开放端口（Telnet、远程桌面等风险端口为“高”级）。",
    ] },
  { id: "siteDesigner",
    title: ["Site designer", "Diseñador del sitio", "Standort-Designer", "Concepteur de site", "Progettazione del sito", "サイトデザイナー", "场地设计器"],
    body: [
      "Draw your property and place everything on it. There are two views of the same design: a flat 2D plan and a 3D view you can turn around.\n\nStart from a blank site or \"Start from an example\". Draw the terrain (rectangle or any shape, corner by corner; type a length and press Enter for exact sides) and the buildings, then add doors, windows, arches, garage doors, roofs (with gutters, chimneys, solar panels), terraces, pools, fences, trees, paths, roads, lamps, masts and much more from the toolbox. Floors are chosen in the floor selector; \"Add a floor\" puts one above.\n\nThen place the real equipment: cameras (created in Configuration, they only get their position here), radars (with the round handle to turn them), and devices where they really are. In 3D, the field of view of cameras and radars is drawn; \"Ignore zones\" of the radars are also set here.\n\nUseful controls: Select moves and edits; Move drags across the ground; Elevate sets the height; undo and redo; grid, snap to grid and walls, dimensions; layers; X-ray and shadows in 3D; the north direction; fit the site in view. \"Export site JSON\" downloads the whole design; \"Versions\" shows the earlier saved versions and lets you go back to one. The design is kept on the server, so every browser sees the same.\n\nBlocks of flats and more objects: select a rectangular building and, in its properties, \"Block of flats\" fills it with floors, a corridor with the flats on both sides, the stairs and the lift, a window for every flat, the street door with its video intercom, a monitor in every flat, the alarm panel and keypad in the hall, stair lights and mailboxes (doing it again replaces what it made). The Interior panel has mirrors, elevators, stair lights, radiators, a washing machine, a fridge, a desk, plants and rugs, and the ARMOR equipment panel has the video intercom, the intercom monitor, the alarm panel and the alarm keypad. A video intercom can be tied to a camera, an alarm panel or keypad to a real panel and a stair light to a device: the object shows what the thing says now and a button opens that menu. Gates can be farm, sliding or cantilever and motorised; garage doors can be sectional, roller, swing, up-and-over, sliding, bi-fold or side sectional; garage doors and window roller shutters can have a motor, and the motor, a motorised gate, the electric water heater and the pump of a solar circuit can be tied to a device. The Interior panel also has water heaters, hot water tanks and solar circuit tanks, and roofs take a solar water heater. In the Electrical Designer, \"Draw the motors and water equipment of the site\" adds all of them as loads, once.",
      "Dibuja tu propiedad y coloca todo en ella. Hay dos vistas del mismo diseño: un plano 2D plano y una vista 3D que puedes girar.\n\nEmpieza con un sitio vacío o con \"Empezar con un ejemplo\". Dibuja el terreno (rectángulo o cualquier forma, esquina a esquina; escribe una longitud y pulsa Intro para lados exactos) y los edificios, y añade puertas, ventanas, arcos, puertas de garaje, tejados (con canalones, chimeneas, placas solares), terrazas, piscinas, vallas, árboles, caminos, carreteras, farolas, mástiles y mucho más desde la caja de herramientas. Las plantas se eligen en el selector de planta; \"Añadir una planta\" pone una encima.\n\nLuego coloca el equipo real: cámaras (se crean en Configuración, aquí solo reciben su posición), radares (con el tirador redondo para girarlos) y dispositivos donde están de verdad. En 3D se dibuja el campo de visión de cámaras y radares; las \"zonas a ignorar\" de los radares también se ponen aquí.\n\nControles útiles: Seleccionar mueve y edita; Mover arrastra por el suelo; Elevar fija la altura; deshacer y rehacer; cuadrícula, ajustar a cuadrícula y muros, cotas; capas; rayos X y sombras en 3D; la dirección del norte; encajar el sitio en la vista. \"Exportar JSON del sitio\" descarga todo el diseño; \"Versiones\" muestra las versiones guardadas antes y deja volver a una. El diseño se guarda en el servidor, así que todos los navegadores ven lo mismo.\n\nBloques de pisos y más objetos: selecciona un edificio rectangular y, en sus propiedades, \"Bloque de pisos\" lo llena con plantas, un pasillo con las viviendas a ambos lados, la escalera y el ascensor, una ventana por vivienda, la puerta de calle con su videoportero, un telefonillo en cada vivienda, la central de alarma y el teclado en el portal, luces de escalera y buzones (si lo repites, sustituye lo que hizo). El panel Interior tiene espejos, ascensores, luces de escalera, radiadores, una lavadora, una nevera, un escritorio, plantas y alfombras, y el panel de equipos ARMOR tiene el videoportero, el telefonillo, la central de alarma y el teclado de alarma. Un videoportero se puede vincular a una cámara, una central o un teclado de alarma a una central real y una luz de escalera a un dispositivo: el objeto muestra lo que dice la cosa vinculada y un botón abre ese menú. Las cancelas pueden ser de finca, correderas o autoportantes y motorizadas; las puertas de garaje seccionales, enrollables, batientes, basculantes, correderas, plegables o seccionales laterales; las puertas de garaje y las persianas de las ventanas pueden llevar motor, y el motor, la cancela motorizada, el termo eléctrico y la bomba de un circuito solar se pueden enlazar con un dispositivo. El panel Interior tiene además termos, depósitos de agua caliente y depósitos del circuito solar, y los tejados admiten un calentador solar de agua. En el Diseñador eléctrico, «Dibujar los motores y el agua caliente del emplazamiento» los añade todos como cargas, una sola vez.",
      "Zeichnen Sie Ihr Grundstück und platzieren Sie alles darauf. Es gibt zwei Ansichten desselben Entwurfs: einen flachen 2D-Plan und eine drehbare 3D-Ansicht.\n\nBeginnen Sie mit einem leeren Standort oder „Mit einem Beispiel beginnen“. Zeichnen Sie das Gelände (Rechteck oder beliebige Form, Ecke für Ecke; Länge tippen und Enter drücken für exakte Seiten) und die Gebäude, dann fügen Sie aus der Werkzeugleiste Türen, Fenster, Bögen, Garagentore, Dächer (mit Dachrinnen, Schornsteinen, Solarmodulen), Terrassen, Pools, Zäune, Bäume, Wege, Straßen, Laternen, Masten und vieles mehr hinzu. Stockwerke wählen Sie im Stockwerkswähler; „Stockwerk hinzufügen“ setzt eines darüber.\n\nDann platzieren Sie die echte Ausrüstung: Kameras (in der Konfiguration angelegt, hier erhalten sie nur ihre Position), Radare (mit dem runden Griff zum Drehen) und Geräte dort, wo sie wirklich sind. In 3D wird das Sichtfeld von Kameras und Radaren gezeichnet; auch die „Ignorierzonen“ der Radare werden hier gesetzt.\n\nNützliche Bedienelemente: Auswählen verschiebt und bearbeitet; Verschieben zieht über den Boden; Anheben setzt die Höhe; Rückgängig und Wiederholen; Raster, Einrasten an Raster und Wänden, Maße; Ebenen; Röntgen und Schatten in 3D; die Nordrichtung; Standort einpassen. „Standort-JSON exportieren“ lädt den ganzen Entwurf herunter; „Versionen“ zeigt frühere Stände und erlaubt die Rückkehr. Der Entwurf liegt auf dem Server, jeder Browser sieht dasselbe.\n\nWohnblöcke und mehr Objekte: Wählen Sie ein rechteckiges Gebäude, und in seinen Eigenschaften füllt „Wohnblock“ es mit Stockwerken, einem Flur mit den Wohnungen auf beiden Seiten, Treppe und Aufzug, einem Fenster je Wohnung, der Haustür mit Video-Türsprechanlage, einem Monitor in jeder Wohnung, Alarmzentrale und Bedienteil im Flur, Treppenlicht und Briefkästen (Wiederholen ersetzt das Frühere). Das Panel Innenraum hat Spiegel, Aufzüge, Treppenlicht, Heizkörper, eine Waschmaschine, einen Kühlschrank, einen Schreibtisch, Pflanzen und Teppiche, das ARMOR-Geräte-Panel die Video-Türsprechanlage, die Sprechstelle, die Alarmzentrale und das Alarm-Bedienteil. Eine Video-Türsprechanlage lässt sich mit einer Kamera, eine Alarmzentrale oder ein Bedienteil mit einer echten Zentrale und ein Treppenlicht mit einem Gerät verknüpfen: Das Objekt zeigt, was das Verknüpfte meldet, und eine Schaltfläche öffnet dieses Menü. Tore können Weide-, Schiebe- oder freitragende Tore und motorisiert sein; Garagentore Sektional-, Roll-, Schwing-, Schwenk-, Schiebe-, Falt- oder Seiten-Sektionaltore; Garagentore und Rollläden von Fenstern können einen Motor haben, und der Motor, ein motorisiertes Tor, der Elektro-Warmwasserspeicher und die Pumpe eines Solarkreises lassen sich mit einem Gerät verknüpfen. Das Panel Innenraum hat auch Warmwasserbereiter, Warmwasserspeicher und Solarspeicher, und Dächer nehmen einen solaren Warmwasserbereiter auf. Im Elektro-Designer fügt „Motoren und Warmwasser des Standorts zeichnen“ alle einmalig als Lasten hinzu.",
      "Dessinez votre propriété et placez-y tout. Deux vues du même plan : un plan 2D à plat et une vue 3D que l'on peut faire tourner.\n\nCommencez par un site vide ou « Partir d'un exemple ». Dessinez le terrain (rectangle ou forme libre, coin par coin ; tapez une longueur et appuyez sur Entrée pour des côtés exacts) et les bâtiments, puis ajoutez depuis la boîte à outils portes, fenêtres, arcs, portes de garage, toits (avec gouttières, cheminées, panneaux solaires), terrasses, piscines, clôtures, arbres, chemins, routes, lampadaires, mâts et bien plus. Les étages se choisissent dans le sélecteur d'étage ; « Ajouter un étage » en met un au-dessus.\n\nPlacez ensuite le vrai matériel : caméras (créées dans Configuration, elles reçoivent ici seulement leur position), radars (avec la poignée ronde pour les orienter) et appareils là où ils sont vraiment. En 3D, le champ de vision des caméras et radars est dessiné ; les « zones à ignorer » des radars se règlent aussi ici.\n\nCommandes utiles : Sélection déplace et édite ; Déplacer glisse sur le sol ; Élever règle la hauteur ; annuler et rétablir ; grille, accrochage à la grille et aux murs, cotes ; calques ; rayons X et ombres en 3D ; la direction du nord ; cadrer le site. « Exporter le JSON du site » télécharge tout le plan ; « Versions » montre les versions précédentes et permet d'y revenir. Le plan est gardé sur le serveur : tous les navigateurs voient la même chose.\n\nImmeubles et plus d'objets : sélectionnez un bâtiment rectangulaire et, dans ses propriétés, « Immeuble d'appartements » le remplit d'étages, d'un couloir avec les appartements des deux côtés, de l'escalier et de l'ascenseur, d'une fenêtre par appartement, de la porte de rue avec son visiophone, d'un moniteur dans chaque appartement, de la centrale d'alarme et du clavier dans le hall, d'éclairages d'escalier et de boîtes aux lettres (recommencer remplace ce qui a été fait). Le panneau Intérieur a des miroirs, ascenseurs, éclairages d'escalier, radiateurs, un lave-linge, un réfrigérateur, un bureau, des plantes et des tapis, et le panneau des équipements ARMOR a le visiophone, le moniteur d'interphone, la centrale d'alarme et le clavier d'alarme. Un visiophone peut être lié à une caméra, une centrale ou un clavier d'alarme à une vraie centrale et un éclairage d'escalier à un appareil : l'objet montre ce que dit ce à quoi il est lié et un bouton ouvre ce menu. Les portails peuvent être de ferme, coulissants ou autoportants et motorisés ; les portes de garage sectionnelles, enroulables, battantes, basculantes, coulissantes, pliantes ou sectionnelles latérales ; les portes de garage et les volets roulants des fenêtres peuvent avoir un moteur, et le moteur, un portail motorisé, le chauffe-eau électrique et la pompe d'un circuit solaire peuvent être liés à un appareil. Le panneau Intérieur a aussi des chauffe-eau, des ballons d'eau chaude et des ballons de circuit solaire, et les toits accueillent un chauffe-eau solaire. Dans le Concepteur électrique, « Dessiner les moteurs et l'eau chaude de l'emplacement » les ajoute tous comme charges, une seule fois.",
      "Disegna la tua proprietà e posizionaci tutto. Due viste dello stesso progetto: una pianta 2D piana e una vista 3D che puoi ruotare.\n\nParti da un sito vuoto o da «Parti da un esempio». Disegna il terreno (rettangolo o forma libera, angolo per angolo; scrivi una lunghezza e premi Invio per lati esatti) e gli edifici, poi aggiungi dalla cassetta degli strumenti porte, finestre, archi, porte da garage, tetti (con grondaie, camini, pannelli solari), terrazzi, piscine, recinzioni, alberi, sentieri, strade, lampioni, pali e molto altro. I piani si scelgono nel selettore di piano; «Aggiungi un piano» ne mette uno sopra.\n\nPoi posiziona l'attrezzatura reale: telecamere (create in Configurazione, qui ricevono solo la posizione), radar (con la maniglia rotonda per ruotarli) e dispositivi dove sono davvero. In 3D si disegna il campo visivo di telecamere e radar; anche le «zone da ignorare» dei radar si impostano qui.\n\nControlli utili: Seleziona sposta e modifica; Sposta trascina sul terreno; Alza imposta l'altezza; annulla e ripristina; griglia, aggancio a griglia e muri, quote; livelli; raggi X e ombre in 3D; la direzione del nord; inquadra il sito. «Esporta JSON del sito» scarica tutto il progetto; «Versioni» mostra le versioni salvate in precedenza e permette di tornare a una. Il progetto è sul server, quindi ogni browser vede lo stesso.\n\nCondomini e più oggetti: seleziona un edificio rettangolare e, nelle sue proprietà, \"Condominio\" lo riempie con piani, un corridoio con gli appartamenti ai due lati, scala e ascensore, una finestra per appartamento, il portone con il videocitofono, un monitor in ogni appartamento, la centrale di allarme e la tastiera nell'androne, luci per le scale e cassette postali (ripetere sostituisce quanto fatto). Il pannello Interni ha specchi, ascensori, luci per le scale, termosifoni, una lavatrice, un frigorifero, una scrivania, piante e tappeti, e il pannello delle apparecchiature ARMOR ha il videocitofono, il monitor del citofono, la centrale di allarme e la tastiera di allarme. Un videocitofono si può collegare a una telecamera, una centrale o una tastiera di allarme a una centrale reale e una luce per le scale a un dispositivo: l'oggetto mostra ciò che dice il collegato e un pulsante apre quel menu. I cancelli possono essere da campo, scorrevoli o autoportanti e motorizzati; le porte del garage sezionali, avvolgibili, a battente, basculanti, scorrevoli, pieghevoli o sezionali laterali; le porte del garage e le tapparelle delle finestre possono avere un motore, e il motore, un cancello motorizzato, lo scaldabagno elettrico e la pompa di un circuito solare si possono collegare a un dispositivo. Il pannello Interni ha anche scaldabagni, serbatoi di acqua calda e serbatoi del circuito solare, e i tetti accolgono uno scaldacqua solare. Nel Progettista elettrico, «Disegna i motori e l'acqua calda del sito» li aggiunge tutti come carichi, una sola volta.",
      "敷地を描き、その上にすべてを配置します。同じ設計の 2 つのビュー：平らな 2D 平面図と、回転できる 3D ビューがあります。\n\n空のサイトまたは「例から始める」で開始します。敷地（長方形または自由な形、角ごとに描画。長さを入力して Enter で正確な辺）と建物を描き、ツールボックスからドア、窓、アーチ、ガレージドア、屋根（樋、煙突、太陽光パネル付き）、テラス、プール、フェンス、樹木、小道、道路、街灯、マストなどを追加します。階は階セレクターで選び、「階を追加」で上に 1 階増やします。\n\n次に実際の機器を配置します：カメラ（設定で作成し、ここでは位置のみ設定）、レーダー（丸いハンドルで向きを変更）、実際の場所の機器。3D ではカメラとレーダーの視野が描かれ、レーダーの「無視ゾーン」もここで設定します。\n\n便利な操作：選択（移動と編集）、移動（地面上をドラッグ）、高さ（高さ設定）、元に戻す/やり直し、グリッド、グリッド/壁へのスナップ、寸法、レイヤー、3D の透視と影、北の方向、サイトを画面に合わせる。「サイト JSON を書き出し」で設計全体をダウンロードし、「バージョン」で過去の保存版に戻せます。設計はサーバーに保存されるので、どのブラウザでも同じ内容が見えます。\n\n集合住宅とオブジェクトの追加：長方形の建物を選び、そのプロパティの「集合住宅にする」で、階、両側に住戸が並ぶ廊下、階段とエレベーター、住戸ごとの窓、ビデオインターホン付きの玄関、各住戸のモニター、ホールの警報制御盤とキーパッド、階段灯、郵便受けを配置します（もう一度実行すると置き換え）。室内パネルには鏡、エレベーター、階段灯、ラジエーター、洗濯機、冷蔵庫、デスク、観葉植物、ラグがあり、ARMOR 機器パネルにはビデオインターホン、インターホンモニター、警報制御盤、警報キーパッドがあります。ビデオインターホンはカメラに、警報制御盤とキーパッドは実際の制御盤に、階段灯はデバイスに関連付けられ、関連付け先の状態が表示され、ボタンでそのメニューを開けます。 ゲートは農場用・スライド式・片持ち式で電動にでき、ガレージドアはセクショナル・ロール・スイング・跳ね上げ・スライド・折りたたみ・横引きセクショナルから選べます。ガレージドアと窓のシャッターにはモーターを付けられ、モーター・電動ゲート・電気温水器・ソーラー回路のポンプはデバイスに関連付けられます。室内パネルには温水器・貯湯タンク・ソーラー回路タンクもあり、屋根には太陽熱温水器を置けます。電気設計では「敷地のモーターと給湯設備を描く」で、すべてを負荷として一度だけ追加します。",
      "绘制你的场地并把一切放在上面。同一设计有两种视图：平面 2D 图和可旋转的 3D 视图。\n\n从空白场地或“从示例开始”。绘制场地（矩形或任意形状，逐角绘制；输入长度并按 Enter 得到精确边长）和建筑，然后从工具箱添加门、窗、拱门、车库门、屋顶（含排水槽、烟囱、光伏板）、露台、泳池、围栏、树木、小路、道路、灯柱、桅杆等。楼层在楼层选择器中选择；“添加楼层”会在上方加一层。\n\n然后放置真实设备：摄像头（在“配置”中创建，这里只设置位置）、雷达（用圆形手柄旋转）以及设备的实际位置。3D 中会绘制摄像头和雷达的视野；雷达的“忽略区域”也在这里设置。\n\n常用控制：选择（移动和编辑）、移动（在地面拖动）、抬升（设置高度）、撤销和重做、网格、吸附网格和墙体、尺寸、图层、3D 透视和阴影、正北方向、将场地适配视图。“导出场地 JSON”下载整个设计；“版本”显示以前保存的版本并可恢复。设计保存在服务器上，所有浏览器看到的内容一致。\n\n公寓楼与更多物体：选择一栋矩形建筑，在其属性中点击“生成公寓楼”，即可用楼层、两侧为住户的走廊、楼梯和电梯、每户一扇窗、带可视对讲的单元门、每户室内分机、门厅的报警主机和键盘、楼梯灯及信箱填充(再次执行会替换)。室内面板新增镜子、电梯、楼梯灯、暖气片、洗衣机、冰箱、书桌、绿植和地毯，ARMOR 设备面板新增可视对讲、对讲分机、报警主机和报警键盘。可视对讲可关联摄像头，报警主机或键盘可关联真实主机，楼梯灯可关联设备：物体会显示所关联对象的当前状态，按钮可打开相应菜单。 大门可选农场、推拉或悬臂式并可电动；车库门可选分节、卷帘、平开、翻板、推拉、折叠或侧向分节；车库门和窗户卷帘可带电机，电机、电动大门、电热水器和太阳能回路水泵都可关联到设备。室内面板还有热水器、热水储水罐和太阳能回路水箱，屋顶可放太阳能热水器。在电气设计器中，“绘制场地的电机和热水设备”会一次性把它们全部作为负载加入。",
    ] },
  { id: "alarmDesigner",
    title: ["Alarm designer", "Diseñador de alarma", "Alarmplaner", "Concepteur d'alarme", "Progettista di allarme", "警報設計", "报警设计"],
    body: [
      "Draw the alarm of the house: the panels (the alarm panel, zone expanders and the communicator), the sensors (door and window contacts, motion and dual-technology detectors, outdoor beams, glass-break and vibration sensors, smoke, heat, carbon monoxide, gas and flood detectors, panic buttons and tamper switches), the sirens and outputs, the keypads, card readers, key fobs and touch panels, and the supply (power supply and backup battery). \"A typical house\" loads an example.\n\nPick an element in the toolbox and click to place it; Rotate (R) turns it; \"Change the kind\" swaps it for another of the same group and keeps its links. The Link tool joins two ports of the same kind: click one, then the other. There are five kinds of link: the wired loop (a sensor to a loop of the panel), the radio link, the siren output, the data bus (keypads and expanders) and the supply. A sensor reaches its panel by its wire or by radio, not by both. A frame groups elements in a room or a floor.\n\nThe drawing is tied to reality: tie a drawn panel to a real one, and a drawn sensor to one of its zones, and the element shows live what the panel says - green when normal, red when the zone is open or the panel sounds, grey when the panel stopped reporting. \"Draw what the panels have\" adds every panel and zone that is not yet in the drawing, each sensor guessed from the name of its zone. From the properties of a tied element, \"Open the Alarm panels menu\" takes you to the real panel.\n\nThe checks warn of a sensor nobody listens to, more loops joined than zones in use, a panel with no siren, no keypad or no backup battery, a wireless sensor with no battery type, a smoke or flood sensor that would be silent while disarmed, and zones that the panel has and the drawing does not. It is a guide for reviewing the drawing, not proof that the house is protected; nothing here arms or sounds anything. Files: export the drawing as JSON or SVG, import it, and see the earlier versions the server keeps. The drawing is kept on the server.",
      "Dibuja la alarma de la casa: las centrales (la central de alarma, los expansores de zonas y el comunicador), los sensores (contactos de puertas y ventanas, detectores de movimiento y de doble tecnología, barreras exteriores, sensores de rotura de cristal y vibración, detectores de humo, calor, monóxido de carbono, gas e inundación, botones de pánico e interruptores antisabotaje), las sirenas y salidas, los teclados, lectores de tarjetas, mandos y paneles táctiles, y la alimentación (fuente y batería de respaldo). \"Una casa típica\" carga un ejemplo.\n\nElige un elemento en la caja de herramientas y haz clic para colocarlo; Girar (R) lo gira; \"Cambiar el tipo\" lo cambia por otro del mismo grupo y conserva sus enlaces. La herramienta Enlace une dos puertos del mismo tipo: haz clic en uno y luego en el otro. Hay cinco tipos de enlace: el lazo cableado (un sensor a un lazo de la central), el enlace por radio, la salida de sirena, el bus de datos (teclados y expansores) y la alimentación. Un sensor llega a su central por su cable o por radio, no por ambos. Un marco agrupa elementos en una habitación o una planta.\n\nEl dibujo se vincula con la realidad: vincula una central dibujada con una real, y un sensor dibujado con una de sus zonas, y el elemento muestra en vivo lo que dice la central - verde si todo está normal, rojo si la zona está abierta o la central suena, gris si la central dejó de informar. \"Dibujar lo que tienen las centrales\" añade cada central y zona que aún no está en el dibujo, adivinando cada sensor por el nombre de su zona. Desde las propiedades de un elemento vinculado, \"Abrir el menú Centrales de alarma\" te lleva a la central real.\n\nLas comprobaciones avisan de un sensor al que nadie escucha, más lazos unidos que zonas en uso, una central sin sirena, sin teclado o sin batería de respaldo, un sensor inalámbrico sin tipo de pila, un sensor de humo o de agua que callaría con el sistema desarmado, y zonas que la central tiene y el dibujo no. Es una guía para revisar el dibujo, no una prueba de que la casa esté protegida; nada de aquí arma ni hace sonar nada. Archivos: exporta el dibujo como JSON o SVG, impórtalo y mira las versiones anteriores que guarda el servidor. El dibujo se guarda en el servidor.",
      "Zeichnen Sie die Alarmanlage des Hauses: die Zentralen (Alarmzentrale, Zonenerweiterungen und Kommunikator), die Melder (Tür- und Fensterkontakte, Bewegungs- und Dualmelder, Außen-Lichtschranken, Glasbruch- und Erschütterungsmelder, Rauch-, Wärme-, Kohlenmonoxid-, Gas- und Wassermelder, Panikknöpfe und Sabotagekontakte), die Sirenen und Ausgänge, die Bedienteile, Kartenleser, Handsender und Touchpanels sowie die Versorgung (Netzteil und Pufferbatterie). „Ein typisches Haus“ lädt ein Beispiel.\n\nWählen Sie ein Element in der Werkzeugleiste und klicken Sie zum Platzieren; Drehen (R) dreht es; „Typ ändern“ tauscht es gegen ein anderes derselben Gruppe und behält die Verbindungen. Das Werkzeug Verbindung verbindet zwei Anschlüsse gleicher Art: erst einen anklicken, dann den anderen. Es gibt fünf Arten: die verdrahtete Schleife (Melder zu einer Schleife der Zentrale), die Funkverbindung, den Sirenenausgang, den Datenbus (Bedienteile und Erweiterungen) und die Versorgung. Ein Melder erreicht seine Zentrale per Kabel oder per Funk, nicht beides. Ein Rahmen fasst Elemente zu einem Raum oder Stockwerk zusammen.\n\nDie Zeichnung wird mit der Wirklichkeit verknüpft: Verknüpfen Sie eine gezeichnete Zentrale mit einer echten und einen gezeichneten Melder mit einer ihrer Zonen, und das Element zeigt live, was die Zentrale meldet - grün bei normal, rot bei offener Zone oder ertönender Zentrale, grau, wenn die Zentrale sich nicht mehr meldet. „Zeichnen, was die Zentralen haben“ fügt jede Zentrale und Zone hinzu, die noch nicht in der Zeichnung ist; jeder Melder wird am Namen seiner Zone erraten. In den Eigenschaften eines verknüpften Elements führt „Menü Alarmzentralen öffnen“ zur echten Zentrale.\n\nDie Prüfungen warnen vor einem Melder, den niemand hört, mehr verbundenen Schleifen als genutzten Zonen, einer Zentrale ohne Sirene, ohne Bedienteil oder ohne Pufferbatterie, einem Funkmelder ohne Batterietyp, einem Rauch- oder Wassermelder, der bei unscharfer Anlage schwiege, und Zonen, die die Zentrale hat, die Zeichnung aber nicht. Es ist eine Hilfe zur Durchsicht, kein Nachweis, dass das Haus geschützt ist; nichts hier schaltet scharf oder lässt etwas ertönen. Dateien: Zeichnung als JSON oder SVG exportieren, importieren und frühere Versionen des Servers ansehen. Die Zeichnung wird auf dem Server gespeichert.",
      "Dessinez l'alarme de la maison : les centrales (la centrale d'alarme, les extensions de zones et le communicateur), les capteurs (contacts de portes et de fenêtres, détecteurs de mouvement et double technologie, barrières extérieures, capteurs de bris de vitre et de vibration, détecteurs de fumée, de chaleur, de monoxyde de carbone, de gaz et d'inondation, boutons panique et contacts d'autoprotection), les sirènes et sorties, les claviers, lecteurs de cartes, télécommandes et panneaux tactiles, et l'alimentation (bloc d'alimentation et batterie de secours). « Une maison typique » charge un exemple.\n\nChoisissez un élément dans la boîte à outils et cliquez pour le placer ; Pivoter (R) le tourne ; « Changer le type » le remplace par un autre du même groupe en gardant ses liaisons. L'outil Liaison relie deux ports de même nature : cliquez sur l'un puis sur l'autre. Il y a cinq sortes de liaison : la boucle filaire (un capteur à une boucle de la centrale), la liaison radio, la sortie sirène, le bus de données (claviers et extensions) et l'alimentation. Un capteur joint sa centrale par son fil ou par radio, pas par les deux. Un cadre regroupe des éléments dans une pièce ou un étage.\n\nLe dessin se lie à la réalité : liez une centrale dessinée à une vraie, et un capteur dessiné à l'une de ses zones, et l'élément montre en direct ce que dit la centrale - vert si normal, rouge si la zone est ouverte ou si la centrale sonne, gris si la centrale ne rapporte plus. « Dessiner ce que les centrales ont » ajoute chaque centrale et zone qui n'est pas encore dans le dessin, chaque capteur étant deviné d'après le nom de sa zone. Depuis les propriétés d'un élément lié, « Ouvrir le menu Centrales d'alarme » mène à la vraie centrale.\n\nLes contrôles signalent un capteur que personne n'écoute, plus de boucles reliées que de zones utilisées, une centrale sans sirène, sans clavier ou sans batterie de secours, un capteur sans fil sans type de pile, un détecteur de fumée ou d'eau qui resterait muet système désarmé, et des zones que la centrale a et que le dessin n'a pas. C'est un guide pour relire le dessin, pas une preuve que la maison est protégée ; rien ici n'arme ni ne fait sonner quoi que ce soit. Fichiers : exporter le dessin en JSON ou SVG, l'importer, et voir les versions précédentes gardées par le serveur. Le dessin est conservé sur le serveur.",
      "Disegna l'allarme della casa: le centrali (la centrale di allarme, le espansioni di zone e il comunicatore), i sensori (contatti di porte e finestre, rilevatori di movimento e a doppia tecnologia, barriere esterne, sensori di rottura vetro e vibrazione, rilevatori di fumo, calore, monossido di carbonio, gas e allagamento, pulsanti antipanico e interruttori antimanomissione), le sirene e le uscite, le tastiere, i lettori di tessere, i telecomandi e i pannelli touch, e l'alimentazione (alimentatore e batteria tampone). \"Una casa tipica\" carica un esempio.\n\nScegli un elemento nella casella degli strumenti e clicca per posizionarlo; Ruota (R) lo gira; \"Cambia il tipo\" lo sostituisce con un altro dello stesso gruppo mantenendo i collegamenti. Lo strumento Collegamento unisce due porte dello stesso tipo: clicca su una e poi sull'altra. Ci sono cinque tipi di collegamento: l'anello cablato (un sensore a un anello della centrale), il collegamento radio, l'uscita sirena, il bus dati (tastiere ed espansioni) e l'alimentazione. Un sensore raggiunge la sua centrale via cavo o via radio, non in entrambi i modi. Un riquadro raggruppa gli elementi in una stanza o un piano.\n\nIl disegno si lega alla realtà: collega una centrale disegnata a una reale, e un sensore disegnato a una delle sue zone, e l'elemento mostra in diretta ciò che dice la centrale - verde se normale, rosso se la zona è aperta o la centrale suona, grigio se la centrale non risponde più. \"Disegna ciò che hanno le centrali\" aggiunge ogni centrale e zona non ancora nel disegno, ogni sensore indovinato dal nome della sua zona. Dalle proprietà di un elemento collegato, \"Apri il menu Centrali di allarme\" porta alla centrale reale.\n\nI controlli avvisano di un sensore che nessuno ascolta, più anelli collegati che zone in uso, una centrale senza sirena, senza tastiera o senza batteria tampone, un sensore wireless senza tipo di batteria, un rilevatore di fumo o acqua che tacerebbe a impianto disattivato, e zone che la centrale ha e il disegno no. È una guida per rivedere il disegno, non una prova che la casa sia protetta; niente qui attiva né fa suonare nulla. File: esporta il disegno in JSON o SVG, importalo e guarda le versioni precedenti conservate dal server. Il disegno è conservato sul server.",
      "家の警報を描きます：制御盤（警報制御盤、ゾーン拡張、通報装置）、センサー（ドア・窓の接点、人感・デュアル検知器、屋外ビーム、ガラス破壊・振動センサー、煙・熱・一酸化炭素・ガス・浸水の検知器、非常ボタン、改ざんスイッチ）、サイレンと出力、キーパッド・カードリーダー・キーフォブ・タッチパネル、電源（電源装置とバックアップ電池）。「一般的な家」で例を読み込めます。\n\nツールボックスから要素を選び、クリックして置きます。回転（R）で向きを変え、「種類を変更」で同じグループの別の要素に置き換えます（リンクは維持）。リンクツールは同じ種類のポート同士をつなぎます：一方をクリックし、次にもう一方をクリックします。リンクは5種類です：有線ループ（センサーから制御盤のループへ）、無線リンク、サイレン出力、データバス（キーパッドと拡張）、電源。センサーは有線か無線のどちらか一方で制御盤につながります。枠で部屋や階ごとに要素をまとめられます。\n\n図は実物と関連付けられます：描いた制御盤を実際の制御盤に、描いたセンサーをそのゾーンに関連付けると、制御盤の報告がライブで表示されます。正常は緑、ゾーンが開いている／制御盤が鳴動中は赤、報告が止まっていればグレーです。「制御盤にあるものを描く」で、図にない制御盤とゾーンをすべて追加します（センサーの種類はゾーン名から推測）。関連付け済み要素のプロパティから「警報制御盤メニューを開く」で実際の制御盤に移動できます。\n\nチェックは、誰も受けていないセンサー、使用ゾーン数より多いループ接続、サイレン・キーパッド・バックアップ電池のない制御盤、電池の種類がない無線センサー、解除中に鳴らない煙・浸水センサー、制御盤にあって図にないゾーンを警告します。図を見直すための目安であり、家が守られている証明ではありません。ここから警戒開始や鳴動は行いません。ファイル：図を JSON または SVG で書き出し、読み込み、サーバーが保管する以前のバージョンを確認できます。図はサーバーに保存されます。",
      "绘制住宅的报警系统：主机(报警主机、防区扩展和通讯器)、传感器(门窗磁、移动和双鉴探测器、室外对射、玻璃破碎和振动传感器、烟雾/温感/一氧化碳/燃气/水浸探测器、紧急按钮和防拆开关)、警笛与输出、键盘、读卡器、遥控钥匙和触摸面板，以及供电(电源和备用电池)。“典型住宅”会载入一个示例。\n\n在工具箱中选择元素并点击放置；旋转(R)可转向；“更改类型”可换成同组的另一种并保留连线。连线工具连接两个同类端口：先点一个，再点另一个。连线有五种：有线回路(传感器到主机的回路)、无线连线、警笛输出、数据总线(键盘与扩展)和供电。传感器通过有线或无线之一连接主机，不能同时使用。边框可把元素按房间或楼层分组。\n\n图纸可与现实关联：把画出的主机关联到真实主机，把传感器关联到它的某个防区，元素就会实时显示主机的上报——正常为绿色，防区打开或主机鸣响为红色，主机停止上报为灰色。“绘制主机已有的内容”会添加图中还没有的每个主机和防区，并按防区名称猜测传感器类型。在已关联元素的属性中，“打开报警主机菜单”可前往真实主机。\n\n检查会提示：无人接收的传感器、接入回路数超过启用防区数、主机没有警笛/键盘/备用电池、无线传感器没有电池类型、撤防时不会鸣响的烟雾或水浸传感器，以及主机有而图中没有的防区。这只是检查图纸的参考，并不证明住宅已得到保护；这里不会布防也不会鸣响任何设备。文件：可把图纸导出为 JSON 或 SVG、导入，并查看服务器保存的历史版本。图纸保存在服务器上。",
    ] },
  { id: "electricalDesigner",
    title: ["Electrical designer", "Diseñador eléctrico", "Elektro-Designer", "Concepteur électrique", "Progettazione elettrica", "電気デザイナー", "电气设计器"],
    body: [
      "Draw the electrical installation as a diagram: the grid, panels, breakers, meters, solar panels, inverters, batteries, loads and the wires between them. \"Load the example\" brings a house with solar to start from.\n\nPick an element in the palette and click on the drawing to place it (Shift keeps placing, Esc cancels). With the Wire tool, click one port and then another to join them; a wire has a label, a length in metres and a cross-section in square millimetres, which the checks use. The Frame tool draws a frame around the elements of one panel. Select moves and edits; the inspector on the right shows the properties of the selection, including whether a switch is drawn open or closed.\n\nThe \"Checks\" list reviews the drawing and reports errors and warnings. It is a guide for reviewing the drawing, not a substitute for an electrician or the regulations. An element can be bound to the electrical node that measures it or to a solar device it shows, so the Electrical screen draws the live values on it.\n\nExport JSON saves the drawing, Export SVG makes an image you can print, Import JSON loads one, and New drawing starts an empty one. The drawing is kept on the server.",
      "Dibuja la instalación eléctrica como un esquema: la red, cuadros, interruptores automáticos, contadores, placas solares, inversores, baterías, cargas y los cables entre ellos. \"Cargar el ejemplo\" trae una casa con solar para empezar.\n\nElige un elemento en la paleta y pulsa en el dibujo para colocarlo (Mayús sigue colocando, Esc cancela). Con la herramienta Cable, pulsa un puerto y luego otro para unirlos; un cable tiene etiqueta, longitud en metros y sección en milímetros cuadrados, que usan las comprobaciones. La herramienta Marco dibuja un marco alrededor de los elementos de un cuadro. Seleccionar mueve y edita; el inspector de la derecha muestra las propiedades de la selección, incluido si un interruptor se dibuja abierto o cerrado.\n\nLa lista de \"Comprobaciones\" revisa el dibujo y muestra errores y avisos. Es una guía para revisar el dibujo, no sustituye a un electricista ni a la normativa. Un elemento puede enlazarse con el nodo eléctrico que lo mide o con un dispositivo solar que muestra, de modo que la pantalla Eléctrico dibuje sobre él los valores en vivo.\n\nExportar JSON guarda el dibujo, Exportar SVG genera una imagen que puedes imprimir, Importar JSON carga uno y Nuevo dibujo empieza uno vacío. El dibujo se guarda en el servidor.",
      "Zeichnen Sie die Elektroanlage als Schema: Netz, Verteiler, Leitungsschutzschalter, Zähler, Solarmodule, Wechselrichter, Batterien, Lasten und die Leitungen dazwischen. „Beispiel laden“ bringt ein Haus mit Solar als Ausgangspunkt.\n\nWählen Sie ein Element in der Palette und klicken Sie in die Zeichnung, um es zu setzen (Umschalt setzt weiter, Esc bricht ab). Mit dem Leitungswerkzeug klicken Sie einen Port und dann einen anderen, um sie zu verbinden; eine Leitung hat Beschriftung, Länge in Metern und Querschnitt in Quadratmillimetern, die die Prüfungen nutzen. Das Rahmenwerkzeug zeichnet einen Rahmen um die Elemente eines Verteilers. Auswählen verschiebt und bearbeitet; der Inspektor rechts zeigt die Eigenschaften der Auswahl, auch ob ein Schalter offen oder geschlossen gezeichnet ist.\n\nDie Liste „Prüfungen“ überprüft die Zeichnung und meldet Fehler und Warnungen. Sie ist eine Hilfe zur Durchsicht, kein Ersatz für einen Elektriker oder die Vorschriften. Ein Element kann an den Elektroknoten gebunden werden, der es misst, oder an ein Solargerät, das es zeigt, damit der Bildschirm Elektrik die Live-Werte darauf zeichnet.\n\nJSON exportieren speichert die Zeichnung, SVG exportieren erzeugt ein druckbares Bild, JSON importieren lädt eine, Neue Zeichnung beginnt eine leere. Die Zeichnung liegt auf dem Server.",
      "Dessinez l'installation électrique comme un schéma : le réseau, tableaux, disjoncteurs, compteurs, panneaux solaires, onduleurs, batteries, charges et les fils entre eux. « Charger l'exemple » apporte une maison avec solaire pour démarrer.\n\nChoisissez un élément dans la palette et cliquez sur le dessin pour le placer (Maj continue de placer, Échap annule). Avec l'outil Fil, cliquez sur un port puis sur un autre pour les relier ; un fil a une étiquette, une longueur en mètres et une section en millimètres carrés, que les contrôles utilisent. L'outil Cadre trace un cadre autour des éléments d'un tableau. Sélection déplace et édite ; l'inspecteur à droite montre les propriétés de la sélection, y compris si un interrupteur est dessiné ouvert ou fermé.\n\nLa liste « Contrôles » examine le dessin et signale erreurs et avertissements. C'est un guide pour relire le dessin, pas un substitut à un électricien ni à la réglementation. Un élément peut être lié au nœud électrique qui le mesure ou à un appareil solaire qu'il affiche, pour que l'écran Électrique dessine dessus les valeurs en direct.\n\nExporter JSON enregistre le dessin, Exporter SVG produit une image imprimable, Importer JSON en charge un, Nouveau dessin en commence un vide. Le dessin est gardé sur le serveur.",
      "Disegna l'impianto elettrico come schema: la rete, quadri, interruttori automatici, contatori, pannelli solari, inverter, batterie, carichi e i fili tra loro. «Carica l'esempio» porta una casa con solare da cui partire.\n\nScegli un elemento nella tavolozza e clicca sul disegno per posizionarlo (Maiusc continua a posizionare, Esc annulla). Con lo strumento Filo, clicca una porta e poi un'altra per unirle; un filo ha etichetta, lunghezza in metri e sezione in millimetri quadrati, che i controlli usano. Lo strumento Cornice disegna una cornice attorno agli elementi di un quadro. Seleziona sposta e modifica; l'ispettore a destra mostra le proprietà della selezione, compreso se un interruttore è disegnato aperto o chiuso.\n\nL'elenco «Controlli» rivede il disegno e segnala errori e avvisi. È una guida per rivedere il disegno, non sostituisce un elettricista né la normativa. Un elemento può essere collegato al nodo elettrico che lo misura o a un dispositivo solare che mostra, così la schermata Elettrico disegna sopra i valori dal vivo.\n\nEsporta JSON salva il disegno, Esporta SVG crea un'immagine stampabile, Importa JSON ne carica uno, Nuovo disegno ne inizia uno vuoto. Il disegno è conservato sul server.",
      "電気設備を図として描きます：系統、盤、ブレーカー、電力量計、太陽光パネル、インバーター、バッテリー、負荷、それらを結ぶ配線。「例を読み込む」で太陽光付きの家から始められます。\n\nパレットから要素を選び、図面をクリックして配置します（Shift で連続配置、Esc で中止）。配線ツールでは、1 つ目のポートと 2 つ目のポートを順にクリックして接続します。配線にはラベル、長さ（m）、断面積（mm²）があり、チェックに使われます。枠ツールは 1 つの盤の要素を枠で囲みます。選択ツールで移動と編集を行い、右のインスペクターで選択の属性（スイッチを開/閉どちらで描くかなど）を確認します。\n\n「チェック」リストは図面を点検し、エラーと警告を報告します。これは図面を見直すための目安であり、電気技術者や法規の代わりにはなりません。要素は、それを測定する電気ノードや表示する太陽光機器に関連付けられ、「電気」画面でライブ値が重ねて表示されます。\n\nJSON 書き出しで図面を保存、SVG 書き出しで印刷用画像を作成、JSON 読み込みで読み込み、「新規図面」で空の図面を開始します。図面はサーバーに保存されます。",
      "把电气设施绘制成示意图：市电、配电箱、断路器、电表、光伏板、逆变器、电池、负载以及它们之间的导线。“载入示例”提供一栋带光伏的住宅作为起点。\n\n在元素面板中选择元素，然后在图上点击放置（Shift 连续放置，Esc 取消）。用导线工具先点一个端口再点另一个即可连接；导线有标签、长度（米）和截面积（平方毫米），检查时会用到。框工具会围绕同一配电箱的元素画框。选择工具用于移动和编辑；右侧检查器显示所选对象的属性，包括开关画成断开还是闭合。\n\n“检查”列表会审查图纸并报告错误和警告。它只是审图参考，不能替代电工或法规。元素可绑定到测量它的电气节点，或它所显示的光伏设备，这样“电气”界面会在其上绘制实时数值。\n\n导出 JSON 保存图纸，导出 SVG 生成可打印的图像，导入 JSON 载入图纸，“新建图纸”开始空白图。图纸保存在服务器上。",
    ] },
  { id: "networkDesigner",
    title: ["Network designer", "Diseñador de red", "Netzwerk-Designer", "Concepteur réseau", "Progettazione di rete", "ネットワークデザイナー", "网络设计器"],
    body: [
      "Draw the network of the house or the site: router, switches, access points, cameras, nodes, computers, and the cables between them. \"Typical house\" loads an example.\n\nPick a device in the toolbox and click to place it; Rotate (R) turns it; \"Replace with another device\" swaps it and keeps its cables. The Link tool joins two devices: click one, then the other. A link can have a speed in Mbit/s and a VLAN, which the checks use; they warn of things like a camera on a slow link or a cable that ends nowhere. It is a guide for reviewing the drawing.\n\nThe drawing can be tied to reality: \"Draw what was found\" puts on the plan the devices that the network node discovered; a drawn device can be tied to the real device found, and a drawn camera to a camera of the Cameras menu. Files: export and import the drawing as JSON. The drawing is kept on the server.",
      "Dibuja la red de la casa o del sitio: router, switches, puntos de acceso, cámaras, nodos, ordenadores y los cables entre ellos. \"Casa típica\" carga un ejemplo.\n\nElige un dispositivo en la caja de herramientas y pulsa para colocarlo; Girar (R) lo gira; \"Sustituir por otro dispositivo\" lo cambia y mantiene sus cables. La herramienta Enlace une dos dispositivos: pulsa uno y luego el otro. Un enlace puede tener una velocidad en Mbit/s y una VLAN, que usan las comprobaciones; avisan de cosas como una cámara en un enlace lento o un cable que no acaba en ningún sitio. Es una guía para revisar el dibujo.\n\nEl dibujo puede ligarse a la realidad: \"Dibujar lo encontrado\" pone en el plano los dispositivos que descubrió el nodo de red; un dispositivo dibujado puede enlazarse con el real encontrado, y una cámara dibujada con una cámara del menú Cámaras. Archivos: exportar e importar el dibujo como JSON. El dibujo se guarda en el servidor.",
      "Zeichnen Sie das Netz des Hauses oder Standorts: Router, Switches, Access Points, Kameras, Knoten, Computer und die Kabel dazwischen. „Typisches Haus“ lädt ein Beispiel.\n\nWählen Sie ein Gerät in der Werkzeugleiste und klicken Sie, um es zu setzen; Drehen (R) dreht es; „Durch anderes Gerät ersetzen“ tauscht es und behält die Kabel. Das Verbindungswerkzeug verbindet zwei Geräte: erst eines, dann das andere anklicken. Eine Verbindung kann eine Geschwindigkeit in Mbit/s und ein VLAN haben, die die Prüfungen nutzen; sie warnen z. B. vor einer Kamera an langsamer Verbindung oder einem Kabel, das nirgends endet. Es ist eine Hilfe zur Durchsicht der Zeichnung.\n\nDie Zeichnung lässt sich mit der Realität verknüpfen: „Gefundenes zeichnen“ setzt die vom Netzknoten entdeckten Geräte in den Plan; ein gezeichnetes Gerät kann mit dem echten gefundenen Gerät verknüpft werden, eine gezeichnete Kamera mit einer Kamera aus dem Menü Kameras. Dateien: Zeichnung als JSON exportieren und importieren. Die Zeichnung liegt auf dem Server.",
      "Dessinez le réseau de la maison ou du site : routeur, switchs, points d'accès, caméras, nœuds, ordinateurs et les câbles entre eux. « Maison typique » charge un exemple.\n\nChoisissez un appareil dans la boîte à outils et cliquez pour le placer ; Pivoter (R) le tourne ; « Remplacer par un autre appareil » l'échange en gardant ses câbles. L'outil Lien relie deux appareils : cliquez sur l'un puis sur l'autre. Un lien peut avoir un débit en Mbit/s et un VLAN, que les contrôles utilisent ; ils avertissent par exemple d'une caméra sur un lien lent ou d'un câble qui ne mène nulle part. C'est un guide pour relire le dessin.\n\nLe dessin peut être relié à la réalité : « Dessiner ce qui a été trouvé » met sur le plan les appareils découverts par le nœud réseau ; un appareil dessiné peut être lié à l'appareil réel trouvé, et une caméra dessinée à une caméra du menu Caméras. Fichiers : exporter et importer le dessin en JSON. Le dessin est gardé sur le serveur.",
      "Disegna la rete della casa o del sito: router, switch, access point, telecamere, nodi, computer e i cavi tra loro. «Casa tipica» carica un esempio.\n\nScegli un dispositivo nella cassetta degli strumenti e clicca per posizionarlo; Ruota (R) lo ruota; «Sostituisci con un altro dispositivo» lo scambia mantenendo i cavi. Lo strumento Collegamento unisce due dispositivi: clicca su uno e poi sull'altro. Un collegamento può avere una velocità in Mbit/s e una VLAN, che i controlli usano; avvisano ad esempio di una telecamera su un collegamento lento o di un cavo che non finisce da nessuna parte. È una guida per rivedere il disegno.\n\nIl disegno può essere legato alla realtà: «Disegna ciò che è stato trovato» mette sul piano i dispositivi scoperti dal nodo di rete; un dispositivo disegnato può essere legato a quello reale trovato, e una telecamera disegnata a una telecamera del menu Telecamere. File: esporta e importa il disegno come JSON. Il disegno è conservato sul server.",
      "家やサイトのネットワークを描きます：ルーター、スイッチ、アクセスポイント、カメラ、ノード、コンピューター、それらを結ぶケーブル。「一般的な家」で例を読み込めます。\n\nツールボックスから機器を選び、クリックして配置します。回転（R）で向きを変え、「別の機器に置き換え」はケーブルを残したまま入れ替えます。リンクツールは 2 台の機器を接続します（1 台目、2 台目の順にクリック）。リンクには速度（Mbit/s）と VLAN を設定でき、チェックに使われます。遅いリンク上のカメラや、どこにも繋がらないケーブルなどを警告します。図面を見直すための目安です。\n\n図面は現実と結び付けられます：「見つかったものを描く」でネットワークノードが検出した機器を図に配置し、描いた機器を実際に見つかった機器に、描いたカメラを「カメラ」メニューのカメラに関連付けられます。ファイル：図面を JSON で書き出し/読み込み。図面はサーバーに保存されます。",
      "绘制住宅或场地的网络：路由器、交换机、接入点、摄像头、节点、计算机以及它们之间的线缆。“典型住宅”载入一个示例。\n\n在工具箱中选择设备并点击放置；旋转（R）可转动它；“替换为其他设备”会换成另一台并保留线缆。链路工具连接两台设备：先点一台再点另一台。链路可设置速率（Mbit/s）和 VLAN，检查时会用到，例如提醒摄像头接在慢速链路上或线缆没有终点。它只是审图参考。\n\n图纸可与现实关联：“绘制已发现的设备”把网络节点发现的设备放到图上；画出的设备可与发现的真实设备关联，画出的摄像头可与“摄像头”菜单中的摄像头关联。文件：以 JSON 导出和导入图纸。图纸保存在服务器上。",
    ] },
  { id: "system",
    title: ["System", "Sistema", "System", "Système", "Sistema", "システム", "系统"],
    body: [
      "The health of the server. Cards show what it holds (nodes, cameras, devices, alarms, automations, users, events), its storage (disk used and free), its connections (the MQTT broker, whether it answers), the live video program (FFmpeg) that turns camera streams into live pictures, the alarm webhook, and the memory, processor and temperature of the machine.\n\nThe audit trail lists the actions taken on the system - who armed it, who changed a setting, what was denied or failed - with the user and the target. Filter it by action, user or target, or show only what was denied or failed. It is where you look when you want to know who did something.\n\nIf a card is red, the thing it describes has a problem: follow it in Services or in the logs of the server.",
      "La salud del servidor. Las tarjetas muestran lo que guarda (nodos, cámaras, dispositivos, alarmas, automatizaciones, usuarios, eventos), su almacenamiento (disco usado y libre), sus conexiones (el broker MQTT, si responde), el programa de vídeo en vivo (FFmpeg) que convierte los flujos de cámara en imágenes en vivo, el webhook de alarmas, y la memoria, el procesador y la temperatura de la máquina.\n\nEl registro de auditoría lista las acciones hechas en el sistema - quién lo armó, quién cambió un ajuste, qué se denegó o falló - con el usuario y el objetivo. Fíltralo por acción, usuario u objetivo, o muestra solo lo denegado o fallido. Es donde miras cuando quieres saber quién hizo algo.\n\nSi una tarjeta está en rojo, lo que describe tiene un problema: síguelo en Servicios o en los registros del servidor.",
      "Der Zustand des Servers. Karten zeigen, was er hält (Knoten, Kameras, Geräte, Alarme, Automatisierungen, Benutzer, Ereignisse), seinen Speicher (belegter und freier Platz), seine Verbindungen (der MQTT-Broker, ob er antwortet), das Live-Videoprogramm (FFmpeg), das Kamerastreams in Live-Bilder wandelt, den Alarm-Webhook sowie Speicher, Prozessor und Temperatur der Maschine.\n\nDas Audit-Protokoll listet die Aktionen am System - wer es geschärft hat, wer eine Einstellung geändert hat, was abgelehnt wurde oder scheiterte - mit Benutzer und Ziel. Filtern Sie nach Aktion, Benutzer oder Ziel, oder zeigen Sie nur Abgelehntes oder Gescheitertes. Hier sehen Sie nach, wenn Sie wissen wollen, wer etwas getan hat.\n\nIst eine Karte rot, hat das Beschriebene ein Problem: verfolgen Sie es in Dienste oder in den Protokollen des Servers.",
      "La santé du serveur. Des cartes montrent ce qu'il contient (nœuds, caméras, appareils, alarmes, automatisations, utilisateurs, événements), son stockage (disque utilisé et libre), ses connexions (le broker MQTT, s'il répond), le programme vidéo en direct (FFmpeg) qui transforme les flux de caméra en images en direct, le webhook d'alarme, et la mémoire, le processeur et la température de la machine.\n\nLe journal d'audit liste les actions faites sur le système - qui l'a armé, qui a changé un réglage, ce qui a été refusé ou a échoué - avec l'utilisateur et la cible. Filtrez-le par action, utilisateur ou cible, ou n'affichez que ce qui a été refusé ou a échoué. C'est là qu'on regarde pour savoir qui a fait quelque chose.\n\nSi une carte est rouge, ce qu'elle décrit a un problème : suivez-le dans Services ou dans les journaux du serveur.",
      "La salute del server. Le schede mostrano ciò che contiene (nodi, telecamere, dispositivi, allarmi, automazioni, utenti, eventi), il suo archivio (disco usato e libero), i collegamenti (il broker MQTT, se risponde), il programma video dal vivo (FFmpeg) che trasforma i flussi delle telecamere in immagini dal vivo, il webhook degli allarmi, e memoria, processore e temperatura della macchina.\n\nIl registro di audit elenca le azioni compiute sul sistema - chi lo ha armato, chi ha cambiato un'impostazione, cosa è stato negato o è fallito - con utente e bersaglio. Filtralo per azione, utente o bersaglio, o mostra solo ciò che è stato negato o fallito. È dove guardi quando vuoi sapere chi ha fatto qualcosa.\n\nSe una scheda è rossa, ciò che descrive ha un problema: seguilo in Servizi o nei registri del server.",
      "サーバーの状態です。カードには、保持しているもの（ノード、カメラ、機器、アラーム、オートメーション、ユーザー、イベント）、ストレージ（ディスクの使用量と空き）、接続（MQTT ブローカーの応答）、カメラのストリームをライブ映像に変換する映像プログラム（FFmpeg）、アラーム Webhook、マシンのメモリ・プロセッサー・温度が表示されます。\n\n監査ログには、システムに対する操作（誰が警戒したか、誰が設定を変更したか、何が拒否または失敗したか）がユーザーと対象とともに並びます。操作・ユーザー・対象で絞り込んだり、拒否または失敗したものだけを表示できます。誰が何をしたかを知りたいときに見る場所です。\n\nカードが赤い場合は、その対象に問題があります。「サービス」やサーバーのログで確認してください。",
      "服务器的健康状况。卡片显示其保存的内容（节点、摄像头、设备、报警、自动化、用户、事件）、存储（磁盘已用和可用）、连接（MQTT 代理是否响应）、把摄像头视频流转换为实时画面的视频程序（FFmpeg）、报警 Webhook，以及机器的内存、处理器和温度。\n\n审计记录列出对系统执行的操作——谁布防、谁修改了设置、什么被拒绝或失败——并带有用户和目标。可按操作、用户或目标筛选，或只显示被拒绝或失败的内容。想知道谁做了什么时就看这里。\n\n若卡片为红色，说明它所描述的对象有问题：请到“服务”或服务器日志中跟进。",
    ] },
  { id: "services",
    title: ["Services", "Servicios", "Dienste", "Services", "Servizi", "サービス", "服务"],
    body: [
      "The A.R.M.O.R. services that run on the server - the server itself, the MQTT broker, the network node, the alarm and observation services, the voice gateway and the others - with whether each is active and its version.\n\nThe filters show all, only the active ones or only those that are not running, by family, and the search box finds a service by name. Refresh reads the state again.\n\nAn administrator can also start, stop, restart, reload, pause or resume a service from here, in Configuration > Services: Studio asks first and says what depends on it. Stopping or restarting the server leaves this console without an answer for a few seconds. The same tab area has the MQTT broker (the accounts of the nodes) and the settings files of the services, with the secrets hidden.",
      "Los servicios de A.R.M.O.R. que corren en el servidor - el propio servidor, el broker MQTT, el nodo de red, los servicios de alarma y observación, la pasarela de voz y los demás - con si cada uno está activo y su versión.\n\nLos filtros muestran todos, solo los activos o solo los que no corren, por familia, y el buscador encuentra un servicio por nombre. Actualizar vuelve a leer el estado.\n\nUn administrador también puede arrancar, parar, reiniciar, recargar, pausar o reanudar un servicio desde Configuración > Servicios: Studio pregunta antes y dice qué depende de él. Parar o reiniciar el servidor deja esta consola sin respuesta unos segundos. En la misma zona de pestañas están el broker MQTT (las cuentas de los nodos) y los archivos de ajustes de los servicios, con los secretos ocultos.",
      "Die A.R.M.O.R.-Dienste auf dem Server - der Server selbst, der MQTT-Broker, der Netzwerkknoten, die Alarm- und Beobachtungsdienste, das Sprach-Gateway und weitere - mit Angabe, ob jeder aktiv ist, und seiner Version.\n\nDie Filter zeigen alle, nur die aktiven oder nur die nicht laufenden, nach Familie, und das Suchfeld findet einen Dienst nach Namen. Aktualisieren liest den Zustand neu.\n\nEin Administrator kann einen Dienst auch in Konfiguration > Dienste starten, stoppen, neu starten, neu laden, pausieren oder fortsetzen: Studio fragt vorher und sagt, was davon abhängt. Stoppen oder Neustarten des Servers lässt diese Konsole einige Sekunden ohne Antwort. Im selben Tab-Bereich finden sich der MQTT-Broker (die Konten der Knoten) und die Einstellungsdateien der Dienste, Geheimnisse verborgen.",
      "Les services A.R.M.O.R. qui tournent sur le serveur - le serveur lui-même, le broker MQTT, le nœud réseau, les services d'alarme et d'observation, la passerelle vocale et les autres - avec leur état actif ou non et leur version.\n\nLes filtres montrent tous, seulement les actifs ou seulement ceux qui ne tournent pas, par famille, et la recherche trouve un service par son nom. Actualiser relit l'état.\n\nUn administrateur peut aussi démarrer, arrêter, redémarrer, recharger, mettre en pause ou reprendre un service dans Configuration > Services : Studio demande d'abord et dit ce qui en dépend. Arrêter ou redémarrer le serveur laisse cette console sans réponse quelques secondes. La même zone d'onglets contient le broker MQTT (les comptes des nœuds) et les fichiers de réglages des services, secrets masqués.",
      "I servizi A.R.M.O.R. che girano sul server - il server stesso, il broker MQTT, il nodo di rete, i servizi di allarme e osservazione, il gateway vocale e gli altri - con l'indicazione se ciascuno è attivo e la sua versione.\n\nI filtri mostrano tutti, solo gli attivi o solo quelli non in esecuzione, per famiglia, e la ricerca trova un servizio per nome. Aggiorna rilegge lo stato.\n\nUn amministratore può anche avviare, fermare, riavviare, ricaricare, mettere in pausa o riprendere un servizio da Configurazione > Servizi: Studio chiede prima e dice cosa ne dipende. Fermare o riavviare il server lascia questa console senza risposta per qualche secondo. Nella stessa area di schede ci sono il broker MQTT (gli account dei nodi) e i file di impostazioni dei servizi, con i segreti nascosti.",
      "サーバー上で動く A.R.M.O.R. のサービス（サーバー本体、MQTT ブローカー、ネットワークノード、警報・観測サービス、音声ゲートウェイなど）を、稼働状態とバージョンとともに表示します。\n\nフィルターで、すべて／稼働中のみ／停止中のみ、ファミリー別に絞り込み、検索欄で名前から探します。「更新」で状態を読み直します。\n\n管理者は、設定 > サービスからサービスの起動、停止、再起動、再読み込み、一時停止、再開もできます。Studio は事前に確認し、依存するものを示します。サーバーの停止や再起動中は、このコンソールが数秒応答しません。同じタブ領域に、MQTT ブローカー（ノードのアカウント）と、サービスの設定ファイル（秘密は非表示）があります。",
      "服务器上运行的 A.R.M.O.R. 服务——服务器本身、MQTT 代理、网络节点、报警与观测服务、语音网关等——并显示每个服务是否运行及其版本。\n\n筛选器可显示全部、仅运行中或仅未运行的服务，并可按系列筛选，搜索框按名称查找服务。“刷新”重新读取状态。\n\n管理员还可以在 设置 > 服务 中启动、停止、重启、重新加载、暂停或恢复服务：Studio 会先询问，并说明哪些依赖它。停止或重启服务器会使本控制台数秒无响应。同一标签区域还有 MQTT 代理(节点账号)和各服务的设置文件(密钥已隐藏)。",
    ] },
  { id: "configuration",
    title: ["Configuration", "Configuración", "Konfiguration", "Configuration", "Configurazione", "設定", "配置"],
    body: [
      "The settings, in tabs. General: the server origin (the address Studio uses to reach the ARMOR server, with a button to check it), the language and the theme of the console; \"Save preferences\" keeps them in this browser. Cameras: add, edit and remove cameras, and their connection data. Discovery: look for cameras on the local network. Video and PTZ: the quality of the live video and the PTZ options. Server: where the ARMOR server listens and where Studio is served (only an administrator can see and change this).\n\nUsers: who can sign in to Studio. There are two roles. An administrator changes everything, including users. An operator does everything else: answers alarms, sees the cameras, arms and disarms. Each user can have a PIN (4 to 10 digits) that is asked to disarm the system, and an optional duress PIN that disarms as well but silently raises a critical alarm; an administrator sets them here. \"My account\" lets anyone change their own password (the current one is required).\n\nPasswords of cameras go only to your local server, which keeps them encrypted; the browser never keeps them. If the server has been restarted, sign in again to use the cameras.\n\nAdministrators also have: Services, MQTT broker and Settings files (start and stop services, add or remove the accounts of nodes, edit the settings files with the secrets hidden); Notifications (where alarms are sent - Telegram and a Home Assistant webhook - with a test button); Installation (the whole installation as one file - cameras without their passwords, the designs of the site, alarm, electricity and network, rules, automations, devices and solar equipment - to keep or to import on another machine; users and passwords are never in it); and Node firmware: update the firmware of the field nodes (radar, solar, electrical, alarm and touch panel) without opening the page of each one - from a file of this computer or from the newest release on GitHub (downloaded by the server and checked against the hash the release publishes) - to one node or to every node of a type, one after another, with the login of the nodes' own panel (used for the update only, never kept). A node the network node does not see can be added by its address. Preferences: the guided tours (a welcome tour on the first visit and one for every menu, started from here or from the Help), the hover hints (off, text, or with an animated picture and the time they wait), the animations, the density, the size of the text, the menu Studio opens at, and whether a new critical alarm is heard and shown as a notification; they are kept in this browser.\n\nRoles and push: besides administrator and operator there is the viewer role (family, guards): it can look at the state, alarms, cameras and history but cannot arm, acknowledge, switch, delete or change anything, and each role has a line explaining it. In Notifications, ntfy sends a push to the phone's ntfy app (the highest priority for a critical alarm, sounding even in silent mode), and a critical alarm that nobody acknowledges within the minutes set in ARMOR_ESCALATE_AFTER_MIN is told again as unattended to every channel.",
      "Los ajustes, en pestañas. General: el origen del servidor (la dirección que Studio usa para llegar al servidor ARMOR, con un botón para comprobarla), el idioma y el tema de la consola; \"Guardar preferencias\" las guarda en este navegador. Cámaras: añadir, editar y quitar cámaras, y sus datos de conexión. Descubrimiento: busca cámaras en la red local. Vídeo y PTZ: la calidad del vídeo en vivo y las opciones PTZ. Servidor: dónde escucha el servidor ARMOR y desde dónde se sirve Studio (solo un administrador lo ve y lo cambia).\n\nUsuarios: quién puede entrar en Studio. Hay dos roles. Un administrador cambia todo, incluidos los usuarios. Un operador hace todo lo demás: atiende alarmas, ve las cámaras, arma y desarma. Cada usuario puede tener un PIN (de 4 a 10 dígitos) que se pide para desarmar el sistema, y un PIN de coacción opcional que también desarma pero levanta en silencio una alarma crítica; los pone un administrador aquí. \"Mi cuenta\" permite a cualquiera cambiar su propia contraseña (se exige la actual).\n\nLas contraseñas de las cámaras van solo a tu servidor local, que las guarda cifradas; el navegador nunca las guarda. Si el servidor se ha reiniciado, vuelve a iniciar sesión para usar las cámaras.\n\nLos administradores tienen además: Servicios, Broker MQTT y Archivos de ajustes (arrancar y parar servicios, añadir o quitar las cuentas de los nodos, editar los archivos de ajustes con los secretos ocultos); Notificaciones (adónde se envían las alarmas - Telegram y un webhook de Home Assistant - con un botón de prueba); Instalación (toda la instalación en un archivo - cámaras sin sus contraseñas, los diseños del sitio, la alarma, la electricidad y la red, reglas, automatizaciones, dispositivos y equipos solares - para guardar o importar en otra máquina; nunca lleva usuarios ni contraseñas); y Firmware de nodos: actualiza el firmware de los nodos de campo (radar, solar, eléctrico, alarma y panel táctil) sin abrir la página de cada uno - desde un archivo de este ordenador o desde la última versión de GitHub (la descarga el servidor y la comprueba con el hash que publica la versión) - a un nodo o a todos los de un tipo, uno tras otro, con el usuario del panel propio de los nodos (solo para la actualización, nunca se guarda). Un nodo que el nodo de red no ve se puede añadir por su dirección. Preferencias: las guías paso a paso (una de bienvenida en la primera visita y una por cada menú, desde aquí o desde la Ayuda), los globos de ayuda (desactivados, solo texto, o con imagen animada y el tiempo que tardan), las animaciones, la densidad, el tamaño del texto, el menú con el que abre Studio y si una alarma crítica nueva suena y se muestra como notificación; se guardan en este navegador.\n\nRoles y avisos push: además de administrador y operador existe el rol observador (familia, vigilantes): puede mirar el estado, las alarmas, las cámaras y el historial pero no puede armar, reconocer, conmutar, borrar ni cambiar nada, y cada rol tiene una línea que lo explica. En Notificaciones, ntfy envía un aviso a la app ntfy del móvil (la máxima prioridad para una alarma crítica, que suena incluso en silencio), y una alarma crítica que nadie reconoce en los minutos fijados en ARMOR_ESCALATE_AFTER_MIN se vuelve a avisar como desatendida por todos los canales.",
      "Die Einstellungen in Tabs. Allgemein: der Server-Ursprung (die Adresse, unter der Studio den ARMOR-Server erreicht, mit Prüfknopf), Sprache und Design der Konsole; „Einstellungen speichern“ behält sie in diesem Browser. Kameras: Kameras und ihre Verbindungsdaten hinzufügen, bearbeiten und entfernen. Suche: Kameras im lokalen Netz finden. Video und PTZ: Qualität des Live-Videos und PTZ-Optionen. Server: wo der ARMOR-Server lauscht und von wo Studio ausgeliefert wird (nur ein Administrator sieht und ändert das).\n\nBenutzer: wer sich in Studio anmelden darf. Es gibt zwei Rollen. Ein Administrator ändert alles, auch Benutzer. Ein Operator macht alles andere: Alarme beantworten, Kameras sehen, scharf- und unscharfschalten. Jeder Benutzer kann eine PIN (4 bis 10 Ziffern) haben, die zum Unscharfschalten verlangt wird, und eine optionale Zwangs-PIN, die ebenfalls unscharf schaltet, aber still einen kritischen Alarm auslöst; ein Administrator legt sie hier fest. „Mein Konto“ lässt jeden sein eigenes Passwort ändern (das aktuelle ist nötig).\n\nKamerapasswörter gehen nur an Ihren lokalen Server, der sie verschlüsselt speichert; der Browser behält sie nie. Wurde der Server neu gestartet, melden Sie sich erneut an, um die Kameras zu nutzen.\n\nAdministratoren haben außerdem: Dienste, MQTT-Broker und Einstellungsdateien (Dienste starten und stoppen, Konten der Knoten anlegen oder entfernen, Einstellungsdateien mit verborgenen Geheimnissen bearbeiten); Benachrichtigungen (wohin Alarme gesendet werden - Telegram und ein Home-Assistant-Webhook - mit Testknopf); Installation (die ganze Installation als eine Datei - Kameras ohne Passwörter, die Entwürfe von Standort, Alarm, Elektrik und Netzwerk, Regeln, Automatisierungen, Geräte und Solargeräte - zum Aufbewahren oder Importieren auf einer anderen Maschine; Benutzer und Passwörter sind nie darin); und Knoten-Firmware: die Firmware der Feldknoten (Radar, Solar, Elektrik, Alarm und Touchpanel) aktualisieren, ohne die Seite jedes einzelnen zu öffnen - aus einer Datei dieses Rechners oder aus dem neuesten GitHub-Release (vom Server geladen und gegen den veröffentlichten Hash geprüft) - für einen Knoten oder alle einer Art nacheinander, mit dem Login des eigenen Panels der Knoten (nur für das Update, nie gespeichert). Ein Knoten, den der Netzwerkknoten nicht sieht, lässt sich über seine Adresse hinzufügen. Einstellungen: die geführten Touren (eine Willkommenstour beim ersten Besuch und eine für jedes Menü, von hier oder aus der Hilfe), die Hinweisblasen (aus, Text oder mit animiertem Bild und Wartezeit), die Animationen, die Dichte, die Textgröße, das Menü, bei dem Studio startet, und ob ein neuer kritischer Alarm ertönt und als Benachrichtigung erscheint; sie werden in diesem Browser gespeichert.\n\nRollen und Push: Neben Administrator und Operator gibt es die Rolle Betrachter (Familie, Wachleute): Sie sieht Zustand, Alarme, Kameras und Verlauf, kann aber nichts scharfschalten, quittieren, schalten, löschen oder ändern; jede Rolle hat eine erklärende Zeile. Unter Benachrichtigungen sendet ntfy einen Push an die ntfy-App des Handys (höchste Priorität bei kritischem Alarm, auch im Lautlosmodus), und ein kritischer Alarm, den niemand innerhalb der in ARMOR_ESCALATE_AFTER_MIN gesetzten Minuten quittiert, wird auf allen Kanälen erneut als unbeachtet gemeldet.",
      "Les réglages, en onglets. Général : l'origine du serveur (l'adresse que Studio utilise pour joindre le serveur ARMOR, avec un bouton de vérification), la langue et le thème de la console ; « Enregistrer les préférences » les garde dans ce navigateur. Caméras : ajouter, modifier et retirer des caméras et leurs données de connexion. Découverte : chercher des caméras sur le réseau local. Vidéo et PTZ : la qualité de la vidéo en direct et les options PTZ. Serveur : où le serveur ARMOR écoute et d'où Studio est servi (seul un administrateur le voit et le change).\n\nUtilisateurs : qui peut se connecter à Studio. Il y a deux rôles. Un administrateur change tout, utilisateurs compris. Un opérateur fait tout le reste : répondre aux alarmes, voir les caméras, armer et désarmer. Chaque utilisateur peut avoir un PIN (4 à 10 chiffres) demandé pour désarmer le système, et un PIN de contrainte facultatif qui désarme aussi mais déclenche en silence une alarme critique ; un administrateur les définit ici. « Mon compte » permet à chacun de changer son mot de passe (l'actuel est exigé).\n\nLes mots de passe des caméras vont seulement à votre serveur local, qui les garde chiffrés ; le navigateur ne les garde jamais. Si le serveur a redémarré, reconnectez-vous pour utiliser les caméras.\n\nLes administrateurs ont aussi : Services, Broker MQTT et Fichiers de réglages (démarrer et arrêter des services, ajouter ou retirer les comptes des nœuds, modifier les fichiers de réglages secrets masqués) ; Notifications (où sont envoyées les alarmes - Telegram et un webhook Home Assistant - avec un bouton de test) ; Installation (toute l'installation en un fichier - caméras sans leurs mots de passe, les plans du site, de l'alarme, de l'électricité et du réseau, règles, automatisations, appareils et équipements solaires - à garder ou à importer sur une autre machine ; ni utilisateurs ni mots de passe dedans) ; et Firmware des nœuds : mettre à jour le firmware des nœuds de terrain (radar, solaire, électrique, alarme et panneau tactile) sans ouvrir la page de chacun - depuis un fichier de cet ordinateur ou depuis la dernière version de GitHub (téléchargée par le serveur et vérifiée avec le hash que publie la version) - pour un nœud ou tous ceux d'un type, l'un après l'autre, avec l'identifiant du panneau propre des nœuds (pour la mise à jour seulement, jamais gardé). Un nœud que le nœud réseau ne voit pas peut être ajouté par son adresse. Préférences : les visites guidées (une de bienvenue à la première visite et une par menu, d'ici ou depuis l'aide), les bulles d'aide (désactivées, texte seul, ou avec image animée et délai), les animations, la densité, la taille du texte, le menu d'ouverture de Studio et si une nouvelle alarme critique retentit et s'affiche en notification ; elles sont gardées dans ce navigateur.\n\nRôles et push : en plus d'administrateur et d'opérateur, il y a le rôle observateur (famille, gardiens) : il voit l'état, les alarmes, les caméras et l'historique mais ne peut ni armer, ni acquitter, ni commuter, ni supprimer, ni modifier ; chaque rôle a une ligne qui l'explique. Dans Notifications, ntfy envoie un push à l'application ntfy du téléphone (priorité maximale pour une alarme critique, qui sonne même en silencieux), et une alarme critique que personne n'acquitte dans les minutes fixées par ARMOR_ESCALATE_AFTER_MIN est signalée de nouveau comme non traitée sur tous les canaux.",
      "Le impostazioni, in schede. Generale: l'origine del server (l'indirizzo che Studio usa per raggiungere il server ARMOR, con un pulsante per verificarlo), la lingua e il tema della console; \"Salva preferenze\" le conserva in questo browser. Telecamere: aggiungere, modificare e rimuovere telecamere e i loro dati di connessione. Ricerca: cerca telecamere nella rete locale. Video e PTZ: la qualità del video dal vivo e le opzioni PTZ. Server: dove ascolta il server ARMOR e da dove viene servito Studio (solo un amministratore lo vede e lo cambia).\n\nUtenti: chi può accedere a Studio. Ci sono due ruoli. Un amministratore cambia tutto, utenti compresi. Un operatore fa tutto il resto: risponde agli allarmi, vede le telecamere, attiva e disattiva. Ogni utente può avere un PIN (da 4 a 10 cifre) richiesto per disattivare il sistema e un PIN di coercizione facoltativo che disattiva comunque ma genera in silenzio un allarme critico; li imposta un amministratore qui. \"Il mio account\" permette a chiunque di cambiare la propria password (serve quella attuale).\n\nLe password delle telecamere vanno solo al tuo server locale, che le conserva cifrate; il browser non le conserva mai. Se il server è stato riavviato, accedi di nuovo per usare le telecamere.\n\nGli amministratori hanno anche: Servizi, Broker MQTT e File di impostazioni (avviare e fermare servizi, aggiungere o rimuovere gli account dei nodi, modificare i file di impostazioni con i segreti nascosti); Notifiche (dove vengono inviati gli allarmi - Telegram e un webhook di Home Assistant - con un pulsante di prova); Installazione (l'intera installazione in un file - telecamere senza password, i progetti del sito, dell'allarme, dell'elettricità e della rete, regole, automazioni, dispositivi e impianti solari - da conservare o importare su un'altra macchina; mai utenti né password); e Firmware dei nodi: aggiornare il firmware dei nodi sul campo (radar, solare, elettrico, allarme e pannello touch) senza aprire la pagina di ciascuno - da un file di questo computer o dall'ultima versione su GitHub (scaricata dal server e verificata con l'hash che la versione pubblica) - su un nodo o su tutti quelli di un tipo, uno dopo l'altro, con il login del pannello proprio dei nodi (solo per l'aggiornamento, mai conservato). Un nodo che il nodo di rete non vede si può aggiungere dal suo indirizzo. Preferenze: le visite guidate (una di benvenuto alla prima visita e una per ogni menu, da qui o dalla Guida), i suggerimenti (disattivati, solo testo, o con immagine animata e tempo di attesa), le animazioni, la densità, la dimensione del testo, il menu con cui si apre Studio e se un nuovo allarme critico suona e compare come notifica; sono salvate in questo browser.\n\nRuoli e push: oltre ad amministratore e operatore c'è il ruolo osservatore (famiglia, vigilanti): può guardare stato, allarmi, telecamere e storico ma non può armare, riconoscere, comandare, eliminare né modificare nulla, e ogni ruolo ha una riga che lo spiega. In Notifiche, ntfy invia una push all'app ntfy del telefono (priorità massima per un allarme critico, che suona anche in silenzioso), e un allarme critico che nessuno riconosce entro i minuti impostati in ARMOR_ESCALATE_AFTER_MIN viene segnalato di nuovo come non gestito su tutti i canali.",
      "設定はタブに分かれています。一般：サーバーのオリジン（Studio が ARMOR サーバーに接続するアドレス。確認ボタンあり）、言語とテーマ。「設定を保存」でこのブラウザーに保存します。カメラ：カメラと接続情報の追加・編集・削除。検出：ローカルネットワークでカメラを探します。映像と PTZ：ライブ映像の品質と PTZ のオプション。サーバー：ARMOR サーバーの待ち受け先と Studio の配信元（管理者のみ表示・変更可能）。\n\nユーザー：Studio にログインできる人です。ロールは2つあり、管理者はユーザーを含むすべてを変更でき、オペレーターはアラーム対応、カメラ閲覧、警戒／解除など他のすべてを行えます。各ユーザーには、解除時に求められる PIN（4〜10桁）と、解除はできるが静かに重大アラームを発報する任意の強要 PIN を設定できます（管理者がここで設定）。「マイアカウント」では誰でも自分のパスワードを変更できます（現在のパスワードが必要）。\n\nカメラのパスワードはローカルサーバーにのみ送られ、暗号化して保管されます。ブラウザーには保存されません。サーバーを再起動した場合は、カメラを使うために再ログインしてください。\n\n管理者にはさらに次があります：サービス、MQTT ブローカー、設定ファイル（サービスの起動・停止、ノードのアカウントの追加・削除、秘密を隠した設定ファイルの編集）、通知（アラームの送信先：Telegram と Home Assistant の Webhook、テストボタンあり）、インストール（インストール全体を1ファイルに：パスワードなしのカメラ、サイト・警報・電気・ネットワークの設計、ルール、自動化、デバイス、太陽光機器。別のマシンに保管・取り込み可能。ユーザーとパスワードは含まれません）、ノードのファームウェア：現場ノード（レーダー、太陽光、電気、警報、タッチパネル）を各ページを開かずに更新します。このコンピューターのファイル、または GitHub の最新リリース（サーバーがダウンロードし、リリースのハッシュで検証）から、1台または同種の全ノードに順番に、ノード自身のパネルのログインで実施します（更新のみに使用、保存なし）。ネットワークノードが見つけられないノードはアドレスで追加できます。環境設定：ガイドツアー（初回のウェルカムツアーと各メニューごとのツアー。ここまたはヘルプから開始）、ホバーヒント（オフ・テキスト・アニメーション画像付きと待ち時間）、アニメーション、密度、文字サイズ、起動時のメニュー、新しい重大アラームの音と通知。設定はこのブラウザーに保存されます。\n\nロールとプッシュ：管理者・オペレーターに加え、閲覧者ロール（家族、警備員）があります。状態、アラーム、カメラ、履歴は見られますが、警戒、確認、切り替え、削除、変更はできず、各ロールには説明行があります。通知では、ntfy がスマホの ntfy アプリにプッシュを送り（重大アラームは最高優先度でサイレントでも鳴ります）、ARMOR_ESCALATE_AFTER_MIN で設定した分数内に誰も確認しない重大アラームは、全チャンネルに「未対応」として再通知されます。",
      "设置分为多个标签页。常规：服务器地址(Studio 用来连接 ARMOR 服务器的地址，带检查按钮)、控制台语言和主题；“保存偏好”会将它们保存在此浏览器中。摄像头：添加、编辑和删除摄像头及其连接信息。发现：在本地网络中查找摄像头。视频与 PTZ：实时视频质量和 PTZ 选项。服务器：ARMOR 服务器监听的位置以及 Studio 的提供位置(仅管理员可见和修改)。\n\n用户：谁可以登录 Studio。有两种角色：管理员可更改一切，包括用户；操作员可做其余所有事：处理报警、查看摄像头、布防和撤防。每个用户可以有一个撤防时要求输入的 PIN(4 到 10 位)，以及一个可选的胁迫 PIN——它同样可以撤防，但会悄悄触发严重报警；由管理员在此设置。“我的账户”允许任何人修改自己的密码(需要当前密码)。\n\n摄像头密码只发送到您的本地服务器并加密保存；浏览器从不保存。若服务器已重启，请重新登录以使用摄像头。\n\n管理员还有：服务、MQTT 代理和设置文件(启动/停止服务，添加或删除节点账号，编辑隐藏密钥的设置文件)；通知(报警发送到哪里——Telegram 和 Home Assistant webhook——带测试按钮)；安装(将整个安装导出为一个文件——不含密码的摄像头、场地、报警、电气和网络的设计、规则、自动化、设备和太阳能设备，可保存或导入到另一台机器；其中绝不包含用户和密码)；以及节点固件：无需逐个打开页面，即可更新现场节点(雷达、太阳能、电气、报警和触摸面板)的固件——来自本机文件或 GitHub 最新发布(由服务器下载，并用发布提供的哈希校验)——更新一个节点或同类全部节点(依次进行)，使用节点自身面板的登录(仅用于更新，不保存)。网络节点没有发现的节点，可以按地址添加。偏好设置：分步导览（首次访问的欢迎导览加每个菜单各一个导览，可从这里或帮助中开始）、悬停提示（关闭、纯文本，或带动画图片及等待时间）、动画、密度、文字大小、Studio 的起始菜单，以及新的严重报警是否发声并弹出通知；设置保存在此浏览器中。\n\n角色与推送：除管理员和操作员外，还有查看者角色（家人、保安）：可以查看状态、报警、摄像头和历史，但不能布防、确认、切换、删除或更改任何内容，每个角色都有一行说明。在“通知”中，ntfy 会向手机上的 ntfy 应用发送推送（严重报警为最高优先级，静音时也会响）；严重报警若在 ARMOR_ESCALATE_AFTER_MIN 设定的分钟数内无人确认，会在所有渠道再次以“无人处理”通知。",
    ] },
  { id: "tips",
    title: ["Tips and shortcuts", "Consejos y atajos", "Tipps und Tastenkürzel", "Astuces et raccourcis", "Consigli e scorciatoie", "ヒントとショートカット", "提示与快捷键"],
    body: [
      "Hover to learn: pause the pointer over any button, field or menu entry for a short explanation.\n\nIn the designers: Ctrl+Z undoes, Delete removes the selection, the arrow keys nudge, Esc cancels what you are doing, R rotates the selected element of the alarm, electrical and network designers. In 3D, the left button selects and moves, the right or middle button pans, the wheel zooms, and holding Shift while dragging an object changes its elevation.\n\nSnap and grid help you draw exact sizes; typing a length and pressing Enter gives exact sides.\n\nThe design, the alarm, electrical and network drawings and the preferences of your user are kept on the server, so a different browser or a tablet sees the same; each has its earlier versions, which you can take back. The look, the language and which menu groups are folded are kept in the browser you set them in.\n\nEvery question - deleting a camera, a user, a recording or a device, forgetting a node, switching a circuit - is asked in a dialog of the page itself, so the browser can never silence it. Allow the browser's notifications to hear and see a new critical alarm even when Studio is on another tab.\n\nIf something does not respond, check the connection to the server (the status in the bar at the bottom) and the System screen. A message in red says what failed and why.",
      "Pasa el puntero para aprender: déjalo sobre cualquier botón, campo o entrada del menú para ver una breve explicación.\n\nEn los diseñadores: Ctrl+Z deshace, Supr borra la selección, las flechas desplazan, Esc cancela lo que estás haciendo, R gira el elemento seleccionado de los diseñadores de alarma, eléctrico y de red. En 3D, el botón izquierdo selecciona y mueve, el derecho o el central desplaza la vista, la rueda hace zoom, y mantener Mayús al arrastrar un objeto cambia su elevación.\n\nLa imantación y la cuadrícula ayudan a dibujar medidas exactas; escribir una longitud y pulsar Intro da lados exactos.\n\nEl diseño, los dibujos de alarma, eléctrico y de red y las preferencias de tu usuario se guardan en el servidor, así que otro navegador o una tableta ven lo mismo; cada uno tiene sus versiones anteriores, que puedes recuperar. El aspecto, el idioma y qué grupos del menú están plegados se guardan en el navegador donde los fijaste.\n\nToda pregunta - borrar una cámara, un usuario, una grabación o un dispositivo, olvidar un nodo, conmutar un circuito - se hace en un diálogo de la propia página, así que el navegador nunca puede silenciarla. Permite las notificaciones del navegador para oír y ver una alarma crítica nueva aunque Studio esté en otra pestaña.\n\nSi algo no responde, revisa la conexión con el servidor (el estado en la barra de abajo) y la pantalla Sistema. Un mensaje en rojo dice qué falló y por qué.",
      "Zeigen, um zu lernen: Halten Sie den Zeiger über eine Schaltfläche, ein Feld oder einen Menüeintrag für eine kurze Erklärung.\n\nIn den Planern: Strg+Z macht rückgängig, Entf löscht die Auswahl, die Pfeiltasten verschieben, Esc bricht ab, R dreht das gewählte Element der Planer für Alarm, Elektrik und Netzwerk. In 3D wählt und bewegt die linke Taste, die rechte oder mittlere verschiebt die Ansicht, das Rad zoomt, und Umschalt beim Ziehen eines Objekts ändert seine Höhe.\n\nRaster und Einrasten helfen bei exakten Maßen; eine Länge tippen und Enter drücken ergibt exakte Seiten.\n\nDer Entwurf, die Zeichnungen für Alarm, Elektrik und Netzwerk und die Einstellungen Ihres Benutzers liegen auf dem Server, sodass ein anderer Browser oder ein Tablet dasselbe sieht; jedes hat frühere Versionen, die Sie zurückholen können. Aussehen, Sprache und welche Menügruppen eingeklappt sind, bleiben im Browser, in dem Sie sie gesetzt haben.\n\nJede Frage - eine Kamera, einen Benutzer, eine Aufnahme oder ein Gerät löschen, einen Knoten vergessen, einen Stromkreis schalten - wird in einem Dialog der Seite selbst gestellt, den der Browser nie unterdrücken kann. Erlauben Sie Browser-Benachrichtigungen, um einen neuen kritischen Alarm auch bei Studio in einem anderen Tab zu hören und zu sehen.\n\nReagiert etwas nicht, prüfen Sie die Verbindung zum Server (der Status in der unteren Leiste) und den Bildschirm System. Eine rote Meldung sagt, was fehlschlug und warum.",
      "Survolez pour apprendre : laissez le pointeur sur un bouton, un champ ou une entrée du menu pour une courte explication.\n\nDans les concepteurs : Ctrl+Z annule, Suppr supprime la sélection, les flèches déplacent, Échap annule l'action en cours, R pivote l'élément sélectionné des concepteurs d'alarme, électrique et réseau. En 3D, le bouton gauche sélectionne et déplace, le droit ou le milieu fait glisser la vue, la molette zoome, et Maj en faisant glisser un objet change son élévation.\n\nL'aimantation et la grille aident à dessiner des mesures exactes ; taper une longueur et appuyer sur Entrée donne des côtés exacts.\n\nLe plan, les dessins d'alarme, électrique et réseau et les préférences de votre utilisateur sont conservés sur le serveur, donc un autre navigateur ou une tablette voit la même chose ; chacun a ses versions précédentes, que vous pouvez reprendre. L'apparence, la langue et les groupes de menu repliés restent dans le navigateur où vous les avez réglés.\n\nToute question - supprimer une caméra, un utilisateur, un enregistrement ou un appareil, oublier un nœud, commuter un circuit - est posée dans une boîte de la page elle-même, que le navigateur ne peut jamais faire taire. Autorisez les notifications du navigateur pour entendre et voir une nouvelle alarme critique même quand Studio est sur un autre onglet.\n\nSi quelque chose ne répond pas, vérifiez la connexion au serveur (l'état dans la barre du bas) et l'écran Système. Un message en rouge dit ce qui a échoué et pourquoi.",
      "Passa il puntatore per imparare: fermalo su un pulsante, un campo o una voce del menu per una breve spiegazione.\n\nNei progettisti: Ctrl+Z annulla, Canc elimina la selezione, le frecce spostano, Esc annulla ciò che stai facendo, R ruota l'elemento selezionato dei progettisti di allarme, elettrico e di rete. In 3D, il tasto sinistro seleziona e sposta, il destro o centrale sposta la vista, la rotella ingrandisce, e Maiusc mentre trascini un oggetto ne cambia l'altezza.\n\nAgganci e griglia aiutano a disegnare misure esatte; digitare una lunghezza e premere Invio dà lati esatti.\n\nIl progetto, i disegni di allarme, elettrico e di rete e le preferenze del tuo utente sono conservati sul server, quindi un altro browser o un tablet vede lo stesso; ognuno ha le sue versioni precedenti, che puoi recuperare. L'aspetto, la lingua e quali gruppi del menu sono compressi restano nel browser in cui li hai impostati.\n\nOgni domanda - eliminare una telecamera, un utente, una registrazione o un dispositivo, dimenticare un nodo, commutare un circuito - viene posta in una finestra della pagina stessa, che il browser non può mai silenziare. Consenti le notifiche del browser per sentire e vedere un nuovo allarme critico anche con Studio su un'altra scheda.\n\nSe qualcosa non risponde, controlla la connessione al server (lo stato nella barra in basso) e la schermata Sistema. Un messaggio in rosso dice cosa non ha funzionato e perché.",
      "ポインターを重ねて学べます：ボタン、入力欄、メニュー項目に重ねると短い説明が表示されます。\n\n設計画面では、Ctrl+Z で元に戻し、Delete で選択を削除、矢印キーで微調整、Esc で操作を取り消し、R で警報・電気・ネットワーク設計の選択した要素を回転します。3D では、左ボタンで選択と移動、右または中ボタンで視点移動、ホイールでズーム、Shift を押しながらオブジェクトをドラッグすると高さが変わります。\n\nスナップとグリッドで正確な寸法を描けます。長さを入力して Enter を押すと正確な辺になります。\n\nサイトの設計、警報・電気・ネットワークの図、ユーザーの設定はサーバーに保存されるため、別のブラウザーやタブレットでも同じ内容が見られます。それぞれ以前のバージョンがあり、戻せます。外観、言語、折りたたんだメニューグループは、設定したブラウザーに保存されます。\n\nすべての確認（カメラ、ユーザー、録画、デバイスの削除、ノードの削除、回路の切り替えなど）は、ページ内のダイアログで行われるため、ブラウザーに黙らされることはありません。ブラウザーの通知を許可すると、Studio が別のタブにあっても新しい重大アラームを音と通知で知らせます。\n\n応答しないときは、サーバーとの接続（下部バーの状態）とシステム画面を確認してください。赤いメッセージが失敗の内容と理由を示します。",
      "悬停即可了解：把指针停在任何按钮、字段或菜单项上，会显示简短说明。\n\n在设计器中：Ctrl+Z 撤销，Delete 删除所选，方向键微调，Esc 取消当前操作，R 旋转报警、电气和网络设计器中所选元素。在 3D 中，左键选择并移动，右键或中键平移，滚轮缩放，拖动对象时按住 Shift 可改变其高度。\n\n吸附和网格有助于绘制精确尺寸；输入长度并按 Enter 可得到精确边长。\n\n场地设计、报警/电气/网络图纸以及用户偏好都保存在服务器上，因此其他浏览器或平板看到的内容相同；每项都有历史版本，可以恢复。外观、语言以及菜单分组的折叠状态保存在您设置它们的浏览器中。\n\n所有确认——删除摄像头、用户、录像或设备、忘记节点、切换回路——都在页面自己的对话框中询问，浏览器无法将其屏蔽。允许浏览器通知，即使 Studio 位于其他标签页，也能听到并看到新的严重报警。\n\n若某处无响应，请检查与服务器的连接(底部栏中的状态)和系统界面。红色消息会说明失败的内容和原因。",
    ] },
];

const sectionCatalogue = (index: number): Record<string, string> => {
  const out: Record<string, string> = {};
  for (const section of HELP_SECTIONS) { out[`help_s_${section.id}`] = section.title[index]; out[`help_b_${section.id}`] = section.body[index]; }
  return out;
};

const UI: Record<string, Seven> = {
  helpButton: ["Help", "Ayuda", "Hilfe", "Aide", "Guida", "ヘルプ", "帮助"],
  helpTitle: ["Studio help", "Ayuda de Studio", "Studio-Hilfe", "Aide de Studio", "Guida di Studio", "Studio ヘルプ", "Studio 帮助"],
  helpIntro: ["A guide to every menu of the console.", "Una guía de cada menú de la consola.", "Ein Leitfaden zu jedem Menü der Konsole.", "Un guide de chaque menu de la console.", "Una guida a ogni menu della console.", "コンソールの各メニューのガイド。", "控制台各菜单的使用指南。"],
  helpSections: ["Help sections", "Secciones de la ayuda", "Hilfeabschnitte", "Sections de l'aide", "Sezioni della guida", "ヘルプの項目", "帮助章节"],
};

/** The catalogue of one language: the sections and the few labels of the window. */
export const helpCatalogue = (locale: Locale): Record<string, string> => {
  const index = order.indexOf(locale);
  const out = sectionCatalogue(index);
  for (const [key, value] of Object.entries(UI)) out[key] = value[index];
  return out;
};

/** The Help in Portuguese, one entry per menu: [title, body]. */
export const HELP_PT: Record<string, readonly [string, string]> = { ...HELP_PT_A, ...HELP_PT_B };

/** The sections of the Help in Portuguese, as catalogue entries (the labels of the window come from the Portuguese catalogue). */
export const ptHelpCatalogue = (): Record<string, string> => {
  const out: Record<string, string> = {};
  for (const [id, [title, body]] of Object.entries(HELP_PT)) { out[`help_s_${id}`] = title; out[`help_b_${id}`] = body; }
  return out;
};
